def add(a, b):
    return a + b


def subtract(a, b):
    return a - b


def multiply(a, b):
    return a * b


def divide(a, b):
    if b == 0:
        raise ZeroDivisionError("cannot divide by zero")
    return a / b


def floor_divide(a, b):
    if b == 0:
        raise ZeroDivisionError("cannot floor divide by zero")
    return a // b


def modulo(a, b):
    if b == 0:
        raise ZeroDivisionError("cannot take modulo by zero")
    return a % b


def power(a, b):
    return a ** b


def negate(a):
    return -a


def operation_table():
    return {
        "add": (add, 2),
        "subtract": (subtract, 2),
        "multiply": (multiply, 2),
        "divide": (divide, 2),
        "floor_divide": (floor_divide, 2),
        "modulo": (modulo, 2),
        "power": (power, 2),
        "negate": (negate, 1),
    }


def apply_command(value, name, operand):
    table = operation_table()
    if name not in table:
        raise KeyError("unknown operation: %s" % name)
    func, arity = table[name]
    if arity == 1:
        if operand is not None:
            raise ValueError("%s takes no operand" % name)
        return func(value)
    if operand is None:
        raise ValueError("%s requires an operand" % name)
    return func(value, operand)


def normalize(command):
    if isinstance(command, str):
        return command, None
    name = command[0]
    if len(command) == 1:
        return name, None
    return name, command[1]


def process(start, commands):
    value = start
    for command in commands:
        name, operand = normalize(command)
        value = apply_command(value, name, operand)
    return value


def describe(start, commands):
    steps = [str(start)]
    value = start
    for command in commands:
        name, operand = normalize(command)
        value = apply_command(value, name, operand)
        label = name if operand is None else "%s %s" % (name, operand)
        steps.append("--%s--> %s" % (label, value))
    return " ".join(steps)


def main():
    print(process(5, [("multiply", 2), ("subtract", 3), ("power", 2)]))
    print(describe(10, [("divide", 4), ("floor_divide", 1), ("negate",)]))
    print(describe(17, [("modulo", 5), ("add", 8)]))


if __name__ == "__main__":
    main()

