import string


def to_lowercase(text):
    return text.lower()


def remove_punctuation(text):
    return "".join(ch for ch in text if ch not in string.punctuation)


def strip_whitespace(text):
    return text.strip()


def remove_digits(text):
    return "".join(ch for ch in text if not ch.isdigit())


def collapse_spaces(text):
    return " ".join(text.split())


def reverse_string(text):
    return text[::-1]


def extract_vowels(text):
    return "".join(ch for ch in text if ch in "aeiouAEIOU")


def count_characters(text):
    return len(text)


TRANSFORMATIONS = [
    ("lowercase", to_lowercase),
    ("remove_punctuation", remove_punctuation),
    ("remove_digits", remove_digits),
    ("collapse_spaces", collapse_spaces),
    ("strip_whitespace", strip_whitespace),
    ("extract_vowels", extract_vowels),
    ("reverse", reverse_string),
]


def validate_configuration(configuration):
    known = {entry[0] for entry in TRANSFORMATIONS}
    unknown = [flag for flag in configuration if flag not in known]
    if unknown:
        raise ValueError("unknown configuration flags: " + ", ".join(sorted(unknown)))
    return set(configuration)


def normalize(text, configuration):
    flags = validate_configuration(configuration)
    result = text
    for name, operation in TRANSFORMATIONS:
        if name in flags:
            result = operation(result)
    return result


def format_report(original, configuration):
    processed = normalize(original, configuration)
    return (
        "input   : {0!r} ({1} chars)\n"
        "flags   : {2}\n"
        "output  : {3!r} ({4} chars)"
    ).format(
        original,
        count_characters(original),
        ", ".join(configuration) or "none",
        processed,
        count_characters(processed),
    )


def main():
    sample = "   Hello,   World!  It is 2024 already...  "
    cases = [
        ["lowercase", "remove_punctuation", "collapse_spaces", "strip_whitespace"],
        ["remove_digits", "collapse_spaces", "strip_whitespace"],
        ["lowercase", "remove_punctuation", "remove_digits", "extract_vowels"],
        ["strip_whitespace", "collapse_spaces", "reverse"],
        [],
    ]
    for configuration in cases:
        print(format_report(sample, configuration))
        print("-" * 40)


if __name__ == "__main__":
    main()

