def _validate(data):
    if not isinstance(data, (list, tuple)):
        raise TypeError("data must be a list or tuple of numbers")
    if not data:
        raise ValueError("data must contain at least one number")
    for value in data:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("data must contain only numbers")
    return list(data)


def mean(data):
    values = _validate(data)
    return sum(values) / len(values)


def median(data):
    values = sorted(_validate(data))
    middle = len(values) // 2
    if len(values) % 2 == 1:
        return values[middle]
    return (values[middle - 1] + values[middle]) / 2


def mode(data):
    counts = {}
    for value in _validate(data):
        counts[value] = counts.get(value, 0) + 1
    best = max(counts.values())
    return min(value for value, count in counts.items() if count == best)


def variance(data):
    values = _validate(data)
    center = mean(values)
    return sum((value - center) ** 2 for value in values) / len(values)


def standard_deviation(data):
    return variance(data) ** 0.5


def data_range(data):
    values = _validate(data)
    return max(values) - min(values)


def interquartile_range(data):
    values = sorted(_validate(data))
    half = len(values) // 2
    lower = values[:half]
    if not lower:
        return 0
    upper = values[half + 1:] if len(values) % 2 == 1 else values[half:]
    return median(upper) - median(lower)


def minimum(data):
    return min(_validate(data))


def maximum(data):
    return max(_validate(data))


def summarize(data):
    return [mean(data), median(data), mode(data), variance(data),
            standard_deviation(data), data_range(data),
            interquartile_range(data), minimum(data), maximum(data)]


def main():
    labels = ["mean", "median", "mode", "variance", "std dev", "range",
              "IQR", "min", "max"]
    for label, value in zip(labels, summarize([1, 2, 3, 4, 5])):
        print("{:<8}: {:g}".format(label, value))


if __name__ == "__main__":
    main()

