import math


def square_area(side):
    return side * side


def square_perimeter(side):
    return 4 * side


def rectangle_area(width, height):
    return width * height


def rectangle_perimeter(width, height):
    return 2 * (width + height)


def circle_area(radius):
    return math.pi * radius * radius


def circle_circumference(radius):
    return 2 * math.pi * radius


def triangle_area(a, b, c):
    s = (a + b + c) / 2
    return math.sqrt(s * (s - a) * (s - b) * (s - c))


def triangle_perimeter(a, b, c):
    return a + b + c


def validate(name, dims):
    expected = {"square": 1, "rectangle": 2, "circle": 1, "triangle": 3}
    if name not in expected:
        raise ValueError("unknown shape: %s" % name)
    if len(dims) != expected[name]:
        raise ValueError("%s needs %d dimension(s)" % (name, expected[name]))
    if any(d <= 0 for d in dims):
        raise ValueError("dimensions of %s must be positive" % name)
    if name == "triangle":
        a, b, c = sorted(dims)
        if a + b <= c:
            raise ValueError("triangle inequality violated")


def measure(shapes):
    results = []
    for name, dims in shapes:
        validate(name, dims)
        if name == "square":
            results.append((square_area(*dims), square_perimeter(*dims)))
        elif name == "rectangle":
            results.append((rectangle_area(*dims), rectangle_perimeter(*dims)))
        elif name == "circle":
            results.append((circle_area(*dims), circle_circumference(*dims)))
        else:
            results.append((triangle_area(*dims), triangle_perimeter(*dims)))
    return results


def format_report(shapes, results):
    lines = []
    for (name, dims), (area, perimeter) in zip(shapes, results):
        sizes = " x ".join("%g" % d for d in dims)
        lines.append("%-10s %-14s area=%8.3f perimeter=%8.3f"
                     % (name, sizes, area, perimeter))
    return "\n".join(lines)


def main():
    shapes = [
        ("square", (4,)),
        ("rectangle", (3, 7.5)),
        ("circle", (2.5,)),
        ("triangle", (3, 4, 5)),
    ]
    print(format_report(shapes, measure(shapes)))


if __name__ == "__main__":
    main()

