def total_sum(sequence):
    result = 0
    for value in sequence:
        result += value
    return result


def total_product(sequence):
    result = 1
    for value in sequence:
        result *= value
    return result


def count_positive(sequence):
    return sum(1 for value in sequence if value > 0)


def count_negative(sequence):
    return sum(1 for value in sequence if value < 0)


def count_even(sequence):
    return sum(1 for value in sequence if value % 2 == 0)


def count_odd(sequence):
    return sum(1 for value in sequence if value % 2 != 0)


def max_adjacent_difference(sequence):
    if len(sequence) < 2:
        return 0
    return max(abs(b - a) for a, b in zip(sequence, sequence[1:]))


def count_increasing_pairs(sequence):
    return sum(1 for a, b in zip(sequence, sequence[1:]) if b > a)


def validate(sequence):
    if not isinstance(sequence, (list, tuple)):
        raise TypeError("sequence must be a list or tuple of integers")
    for value in sequence:
