    return any(char in symbols for char in credential)


def has_no_spaces(credential):
    return not any(char.isspace() for char in credential)


def does_not_start_with_digit(credential):
    return bool(credential) and not credential[0].isdigit()


def has_no_triple_repeat(credential):
    for index in range(len(credential) - 2):
        window = credential[index:index + 3]
        if window[0] == window[1] == window[2]:
            return False
    return True


