def mask8(value):
    return value & 0xFF


def bit_and(value, operand):
    return mask8(value & operand)


def bit_or(value, operand):
    return mask8(value | operand)


def bit_xor(value, operand):
    return mask8(value ^ operand)


def bit_not(value):
    return mask8(~value)


def shift_left(value, count):
    return mask8(mask8(value) << count)


def shift_right(value, count):
    return mask8(value) >> count


def rotate_left(value, count):
    value = mask8(value)
    count %= 8
    return mask8((value << count) | (value >> (8 - count))) if count else value


def rotate_right(value, count):
    value = mask8(value)
    count %= 8
    return mask8((value >> count) | (value << (8 - count))) if count else value


def operation_table():
    return {
        "and": bit_and,
        "or": bit_or,
        "xor": bit_xor,
        "not": bit_not,
        "shl": shift_left,
        "shr": shift_right,
        "rol": rotate_left,
        "ror": rotate_right,
    }


def parse_instruction(instruction, table):
    if isinstance(instruction, str):
        name, args = instruction, ()
    else:
        name, args = instruction[0], tuple(instruction[1:])
    name = name.lower()
    if name not in table:
        raise ValueError("unknown operation: %s" % name)
    return name, args


def simulate(value, instructions):
    table = operation_table()
    value = mask8(value)
    for instruction in instructions:
        name, args = parse_instruction(instruction, table)
        value = table[name](value, *args)
    return value

