def clamp(value):
    return max(0, min(255, int(value)))


def validate(color):
    if len(color) != 3:
        raise ValueError("a color needs exactly three components: %r" % (color,))
    for component in color:
        if not isinstance(component, int) or isinstance(component, bool):
            raise TypeError("channel values must be integers: %r" % (color,))
        if component < 0 or component > 255:
            raise ValueError("channel values must be in 0..255: %r" % (color,))
    return tuple(color)


def invert(color):
    red, green, blue = validate(color)
    return (255 - red, 255 - green, 255 - blue)


def grayscale(color):
    red, green, blue = validate(color)
    level = clamp(round(0.299 * red + 0.587 * green + 0.114 * blue))
    return (level, level, level)


def boost_red(color):
    red, green, blue = validate(color)
    return (clamp(red * 1.5), green, blue)


def boost_green(color):
    red, green, blue = validate(color)
    return (red, clamp(green * 1.5), blue)


def boost_blue(color):
    red, green, blue = validate(color)
    return (red, green, clamp(blue * 1.5))


def decrease_brightness(color):
    red, green, blue = validate(color)
    return (clamp(red * 0.75), clamp(green * 0.75), clamp(blue * 0.75))


def increase_brightness(color):
    red, green, blue = validate(color)
    return (clamp(red * 1.25), clamp(green * 1.25), clamp(blue * 1.25))


def complementary(color):
    red, green, blue = validate(color)
    pivot = max(red, green, blue) + min(red, green, blue)
    return (pivot - red, pivot - green, pivot - blue)


OPERATIONS = {
    "invert": invert,
    "grayscale": grayscale,
    "boost_red": boost_red,
    "boost_green": boost_green,
    "boost_blue": boost_blue,
    "darken": decrease_brightness,
    "brighten": increase_brightness,
    "complement": complementary,
}


def adjust(pixels, operation):
    try:
        transform = OPERATIONS[operation]
    except KeyError:
        raise ValueError("unknown operation: %r" % (operation,))
    return [transform(pixel) for pixel in pixels]


def to_hex(color):
    return "#%02X%02X%02X" % validate(color)


def report(pixels, operation):
    adjusted = adjust(pixels, operation)
    lines = ["%-12s %s -> %s" % (operation, to_hex(before), to_hex(after))
             for before, after in zip(pixels, adjusted)]
    return "\n".join(lines)


def main():
    palette = [(255, 99, 71), (18, 52, 86), (0, 128, 128)]
    for operation in sorted(OPERATIONS):
        print(report(palette, operation))
        print()


if __name__ == "__main__":
    main()

