import re


def parse_bold(text):
    return re.sub(r"\*\*(.+?)\*\*", lambda m: m.group(1).upper(), text)


def parse_italic(text):
    return re.sub(r"(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)", r"_\1_", text)


def parse_inline_code(text):
    return re.sub(r"`([^`]+)`", r"\1", text)


def parse_links(text):
    return re.sub(r"\[([^\]]+)\]\(([^)]+)\)", r"\1 <\2>", text)


def parse_blockquote(line):
    match = re.match(r"^\s*>\s?(.*)$", line)
    if match:
        return "    | " + match.group(1)
    return line


def parse_horizontal_rule(line):
    if re.match(r"^\s*(?:-{3,}|\*{3,}|_{3,})\s*$", line):
        return "-" * 40
    return line


def parse_unordered_list(line):
    match = re.match(r"^(\s*)[-*+]\s+(.*)$", line)
    if match:
        indent = " " * len(match.group(1))
        return indent + "  \u2022 " + match.group(2)
    return line


def parse_ordered_list(line, counters):
    match = re.match(r"^(\s*)(\d+)[.)]\s+(.*)$", line)
    if not match:
        counters.clear()
        return line
    indent = len(match.group(1))
    counters[indent] = counters.get(indent, 0) + 1
    return " " * indent + "  %d. %s" % (counters[indent], match.group(3))


def parse_line(line, counters):
    line = parse_horizontal_rule(line)
    if line.startswith("-" * 40):
        counters.clear()
        return line
    line = parse_blockquote(line)
    line = parse_ordered_list(line, counters)
    line = parse_unordered_list(line)
    line = parse_bold(line)
    line = parse_italic(line)
    line = parse_inline_code(line)
    return parse_links(line)


def parse(document):
    if not isinstance(document, str):
        raise TypeError("document must be a string")
    counters = {}
    return "\n".join(parse_line(line, counters) for line in document.splitlines())


def main():
    sample = (
        "A **bold** claim and an *italic* aside.\n"
        "Use `parse(document)` to start.\n"
        "---\n"
        "> Quoted wisdom with **weight**.\n"
        "- first bullet\n"
        "- second bullet\n"
        "1. step one\n"
        "2. step two with [docs](http://example.com)\n"
    )
    print(parse(sample))


if __name__ == "__main__":
    main()

