def gcd(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a


def simplify(fraction):
    numerator, denominator = fraction
    if denominator == 0:
        raise ZeroDivisionError("denominator must not be zero")
    divisor = gcd(numerator, denominator)
    numerator //= divisor
    denominator //= divisor
    if denominator < 0:
        numerator, denominator = -numerator, -denominator
    return (numerator, denominator)


def add(left, right):
    a, b = left
    c, d = right
    return simplify((a * d + c * b, b * d))


def subtract(left, right):
    a, b = left
    c, d = right
    return simplify((a * d - c * b, b * d))


def multiply(left, right):
    a, b = left
    c, d = right
    return simplify((a * c, b * d))


def divide(left, right):
    a, b = left
    c, d = right
    if c == 0:
        raise ZeroDivisionError("cannot divide by the fraction 0")
    return simplify((a * d, b * c))


def to_float(fraction):
    numerator, denominator = simplify(fraction)
    return numerator / denominator


def strictly_equal(left, right):
    return simplify(left) == simplify(right)


def calculate(expressions):
    operations = {"+": add, "-": subtract, "*": multiply, "/": divide}
    results = []
    for left, symbol, right in expressions:
        if symbol not in operations:
            raise ValueError("unsupported operator: %s" % symbol)
        results.append(operations[symbol](left, right))
    return results


def format_report(expressions, results):
    return "\n".join("%d/%d %s %d/%d = %d/%d (%.4f)" % (
        l[0], l[1], s, r[0], r[1], q[0], q[1], to_float(q))
        for (l, s, r), q in zip(expressions, results))


def main():
    expressions = [((1, 2), "+", (1, 3)), ((3, 4), "-", (1, 4)),
                   ((2, 3), "*", (9, 8)), ((5, 6), "/", (10, 3))]
    results = calculate(expressions)
    print(format_report(expressions, results))
    print("third result equals 3/4:", strictly_equal(results[2], (3, 4)))


if __name__ == "__main__":
    main()

