import inspect


def average_velocity(displacement, time):
    return displacement / time


def final_velocity(initial_velocity, acceleration, time):
    return initial_velocity + acceleration * time


def displacement(initial_velocity, acceleration, time):
    return initial_velocity * time + 0.5 * acceleration * time ** 2


def acceleration(initial_velocity, final_velocity, time):
    return (final_velocity - initial_velocity) / time


def time_from_velocities(initial_velocity, final_velocity, acceleration):
    if acceleration == 0:
        raise ValueError("acceleration must be non-zero to solve for time")
    return (final_velocity - initial_velocity) / acceleration


def kinetic_energy(mass, velocity):
    return 0.5 * mass * velocity ** 2


def potential_energy(mass, height, gravity=9.81):
    return mass * height * gravity


def momentum(mass, velocity):
    return mass * velocity


FORMULAS = {
    "average_velocity": average_velocity, "final_velocity": final_velocity,
    "displacement": displacement, "acceleration": acceleration,
    "time": time_from_velocities, "kinetic_energy": kinetic_energy,
    "potential_energy": potential_energy, "momentum": momentum,
}


def collect_arguments(problem, formula):
    arguments = {}
    for name, parameter in inspect.signature(formula).parameters.items():
        if name in problem:
            arguments[name] = float(problem[name])
        elif parameter.default is inspect.Parameter.empty:
            raise ValueError("missing input %r for %r" % (name, problem["find"]))
    return arguments


def solve(problems):
    answers = []
    for problem in problems:
        formula = FORMULAS.get(problem.get("find"))
        if formula is None:
            raise ValueError("cannot solve for %r" % problem.get("find"))
        answers.append(formula(**collect_arguments(problem, formula)))
    return answers


def main():
    problems = [
        {"find": "average_velocity", "displacement": 150.0, "time": 12.0},
        {"find": "acceleration", "initial_velocity": 20.0, "final_velocity": 0.0, "time": 8.0},
        {"find": "time", "initial_velocity": 3.0, "final_velocity": 27.0, "acceleration": 6.0},
        {"find": "kinetic_energy", "mass": 70.0, "velocity": 8.5},
        {"find": "potential_energy", "mass": 2.0, "height": 45.0},
        {"find": "momentum", "mass": 1200.0, "velocity": 27.8},
    ]
    for problem, value in zip(problems, solve(problems)):
        print("%s -> %.3f" % (problem["find"], value))


if __name__ == "__main__":
    main()

