def caesar_cipher(text, shift=3):
    shifted = []
    for ch in text:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            shifted.append(chr((ord(ch) - base + shift) % 26 + base))
        else:
            shifted.append(ch)
    return "".join(shifted)


def reverse_cipher(text):
    return text[::-1]


def atbash_cipher(text):
    flipped = []
    for ch in text:
        if ch.isupper():
            flipped.append(chr(ord('Z') - (ord(ch) - ord('A'))))
        elif ch.islower():
            flipped.append(chr(ord('z') - (ord(ch) - ord('a'))))
        else:
            flipped.append(ch)
    return "".join(flipped)


def rot_thirteen_cipher(text):
    return caesar_cipher(text, 13)


def vowel_replacement_cipher(text):
    mapping = {'a': '1', 'e': '2', 'i': '3', 'o': '4', 'u': '5'}
    return "".join(mapping.get(ch.lower(), ch) for ch in text)


def consonant_capitalization_cipher(text):
    return "".join(
        ch.lower() if ch.lower() in "aeiou" else ch.upper() for ch in text
    )


def hex_encoder(text):
    return " ".join(format(byte, "02x") for byte in text.encode("utf-8"))


def binary_encoder(text):
    return " ".join(format(byte, "08b") for byte in text.encode("utf-8"))


def available_ciphers():
    return {
        "caesar": caesar_cipher, "reverse": reverse_cipher,
        "atbash": atbash_cipher, "rot13": rot_thirteen_cipher,
        "vowel": vowel_replacement_cipher,
        "consonant": consonant_capitalization_cipher,
        "hex": hex_encoder, "binary": binary_encoder,
    }


def encode(messages, cipher):
    ciphers = available_ciphers()
    key = cipher.strip().lower()
    if key not in ciphers:
        raise ValueError("unknown cipher: {}".format(cipher))
    return [ciphers[key](message) for message in messages]


def main():
    messages = ["Attack at dawn", "Hello, World!"]
    for name in available_ciphers():
        print("cipher: {}".format(name))
        for original, transformed in zip(messages, encode(messages, name)):
            print("  {!r} -> {!r}".format(original, transformed))


if __name__ == "__main__":
