def is_valid(address):
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or (len(part) > 1 and part[0] == "0"):
            return False
        if int(part) > 255:
            return False
    return True


def octets(address):
    if not is_valid(address):
        raise ValueError("invalid address: %s" % address)
    return [int(part) for part in address.split(".")]


def is_private(address):
    a, b = octets(address)[:2]
    if a == 10:
        return True
    if a == 172 and 16 <= b <= 31:
        return True
    return a == 192 and b == 168


def is_loopback(address):
    return octets(address)[0] == 127


def first_octet(address):
    return octets(address)[0]


def last_octet(address):
    return octets(address)[3]


def to_int(address):
    value = 0
    for octet in octets(address):
        value = value * 256 + octet
    return value


def from_int(value):
    if not 0 <= value <= 0xFFFFFFFF:
        raise ValueError("value out of range: %d" % value)
    return ".".join(str((value >> shift) & 0xFF) for shift in (24, 16, 8, 0))


def network_class(address):
    a = first_octet(address)
    if a < 128:
        return "A"
    if a < 192:
        return "B"
    if a < 224:
        return "C"
    if a < 240:
        return "D"
    return "E"


def analyze(addresses):
    results = []
    for address in addresses:
        if not is_valid(address):
            results.append({"address": address, "valid": False})
            continue
        value = to_int(address)
        results.append({
            "address": address,
            "valid": True,
            "private": is_private(address),
            "loopback": is_loopback(address),
            "first_octet": first_octet(address),
            "last_octet": last_octet(address),
            "integer": value,
            "roundtrip": from_int(value),
            "class": network_class(address),
        })
    return results


def format_report(results):
    lines = []
    for entry in results:
        if not entry["valid"]:
            lines.append("%-16s INVALID" % entry["address"])
            continue
        flags = []
        if entry["private"]:
            flags.append("private")
        if entry["loopback"]:
            flags.append("loopback")
        lines.append("%-16s class %s  int=%-12d %s" % (
            entry["address"], entry["class"], entry["integer"],
            ",".join(flags) or "public"))
    return "\n".join(lines)


def main():
    samples = ["192.168.1.10", "10.0.0.255", "127.0.0.1", "8.8.8.8",
               "172.20.5.1", "224.0.0.9", "256.1.1.1", "1.2.3"]
    print(format_report(analyze(samples)))
    print("from_int(3232235786) =", from_int(3232235786))


if __name__ == "__main__":
    main()

