def add_stock(inventory, name, quantity, price=None):
    item = inventory.setdefault(name, {"quantity": 0, "price": price or 0.0})
    item["quantity"] += quantity
    if price is not None:
        item["price"] = price
    return inventory


def remove_stock(inventory, name, quantity):
    if name not in inventory:
        raise KeyError("unknown item: %s" % name)
    item = inventory[name]
    if quantity > item["quantity"]:
        raise ValueError("cannot remove %d of %s" % (quantity, name))
    item["quantity"] -= quantity
    return inventory


def update_price(inventory, name, price):
    if price < 0:
        raise ValueError("price must not be negative")
    inventory[name]["price"] = price
    return inventory


def apply_discount(inventory, name, percent):
    if not 0 <= percent <= 100:
        raise ValueError("percent out of range")
    item = inventory[name]
    item["price"] = round(item["price"] * (1 - percent / 100.0), 2)
    return inventory


def total_value(inventory):
    return round(sum(i["quantity"] * i["price"] for i in inventory.values()), 2)


def most_expensive_item(inventory):
    if not inventory:
        return None
    return max(inventory.items(), key=lambda pair: pair[1]["price"])[0]


def out_of_stock_items(inventory):
    return sorted(name for name, i in inventory.items() if i["quantity"] == 0)


def items_below_threshold(inventory, threshold):
    return sorted(name for name, i in inventory.items() if i["quantity"] < threshold)


def manage(inventory, actions):
    handlers = {
        "add": add_stock,
        "remove": remove_stock,
        "price": update_price,
        "discount": apply_discount,
    }
    for action in actions:
        command, args = action[0], action[1:]
        if command not in handlers:
            raise ValueError("unsupported command: %s" % command)
        handlers[command](inventory, *args)
    return inventory


def report(inventory, threshold):
    lines = ["total value: %.2f" % total_value(inventory)]
    lines.append("most expensive: %s" % most_expensive_item(inventory))
    lines.append("out of stock: %s" % ", ".join(out_of_stock_items(inventory)))
    lines.append("below %d: %s" % (threshold, ", ".join(items_below_threshold(inventory, threshold))))
    return "\n".join(lines)


def main():
    stock = {"bolt": {"quantity": 120, "price": 0.35}, "hammer": {"quantity": 8, "price": 14.0}}
    commands = [
        ("add", "drill", 4, 89.99),
        ("add", "bolt", 30, None),
        ("remove", "hammer", 8),
        ("price", "bolt", 0.40),
        ("discount", "drill", 15),
    ]
    final = manage(stock, commands)
    for name in sorted(final):
        print("%-8s qty=%4d price=%7.2f" % (name, final[name]["quantity"], final[name]["price"]))
    print(report(final, 10))


if __name__ == "__main__":
    main()

