def trim(poly):
    coefficients = list(poly)
    while coefficients and coefficients[-1] == 0:
        coefficients.pop()
    return coefficients

def evaluate_at(poly, x):
    total = 0
    for coefficient in reversed(poly):
        total = total * x + coefficient
    return total

def add(p, q):
    length = max(len(p), len(q))
    return trim([
        (p[i] if i < len(p) else 0) + (q[i] if i < len(q) else 0)
        for i in range(length)
    ])

def subtract(p, q):
    length = max(len(p), len(q))
    return trim([
        (p[i] if i < len(p) else 0) - (q[i] if i < len(q) else 0)
        for i in range(length)
    ])

def scalar_multiply(poly, factor):
    return trim([coefficient * factor for coefficient in poly])

def multiply(p, q):
    if not trim(p) or not trim(q):
        return []
    product = [0] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            product[i + j] += a * b
    return trim(product)

def derivative(poly):
    return trim([power * poly[power] for power in range(1, len(poly))])

def integral(poly, constant=0):
    result = [constant]
    for power, coefficient in enumerate(poly):
        quotient = coefficient / (power + 1)
        result.append(int(quotient) if quotient == int(quotient) else quotient)
    return trim(result)

def degree(poly):
    return len(trim(poly)) - 1


OPERATIONS = {
    "eval": evaluate_at,
    "add": add,
    "sub": subtract,
    "scale": scalar_multiply,
    "mul": multiply,
    "deriv": derivative,
    "integ": integral,
    "degree": degree,
}

