def validate_cart(cart):
    if not isinstance(cart, (list, tuple)):
        raise TypeError("cart must be a list of item prices")
    for price in cart:
        if not isinstance(price, (int, float)) or isinstance(price, bool):
            raise TypeError("item prices must be numbers")
        if price < 0:
            raise ValueError("item prices must not be negative")
    return list(cart)


def cart_total(cart):
    return round(sum(validate_cart(cart)), 2)


def cap(amount, total):
    return round(min(amount, total), 2)


def seasonal_discount(total):
    return cap(total * 0.10, total)


def loyalty_discount(total):
    return cap(5.0, total)


def bulk_discount(total):
    if total > 100:
        return cap(total * 0.15, total)
    return 0.0


def clearance_discount(total):
    return cap(2.0, total)


def employee_discount(total):
    return cap(total * 0.50, total)


def weekend_discount(total):
    return cap(total * 0.05, total)


def first_buyer_discount(total):
    return cap(10.0, total)


def holiday_discount(total):
    return cap(total * 0.07, total)


def discount_rules():
    return [
        ("seasonal", seasonal_discount),
        ("loyalty", loyalty_discount),
        ("bulk", bulk_discount),
        ("clearance", clearance_discount),
        ("employee", employee_discount),
        ("weekend", weekend_discount),
        ("first buyer", first_buyer_discount),
        ("holiday", holiday_discount),
    ]


def evaluate(cart):
    total = cart_total(cart)
    return [rule(total) for _, rule in discount_rules()]


def format_report(cart):
    total = cart_total(cart)
    amounts = evaluate(cart)
    lines = ["Cart total: {0:.2f}".format(total)]
    for (name, _), amount in zip(discount_rules(), amounts):
        lines.append("  {0:<12} -{1:.2f}".format(name, amount))
    lines.append("Best single discount: {0:.2f}".format(max(amounts)))
    return "\n".join(lines)


def main():
    cart = [80.0, 65.0, 55.0]
    print(format_report(cart))
    print(evaluate(cart))


if __name__ == "__main__":
    main()

