import string

VOWELS = "aeiou"
OPERATORS = "+-*/%^"


def is_vowel(character):
    return character.lower() in VOWELS


def is_consonant(character):
    return character.isalpha() and character.lower() not in VOWELS


def is_digit(character):
    return character.isdigit()


def is_whitespace(character):
    return character.isspace()


def is_punctuation(character):
    return character in string.punctuation and character not in OPERATORS


def is_uppercase(character):
    return character.isupper()


def is_lowercase(character):
    return character.islower()


def is_operator(character):
    return character in OPERATORS


TRAIT_CHECKS = (
    ("vowel", is_vowel),
    ("consonant", is_consonant),
    ("digit", is_digit),
    ("whitespace", is_whitespace),
    ("punctuation", is_punctuation),
    ("uppercase", is_uppercase),
    ("lowercase", is_lowercase),
    ("operator", is_operator),
)


def validate(character):
    if not isinstance(character, str):
        raise TypeError("categorize expects a string of length 1")
    if len(character) != 1:
        raise ValueError("categorize expects exactly one character")
    return character


def categorize(character):
    symbol = validate(character)
    return [check(symbol) for _, check in TRAIT_CHECKS]


def describe(character):
    flags = categorize(character)
    traits = [name for (name, _), flag in zip(TRAIT_CHECKS, flags) if flag]
    label = ", ".join(traits) if traits else "no recognised trait"
    return "{!r}: {}".format(character, label)


def main():
    for character in ["A", "z", "7", " ", ",", "+"]:
        print(categorize(character))
        print(describe(character))


if __name__ == "__main__":
    main()

