        raise TypeError("weight must be a number")
    if weight <= 0:
        raise ValueError("weight must be positive")
    return float(weight)


def morning_meal(weight):
    return weight * 10


def evening_meal(weight):
    return weight * 12


def training_treats(weight):
    return weight * 2


def dental_chew(weight):
    return 1


def weekend_bonus(weight):
    return weight + 50


def diet_day(weight):
    return weight - 20


def liquid_intake(weight):
    return weight * 20


def vitamin_supplement(weight):
    return 5


def feed(weight):
    dog_weight = validate_weight(weight)
    return [
        morning_meal(dog_weight),
        evening_meal(dog_weight),
        training_treats(dog_weight),
        dental_chew(dog_weight),
        weekend_bonus(dog_weight),
        diet_day(dog_weight),
        liquid_intake(dog_weight),
        vitamin_supplement(dog_weight),
