    level = validate_charge(charge)
    return [
        standby_minutes(level),
        video_minutes(level),
        gaming_minutes(level),
        music_minutes(level),
        reading_minutes(level),
        navigation_minutes(level),
        call_minutes(level),
        emergency_minutes(level),
    ]


def format_duration(minutes):
    hours, mins = divmod(int(round(minutes)), 60)
    if hours:
