    return text.replace(" ", "")


def double_characters(text):
    return "".join(char * 2 for char in text)


def append_exclamation(text):
    return text + "!"


def prepend_question(text):
    return "?" + text


def repeat_twice(text):
    return text * 2


def format(text):
    styles = (
        to_upper,
        capitalize_first,
        underscore_spaces,
        strip_spaces,
        double_characters,
        append_exclamation,
        prepend_question,
        repeat_twice,
    )
    return [style(text) for style in styles]


