)


def validate_cement(cement):
    if isinstance(cement, bool) or not isinstance(cement, (int, float)):
        raise TypeError("cement must be a number")
    if cement < 0:
        raise ValueError("cement cannot be negative")
    return float(cement)


def sand(cement):
    return cement * 2


def gravel(cement):
    return cement * 3


def water(cement):
    return cement / 2


def ash(cement):
    return cement / 10


def bonding_agent():
    return 5.0


def dye():
    return 2.0


def retarder(cement):
    return cement / 100


def accelerator(cement):
    return cement / 20


def scale(cement):
    amount = validate_cement(cement)
    return [
        sand(amount),
        gravel(amount),
        water(amount),
        ash(amount),
        bonding_agent(),
        dye(),
        retarder(amount),
        accelerator(amount),
    ]


def format_batch_report(cement):
    amounts = scale(cement)
    lines = ["Batch for {0:g} units of cement:".format(cement)]
    for name, quantity in zip(MATERIALS, amounts):
        lines.append("  {0:<14}{1:>10.2f}".format(name, quantity))
    lines.append("  {0:<14}{1:>10.2f}".format("total", sum(amounts) + cement))
    return "\n".join(lines)


