def validate_weight(weight):
    if not isinstance(weight, (int, float)):
        raise TypeError("weight must be a number")
    if weight < 0:
        raise ValueError("weight must not be negative")
    return float(weight)


def ground_fee(weight):
    return 2 * weight


def express_air_fee(weight):
    return 5 * weight


def next_day_fee(weight):
    return express_air_fee(weight) + 20


def fragile_handling_fee(weight):
    return 10.0


def heavy_surcharge(weight):
    if weight > 50:
        return 15.0
    return 0.0


def rural_delivery_fee(weight):
    return 12.0


def international_base_fee(weight):
    return 50.0


def signature_required_fee(weight):
    return 3.0


def calculate(weight):
    pounds = validate_weight(weight)
    services = (
        ground_fee,
        express_air_fee,
        next_day_fee,
        fragile_handling_fee,
        heavy_surcharge,
        rural_delivery_fee,
        international_base_fee,
        signature_required_fee,
    )
    return [service(pounds) for service in services]


def service_names():
    return [
        "Ground",
        "Express Air",
        "Next Day",
        "Fragile Handling",
        "Heavy Surcharge",
        "Rural Delivery",
        "International Base",
        "Signature Required",
    ]


def format_quote(weight):
    costs = calculate(weight)
    lines = ["Shipping quote for {:.1f} lb".format(float(weight))]
    for name, cost in zip(service_names(), costs):
        lines.append("  {:<20} ${:>8.2f}".format(name, cost))
    lines.append("  {:<20} ${:>8.2f}".format("TOTAL", sum(costs)))
    return "\n".join(lines)


def main():
    for package_weight in (5, 50, 72.5):
        print(format_quote(package_weight))
        print()


if __name__ == "__main__":
    main()

