import math

SECONDS_PER_YEAR = 31557600.0
GAS_CONSTANT = 8.314
ACTIVATION_ENERGY = 60000.0
FLOW_PREFACTOR = 3.985e-13
GLEN_EXPONENT = 3
SLIDING_COEFFICIENT = 2.0e-17
DEGREE_DAY_FACTOR = 0.006
MELT_SEASON_DAYS = 120.0
SNOW_TO_WATER = 0.35


def validate_measurements(measurements):
    if len(measurements) != 7:
        raise ValueError("glacier() expects exactly 7 measurements")
    thickness, slope, density, gravity, _, snow, melt = [float(v) for v in measurements]
    if thickness <= 0.0 or density <= 0.0 or gravity <= 0.0:
        raise ValueError("thickness, density and gravity must be positive")
    if not 0.0 <= slope < 90.0:
        raise ValueError("surface slope must be in [0, 90) degrees")
    if snow < 0.0 or melt < 0.0:
        raise ValueError("snow depth and meltwater volume cannot be negative")
    return [float(v) for v in measurements]


def basal_shear_stress(thickness, slope, density, gravity):
    return density * gravity * thickness * math.sin(math.radians(slope))


def flow_rate_factor(temperature):
    kelvin = temperature + 273.15
    return FLOW_PREFACTOR * math.exp(-ACTIVATION_ENERGY / (GAS_CONSTANT * kelvin))


def internal_deformation_rate(thickness, slope, density, gravity, temperature):
    tau = basal_shear_stress(thickness, slope, density, gravity)
    factor = flow_rate_factor(temperature)
    rate = 2.0 * factor / (GLEN_EXPONENT + 1) * tau ** GLEN_EXPONENT * thickness
    return rate * SECONDS_PER_YEAR


def basal_sliding_velocity(thickness, slope, density, gravity, temperature):
    tau = basal_shear_stress(thickness, slope, density, gravity)
    warmth = 1.0 / (1.0 + math.exp(-(temperature + 2.0)))
    return SLIDING_COEFFICIENT * warmth * tau ** GLEN_EXPONENT * SECONDS_PER_YEAR


def total_ice_velocity(thickness, slope, density, gravity, temperature):
    sliding = basal_sliding_velocity(thickness, slope, density, gravity, temperature)
    deformation = internal_deformation_rate(thickness, slope, density, gravity, temperature)
    return sliding + deformation


def ice_flux(thickness, slope, density, gravity, temperature):
    return total_ice_velocity(thickness, slope, density, gravity, temperature) * thickness


def accumulation_rate(snow_depth, temperature):
    cold_bonus = 1.0 if temperature < 0.0 else 0.8
    return snow_depth * SNOW_TO_WATER * cold_bonus


def ablation_rate(temperature, meltwater_volume):
    degree_day_melt = DEGREE_DAY_FACTOR * max(temperature, 0.0) * MELT_SEASON_DAYS
    return degree_day_melt + meltwater_volume


def mass_balance(snow_depth, temperature, meltwater_volume):
    return accumulation_rate(snow_depth, temperature) - ablation_rate(temperature, meltwater_volume)


def glacier(measurements):
    thickness, slope, density, gravity, temperature, snow, melt = validate_measurements(measurements)
    return [
        basal_sliding_velocity(thickness, slope, density, gravity, temperature),
        internal_deformation_rate(thickness, slope, density, gravity, temperature),
        total_ice_velocity(thickness, slope, density, gravity, temperature),
        ice_flux(thickness, slope, density, gravity, temperature),
        basal_shear_stress(thickness, slope, density, gravity),
        accumulation_rate(snow, temperature),
        ablation_rate(temperature, melt),
        mass_balance(snow, temperature, melt),
    ]


def format_report(results):
    labels = ["basal sliding (m/yr)", "deformation (m/yr)", "total velocity (m/yr)",
              "ice flux (m2/yr)", "shear stress (Pa)", "accumulation (m w.e.)",
              "ablation (m w.e.)", "mass balance (m w.e.)"]
    return "\n".join("{:<24}{:>14.4f}".format(name, value)
                     for name, value in zip(labels, results))


def main():
    field_site = [220.0, 4.5, 917.0, 9.81, -3.5, 1.8, 0.45]
    print(format_report(glacier(field_site)))


if __name__ == "__main__":
    main()

