        volume_percentage(vol_solute, vol_solution),
        mole_fraction_solute(moles, total_moles),
        mole_fraction_solvent(moles, total_moles),
        parts_per_million(mass_solute, mass_solvent),
        parts_per_billion(mass_solute, mass_solvent),
    ]


