"""HVAC ventilation and load analysis."""

SENSIBLE_FACTOR = 1.08
LATENT_FACTOR = 4840.0
LABELS = (
    "Sensible heat (BTU/h)",
    "Latent heat (BTU/h)",
    "Total heat (BTU/h)",
    "Airflow (CFM)",
    "Air changes per hour",
    "Mixed air temperature (F)",
    "Cooling load (BTU/h)",
    "Heating load (BTU/h)",
)

def sensible_heat(cfm, delta_t):
    return SENSIBLE_FACTOR * cfm * delta_t

def latent_heat(cfm, delta_w):
    return LATENT_FACTOR * cfm * delta_w

def total_heat(q_sensible, q_latent):
    return q_sensible + q_latent

def airflow_cfm(mass_flow_lb_per_hr, specific_volume):
    return mass_flow_lb_per_hr * specific_volume / 60.0

def air_changes_per_hour(cfm, room_volume):
    return cfm * 60.0 / room_volume

def mixed_air_temperature(indoor_t, outdoor_t, outdoor_fraction):
    return outdoor_fraction * outdoor_t + (1.0 - outdoor_fraction) * indoor_t

def cooling_load(cfm, mixed_t, indoor_t, w_outdoor, w_indoor, outdoor_fraction):
    q_s = sensible_heat(cfm, mixed_t - indoor_t)
    q_l = latent_heat(cfm, outdoor_fraction * (w_outdoor - w_indoor))
    load = total_heat(q_s, q_l)
    return load if load > 0.0 else 0.0

def heating_load(cfm, mixed_t, indoor_t):
    load = sensible_heat(cfm, indoor_t - mixed_t)
    return load if load > 0.0 else 0.0

def validate_readings(readings):
    if len(readings) != 8:
        raise ValueError("readings must contain exactly 8 values")
    volume, _, _, _, _, specific_volume, mass_flow, fraction = readings
    if volume <= 0.0 or specific_volume <= 0.0:
        raise ValueError("room volume and specific volume must be positive")
    if mass_flow < 0.0:
        raise ValueError("supply mass flow cannot be negative")
    if not 0.0 <= fraction <= 1.0:
        raise ValueError("outdoor air fraction must be between 0 and 1")

def ventilation(readings):
    validate_readings(readings)
    volume, indoor_t, outdoor_t, w_in, w_out, spec_vol, mass_flow, fraction = readings
    cfm = airflow_cfm(mass_flow, spec_vol)
    q_s = sensible_heat(cfm, outdoor_t - indoor_t)
    q_l = latent_heat(cfm, w_out - w_in)
    mixed_t = mixed_air_temperature(indoor_t, outdoor_t, fraction)
    return [
        q_s,
        q_l,
        total_heat(q_s, q_l),
        cfm,
        air_changes_per_hour(cfm, volume),
        mixed_t,
        cooling_load(cfm, mixed_t, indoor_t, w_out, w_in, fraction),
        heating_load(cfm, mixed_t, indoor_t),
    ]

def format_report(metrics):
    return "\n".join(
        "{0:<28}{1:>12.2f}".format(label, value)
        for label, value in zip(LABELS, metrics)
    )

def main():
    room = [8000.0, 75.0, 95.0, 0.0092, 0.0155, 13.5, 4000.0, 0.25]
    metrics = ventilation(room)
    print(format_report(metrics))


if __name__ == "__main__":
    main()

