def crude_birth_rate(births, population):
    return births / population * 1000


def crude_death_rate(deaths, population):
    return deaths / population * 1000


def rate_of_natural_increase(births, deaths, population):
    return (crude_birth_rate(births, population) - crude_death_rate(deaths, population)) / 10


def net_migration_rate(immigrants, emigrants, population):
    return (immigrants - emigrants) / population * 1000


def population_growth_rate(births, deaths, immigrants, emigrants, population):
    natural = rate_of_natural_increase(births, deaths, population)
    return natural + net_migration_rate(immigrants, emigrants, population) / 10


def doubling_time(growth_rate):
    if growth_rate <= 0:
        return float('inf')
    return 70 / growth_rate


def dependency_ratio(population, working_age):
    return (population - working_age) / working_age * 100


def infant_mortality_rate(infant_deaths, births):
    if births == 0:
        return 0.0
    return infant_deaths / births * 1000


def validate(census):
    if len(census) != 7:
        raise ValueError('census must contain exactly 7 values')
    population, births, deaths, immigrants, emigrants, working_age, infant_deaths = census
    if population <= 0 or working_age <= 0:
        raise ValueError('population and working age population must be positive')
    if min(births, deaths, immigrants, emigrants, infant_deaths) < 0:
        raise ValueError('event counts cannot be negative')
    if working_age > population:
        raise ValueError('working age population cannot exceed total population')
    return census


def demographics(census):
    population, births, deaths, immigrants, emigrants, working_age, infant_deaths = validate(census)
    growth = population_growth_rate(births, deaths, immigrants, emigrants, population)
    return [
        crude_birth_rate(births, population),
        crude_death_rate(deaths, population),
        rate_of_natural_increase(births, deaths, population),
        net_migration_rate(immigrants, emigrants, population),
        growth,
        doubling_time(growth),
        dependency_ratio(population, working_age),
        infant_mortality_rate(infant_deaths, births),
    ]


def report(census):
    labels = [
        'Crude birth rate (per 1000)',
        'Crude death rate (per 1000)',
        'Rate of natural increase (%)',
        'Net migration rate (per 1000)',
        'Population growth rate (%)',
        'Doubling time (years)',
        'Dependency ratio (%)',
        'Infant mortality rate (per 1000 births)',
    ]
    lines = []
    for label, value in zip(labels, demographics(census)):
        lines.append('{:<40}{:>10.2f}'.format(label, value))
    return '\n'.join(lines)


def main():
    census = [1000000, 14200, 8600, 5400, 2100, 640000, 78]
    print(report(census))


if __name__ == '__main__':
    main()

