def validate_stats(stats):
    if len(stats) != 7:
        raise ValueError("expected 7 values: runs, outs, balls, boundaries, conceded, wickets, overs")
    for value in stats:
        if not isinstance(value, int) or value < 0:
            raise ValueError("every statistic must be a non-negative integer")
    return list(stats)


def safe_ratio(numerator, denominator):
    if denominator == 0:
        return 0.0
    return numerator / denominator


def batting_average(runs, outs):
    return round(safe_ratio(runs, outs), 2)


def strike_rate(runs, balls_faced):
    return round(safe_ratio(runs * 100, balls_faced), 2)


def boundary_percentage(boundaries, balls_faced):
    return round(safe_ratio(boundaries * 100, balls_faced), 2)


def bowling_average(runs_conceded, wickets):
    return round(safe_ratio(runs_conceded, wickets), 2)


def economy_rate(runs_conceded, overs):
    return round(safe_ratio(runs_conceded, overs), 2)


def bowling_strike_rate(overs, wickets):
    return round(safe_ratio(overs * 6, wickets), 2)


def balls_per_wicket(balls_faced, outs):
    return round(safe_ratio(balls_faced, outs), 2)


def runs_per_over(runs, balls_faced):
    return round(safe_ratio(runs * 6, balls_faced), 2)


def cricket(stats):
    runs, outs, balls, boundaries, conceded, wickets, overs = validate_stats(stats)
    return [
        batting_average(runs, outs),
        strike_rate(runs, balls),
        boundary_percentage(boundaries, balls),
        bowling_average(conceded, wickets),
        economy_rate(conceded, overs),
        bowling_strike_rate(overs, wickets),
        balls_per_wicket(balls, outs),
        runs_per_over(runs, balls),
    ]


def format_report(metrics):
    labels = [
        "Batting average", "Batting strike rate", "Boundary percentage",
        "Bowling average", "Economy rate", "Bowling strike rate",
        "Balls per wicket", "Runs per over",
    ]
    lines = []
    for label, value in zip(labels, metrics):
        lines.append("{:<20}: {:>8.2f}".format(label, value))
    return "\n".join(lines)


def main():
    career = [13288, 350, 16240, 1600, 3480, 96, 580]
    metrics = cricket(career)
    print(metrics)
    print(format_report(metrics))


if __name__ == "__main__":
    main()

