def parse_measurements(measurements):
    lanes, vehicle_count, period_hours, travel_times, segment_length = measurements
    if lanes < 1:
        raise ValueError("a highway segment must have at least one lane")
    if vehicle_count < 1:
        raise ValueError("at least one vehicle must be observed")
    if period_hours <= 0:
        raise ValueError("the observation period must be positive")
    if not travel_times or any(t <= 0 for t in travel_times):
        raise ValueError("every average travel time must be positive")
    if segment_length <= 0:
        raise ValueError("the segment length must be positive")
    return lanes, vehicle_count, period_hours, list(travel_times), segment_length


def flow_rate(vehicle_count, period_hours, lanes):
    return vehicle_count / (period_hours * lanes)


def space_mean_speed(segment_length, travel_times):
    return len(travel_times) * segment_length / sum(travel_times)


def time_mean_speed(segment_length, travel_times):
    speeds = [segment_length / t for t in travel_times]
    return sum(speeds) / len(speeds)


def traffic_density(flow, mean_speed):
    return flow / mean_speed


def free_flow_speed(segment_length, travel_times):
    return segment_length / min(travel_times)


def jam_density(density, mean_speed, ffs):
    reserve = 1.0 - mean_speed / ffs
    if reserve <= 0:
        raise ValueError("uniform speeds cannot calibrate a Greenshields jam density")
    return density / reserve


def maximum_capacity(ffs, k_jam):
    return ffs * k_jam / 4.0


def headway(flow):
    return 3600.0 / flow


def traffic(measurements):
    lanes, vehicles, hours, times, length = parse_measurements(measurements)
    flow = flow_rate(vehicles, hours, lanes)
    u_space = space_mean_speed(length, times)
    u_time = time_mean_speed(length, times)
    density = traffic_density(flow, u_space)
    ffs = free_flow_speed(length, times)
    k_jam = jam_density(density, u_space, ffs)
    capacity = maximum_capacity(ffs, k_jam)
    return [flow, density, u_space, u_time, ffs, k_jam, capacity, headway(flow)]


def format_report(states):
    labels = ["Flow rate (veh/h/lane)", "Density (veh/km/lane)",
              "Space mean speed (km/h)", "Time mean speed (km/h)",
              "Free flow speed (km/h)", "Jam density (veh/km/lane)",
              "Maximum capacity (veh/h/lane)", "Headway (s)"]
    return "\n".join("%-30s %10.3f" % pair for pair in zip(labels, states))


def main():
    measurements = [3, 1800, 0.5, [0.020, 0.024, 0.018, 0.022, 0.026], 1.2]
    states = traffic(measurements)
    print(format_report(states))
    print("\nRaw state vector:", [round(value, 3) for value in states])


if __name__ == "__main__":
    main()

