def validate_state(state):
    if len(state) != 6:
        raise ValueError("state must contain 6 values: p1, v1, t1, v2, gamma, n")
    p1, v1, t1, v2, gamma, n = (float(value) for value in state)
    if min(p1, v1, t1, v2, n) <= 0.0:
        raise ValueError("pressure, volumes, temperature and moles must be positive")
    if gamma <= 1.0:
        raise ValueError("heat capacity ratio must be greater than 1")
    return p1, v1, t1, v2, gamma, n


def boyles_law_final_pressure(p1, v1, v2):
    return p1 * v1 / v2


def charles_law_final_volume(v1, t1, t2):
    return v1 * t2 / t1


def gay_lussac_law_final_pressure(p1, t1, t2):
    return p1 * t2 / t1


def avogadro_law_total_moles(n1, v1, v2):
    return n1 * v2 / v1


def internal_energy_change(n, cv, delta_t):
    return n * cv * delta_t


def isobaric_work(p, v1, v2):
    return p * (v2 - v1)


def heat_transferred(n, cp, delta_t):
    return n * cp * delta_t


def adiabatic_final_temperature(t1, v1, v2, gamma):
    return t1 * (v1 / v2) ** (gamma - 1.0)


