import math


PARAMETER_NAMES = (
    "total ammonia nitrogen", "water temperature", "potential of hydrogen",
    "atmospheric pressure", "initial fish weight", "final fish weight",
    "feed given", "dissolved oxygen", "dissolved oxygen after incubation",
    "culture days", "titrant volume", "titrant normality",
    "edta volume", "edta molarity", "sample volume", "dilution factor",
)


def validate_readings(readings):
    if len(readings) != len(PARAMETER_NAMES):
        raise ValueError("expected %d readings, got %d" % (len(PARAMETER_NAMES), len(readings)))
    values = []
    for name, value in zip(PARAMETER_NAMES, readings):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError("%s must be numeric" % name)
        values.append(float(value))
    if not 0.0 <= values[2] <= 14.0:
        raise ValueError("potential of hydrogen out of range")
    if values[9] <= 0 or values[14] <= 0:
        raise ValueError("culture days and sample volume must be positive")
    return values


def unionized_ammonia(tan, temperature, ph):
    pka = 0.09018 + 2729.92 / (temperature + 273.15)
    return tan / (1.0 + 10.0 ** (pka - ph))


def oxygen_saturation(dissolved_oxygen, temperature, pressure):
    solubility = (14.652 - 0.41022 * temperature + 0.007991 * temperature ** 2
                  - 0.000077774 * temperature ** 3)
    return dissolved_oxygen / (solubility * pressure / 760.0) * 100.0


def total_alkalinity(titrant_volume, normality, sample_volume):
    return titrant_volume * normality * 50000.0 / sample_volume


def carbon_dioxide(alkalinity, ph):
    return 2.0 * alkalinity * 10.0 ** (6.3 - ph)


def total_hardness(edta_volume, edta_molarity, sample_volume):
    return edta_volume * edta_molarity * 100090.0 / sample_volume


def biological_oxygen_demand(do_initial, do_final, dilution_factor):
    return (do_initial - do_final) * dilution_factor


def feed_conversion_ratio(feed_given, initial_weight, final_weight):
    gain = final_weight - initial_weight
    if gain <= 0:
        raise ValueError("no biomass gain, feed conversion ratio undefined")
    return feed_given / gain


def specific_growth_rate(initial_weight, final_weight, days):
    return (math.log(final_weight) - math.log(initial_weight)) / days * 100.0


def aquaculture(readings):
    (tan, temperature, ph, pressure, weight_i, weight_f, feed, oxygen,
     oxygen_end, days, titrant, normality, edta, molarity, sample, dilution) = validate_readings(readings)
    alkalinity = total_alkalinity(titrant, normality, sample)
    return [
        unionized_ammonia(tan, temperature, ph),
        oxygen_saturation(oxygen, temperature, pressure),
        carbon_dioxide(alkalinity, ph),
        alkalinity,
        total_hardness(edta, molarity, sample),
        biological_oxygen_demand(oxygen, oxygen_end, dilution),
        feed_conversion_ratio(feed, weight_i, weight_f),
        specific_growth_rate(weight_i, weight_f, days),
    ]


def format_report(metrics):
    labels = ("Un-ionized ammonia (mg/L)", "Oxygen saturation (%)",
              "Free carbon dioxide (mg/L)", "Total alkalinity (mg/L CaCO3)",
              "Total hardness (mg/L CaCO3)", "BOD (mg/L)",
              "Feed conversion ratio", "Specific growth rate (%/day)")
    return "\n".join("  %-30s %8.3f" % (label, value)
                     for label, value in zip(labels, metrics))


def main():
    tanks = {
        "Tank A": [1.5, 28.0, 7.8, 755.0, 25.0, 48.0, 32.0, 6.4, 3.1,
                   30.0, 4.2, 0.02, 6.5, 0.01, 50.0, 5.0],
        "Tank B": [2.8, 31.0, 8.4, 748.0, 30.0, 51.5, 44.0, 5.1, 1.9,
                   30.0, 3.0, 0.02, 9.0, 0.01, 50.0, 5.0],
    }
    for name, readings in tanks.items():
        print(name)
        print(format_report(aquaculture(readings)))


if __name__ == "__main__":
    main()

