def line_height(base_font_size, scale_factor):
    return round(base_font_size * scale_factor, 3)


def paragraph_spacing(base_font_size, scale_factor):
    return round(base_font_size * scale_factor * 0.75, 3)


def optimal_line_length(content_width, base_font_size):
    average_glyph_width = base_font_size * 0.5
    return int(content_width / average_glyph_width)


def em_space_width(base_font_size):
    return round(float(base_font_size), 3)


def en_space_width(base_font_size):
    return round(base_font_size / 2.0, 3)


def x_height_ratio(ascender, descender, base_font_size):
    return round((ascender - descender) / base_font_size, 3)


def modular_scale_ratio(base_font_size, scale_factor, steps=3):
    return round(base_font_size * scale_factor ** steps, 3)


def golden_ratio_column_width(content_width):
    return round(content_width / 1.618033988749895, 3)


def validate(settings):
    if len(settings) < 4:
        raise ValueError("settings needs base size, ascender, descender and width")
    base_font_size, ascender, descender = settings[0], settings[1], settings[2]
    content_width = settings[3]
    scale_factor = settings[4] if len(settings) > 4 else 1.5
    if base_font_size <= 0 or content_width <= 0:
        raise ValueError("base font size and content width must be positive")
    if ascender <= descender:
        raise ValueError("ascender must exceed descender")
    return base_font_size, ascender, descender, content_width, scale_factor


def typography(settings):
    base, ascender, descender, width, scale = validate(settings)
    return [
        line_height(base, scale),
        paragraph_spacing(base, scale),
        optimal_line_length(width, base),
        em_space_width(base),
        en_space_width(base),
        x_height_ratio(ascender, descender, base),
        modular_scale_ratio(base, scale),
        golden_ratio_column_width(width),
    ]


def format_report(dimensions):
    labels = [
        "line height (pt)",
        "paragraph spacing (pt)",
        "optimal line length (chars)",
        "em space (pt)",
        "en space (pt)",
        "x-height ratio",
        "modular scale (3 steps, pt)",
        "golden ratio column (px)",
    ]
    lines = []
    for label, value in zip(labels, dimensions):
        lines.append("{:<30}{:>12}".format(label, value))
    return "\n".join(lines)


def main():
    settings = [16, 11.6, -3.4, 800, 1.5]
    dimensions = typography(settings)
    print(format_report(dimensions))
    print("\nraw values:", dimensions)


if __name__ == "__main__":
    main()

