METAL_DENSITIES = {"Fe": 7.87, "C": 2.26, "Cr": 7.19, "Ni": 8.90, "Mn": 7.44}
ELEMENT_ORDER = ("Fe", "C", "Cr", "Ni", "Mn")


def validate_composition(composition):
    if len(composition) != len(ELEMENT_ORDER):
        raise ValueError("composition must list %d weight percentages" % len(ELEMENT_ORDER))
    weights = [float(value) for value in composition]
    if min(weights) < 0.0:
        raise ValueError("weight percentages cannot be negative")
    total = sum(weights)
    if abs(total - 100.0) > 0.5:
        raise ValueError("weight percentages must total 100, got %.2f" % total)
    return dict(zip(ELEMENT_ORDER, weights))


def tensile_strength(composition):
    alloy = validate_composition(composition)
    return (350.0 + 900.0 * alloy["C"] + 8.0 * alloy["Cr"]
            + 5.0 * alloy["Ni"] + 12.0 * alloy["Mn"])


def yield_strength(composition):
    alloy = validate_composition(composition)
    return 0.58 * tensile_strength(composition) + 9.0 * alloy["Mn"]


def brinell_hardness(composition):
    return tensile_strength(composition) / 3.4


def elongation_percentage(composition):
    alloy = validate_composition(composition)
    raw = 34.0 - 14.0 * alloy["C"] - 0.45 * alloy["Cr"] - 0.2 * alloy["Mn"]
    return max(raw, 2.0)


def thermal_conductivity(composition):
    alloy = validate_composition(composition)
    return 80.0 - 30.0 * alloy["C"] - 0.95 * alloy["Cr"] - 0.6 * alloy["Ni"]


def electrical_resistivity(composition):
    alloy = validate_composition(composition)
    return (0.098 + 0.25 * alloy["C"] + 0.021 * alloy["Cr"]
            + 0.015 * alloy["Ni"] + 0.030 * alloy["Mn"])


def melting_point(composition):
    alloy = validate_composition(composition)
    return (1538.0 - 100.0 * alloy["C"] + 2.0 * alloy["Cr"]
            - 6.0 * alloy["Ni"] - 5.0 * alloy["Mn"])


def density(composition):
    alloy = validate_composition(composition)
    inverse = sum(weight / METAL_DENSITIES[name] for name, weight in alloy.items())
    return 100.0 / inverse


def metallurgy(composition):
    return [round(tensile_strength(composition), 2),
            round(yield_strength(composition), 2),
            round(brinell_hardness(composition), 1),
            round(elongation_percentage(composition), 2),
            round(thermal_conductivity(composition), 2),
            round(electrical_resistivity(composition), 4),
            round(melting_point(composition), 1),
            round(density(composition), 3)]


def format_report(composition, properties):
    labels = ("Tensile strength (MPa)", "Yield strength (MPa)", "Brinell hardness (HB)",
              "Elongation (%)", "Thermal conductivity (W/m.K)", "Electrical resistivity (uOhm.m)",
              "Melting point (C)", "Density (g/cm3)")
    blend = ", ".join("%s %.2f%%" % pair for pair in zip(ELEMENT_ORDER, composition))
    lines = ["Alloy blend: " + blend]
    for label, value in zip(labels, properties):
        lines.append("%-30s %s" % (label, value))
    return "\n".join(lines)


def main():
    steel = [96.5, 0.4, 1.0, 1.2, 0.9]
    print(format_report(steel, metallurgy(steel)))


if __name__ == "__main__":
    main()

