import math


def true_airspeed(indicated_airspeed, altitude, oat_celsius):
    standard_temp = 15.0 - 0.0019812 * altitude
    density_ratio = (1 + 0.0019812 * altitude / 288.15) ** -4.2561
    temp_correction = (oat_celsius + 273.15) / (standard_temp + 273.15)
    return indicated_airspeed / math.sqrt(density_ratio / temp_correction)


def wind_correction_angle(tas, wind_speed, wind_direction, course):
    wind_angle = math.radians(wind_direction - course)
    crosswind = wind_speed * math.sin(wind_angle)
    return math.degrees(math.asin(max(-1.0, min(1.0, crosswind / tas))))


