def percentage(part, whole):
    if whole <= 0:
        return 0.0
    return round(100.0 * part / whole, 1)


def validate(stats):
    if len(stats) != 9:
        raise ValueError("expected 9 raw counts, got %d" % len(stats))
    if any(count < 0 for count in stats):
        raise ValueError("raw counts cannot be negative")
    fgm, fga, tpm, tpa, ftm, fta = stats[:6]
    if fgm > fga or tpm > tpa or ftm > fta:
        raise ValueError("made shots cannot exceed attempts")
    if tpm > fgm or tpa > fga:
        raise ValueError("three pointers must be part of the field goals")
    return tuple(stats)


def field_goal_pct(fgm, fga):
    return percentage(fgm, fga)


def three_point_pct(tpm, tpa):
    return percentage(tpm, tpa)


def free_throw_pct(ftm, fta):
    return percentage(ftm, fta)


def points_scored(fgm, tpm, ftm):
    return 2 * (fgm - tpm) + 3 * tpm + ftm


def true_shooting_pct(points, fga, fta):
    return percentage(points, 2.0 * (fga + 0.44 * fta))


def effective_fg_pct(fgm, tpm, fga):
    return percentage(fgm + 0.5 * tpm, fga)


def missed_shots(fgm, fga, ftm, fta):
    return (fga - fgm) + (fta - ftm)


def offensive_rebound_rate(rebounds, misses):
    return percentage(min(rebounds, misses), rebounds)


def defensive_rebound_rate(rebounds, misses):
    return percentage(rebounds - min(rebounds, misses), rebounds)


def assist_turnover_ratio(assists, turnovers):
    if turnovers == 0:
        return float(assists)
    return round(assists / float(turnovers), 2)


def profile(stats):
    fgm, fga, tpm, tpa, ftm, fta, reb, ast, tov = validate(stats)
    points = points_scored(fgm, tpm, ftm)
    misses = missed_shots(fgm, fga, ftm, fta)
    return [
        field_goal_pct(fgm, fga),
        three_point_pct(tpm, tpa),
        free_throw_pct(ftm, fta),
        true_shooting_pct(points, fga, fta),
        effective_fg_pct(fgm, tpm, fga),
        offensive_rebound_rate(reb, misses),
        defensive_rebound_rate(reb, misses),
        assist_turnover_ratio(ast, tov),
    ]


def format_report(name, values):
    labels = ["FG%", "3P%", "FT%", "TS%", "eFG%", "OREB%", "DREB%", "AST/TO"]
    body = ", ".join("%s %.2f" % pair for pair in zip(labels, values))
    return "%-10s %s" % (name, body)


def main():
    roster = {
        "Guard": (9, 19, 3, 8, 4, 5, 5, 8, 3),
        "Center": (7, 11, 0, 0, 6, 10, 14, 2, 4),
    }
    for name in sorted(roster):
        print(format_report(name, profile(roster[name])))


if __name__ == "__main__":
    main()

