SILK_GSM = 40.0
CHIFFON_GSM = 30.0
LINEN_GSM = 180.0
COTTON_GSM = 150.0
DENIM_GSM = 340.0
CANVAS_GSM = 400.0
WOOL_GSM = 250.0
FLEECE_GSM = 300.0


def validate_area(area):
    value = float(area)
    if value < 0.0:
        raise ValueError("cut area cannot be negative: %r" % (area,))
    return value


def silk(area):
    return validate_area(area) * SILK_GSM


def chiffon(area):
    return validate_area(area) * CHIFFON_GSM


def linen(area):
    return validate_area(area) * LINEN_GSM


def cotton(area):
    return validate_area(area) * COTTON_GSM


def denim(area):
    return validate_area(area) * DENIM_GSM


def canvas(area):
    return validate_area(area) * CANVAS_GSM


def wool(area):
    return validate_area(area) * WOOL_GSM


def fleece(area):
    return validate_area(area) * FLEECE_GSM


def heaviness(area):
    return [silk(area), chiffon(area), linen(area), cotton(area),
            denim(area), canvas(area), wool(area), fleece(area)]


def fabric_names():
    return ["silk", "chiffon", "linen", "cotton",
            "denim", "canvas", "wool", "fleece"]


def format_report(area, weights):
    lines = ["Cut area: %.2f m^2" % area]
    for name, grams in zip(fabric_names(), weights):
        lines.append("%-8s %9.1f g  (%.3f kg)" % (name, grams, grams / 1000.0))
    lines.append("%-8s %9.1f g" % ("total", sum(weights)))
    return "\n".join(lines)


def heaviest_fabric(weights):
    pairs = list(zip(fabric_names(), weights))
    return max(pairs, key=lambda pair: pair[1])


def main():
