def watts_to_horsepower(watts):
    return watts / 745.699872


def validate_measurements(measurements):
    names = ("bore", "stroke", "cylinders", "clearance volume", "torque", "rpm",
             "indicated mean effective pressure", "fuel power", "air flow")
    if len(measurements) != len(names):
        raise ValueError("expected %d engine parameters, got %d"
                         % (len(names), len(measurements)))
    for name, value in zip(names, measurements):
        if value <= 0:
            raise ValueError("%s must be positive, got %r" % (name, value))
    return tuple(float(value) for value in measurements)


def displacement_volume(bore_mm, stroke_mm, cylinders):
    bore_cm = bore_mm / 10.0
    stroke_cm = stroke_mm / 10.0
    return 3.141592653589793 / 4.0 * bore_cm ** 2 * stroke_cm * cylinders


def compression_ratio(displacement_cc, cylinders, clearance_cc):
    swept_per_cylinder = displacement_cc / cylinders
    return (swept_per_cylinder + clearance_cc) / clearance_cc


def brake_horsepower(torque_nm, rpm):
    watts = 2.0 * 3.141592653589793 * rpm * torque_nm / 60.0
    return watts_to_horsepower(watts)


def indicated_horsepower(imep_kpa, displacement_cc, rpm):
    power_cycles_per_second = rpm / 60.0 / 2.0
    kilowatts = imep_kpa * (displacement_cc / 1.0e6) * power_cycles_per_second
    return watts_to_horsepower(kilowatts * 1000.0)


def friction_horsepower(indicated_hp, brake_hp):
    return indicated_hp - brake_hp


def mechanical_efficiency(brake_hp, indicated_hp):
    return brake_hp / indicated_hp * 100.0


def thermal_efficiency(brake_hp, fuel_power_kw):
    brake_kilowatts = brake_hp / watts_to_horsepower(1000.0)
    return brake_kilowatts / fuel_power_kw * 100.0


def volumetric_efficiency(air_flow_lps, displacement_cc, rpm):
    theoretical_lps = displacement_cc / 1000.0 * (rpm / 60.0 / 2.0)
    return air_flow_lps / theoretical_lps * 100.0


def dyno(measurements):
    bore, stroke, cylinders, clearance, torque, rpm, imep, fuel_kw, air_flow = \
        validate_measurements(measurements)
    displacement = displacement_volume(bore, stroke, cylinders)
    ratio = compression_ratio(displacement, cylinders, clearance)
    bhp = brake_horsepower(torque, rpm)
    ihp = indicated_horsepower(imep, displacement, rpm)
    fhp = friction_horsepower(ihp, bhp)
    mech = mechanical_efficiency(bhp, ihp)
    thermal = thermal_efficiency(bhp, fuel_kw)
    volumetric = volumetric_efficiency(air_flow, displacement, rpm)
    return [displacement, ratio, bhp, ihp, fhp, mech, thermal, volumetric]


def format_report(metrics):
    labels = ("Displacement (cc)", "Compression ratio (:1)", "Brake horsepower (hp)",
              "Indicated horsepower (hp)", "Friction horsepower (hp)",
              "Mechanical efficiency (%)", "Thermal efficiency (%)",
              "Volumetric efficiency (%)")
    return "\n".join("%-26s %10.3f" % pair for pair in zip(labels, metrics))


def main():
    engine = (86.0, 86.0, 4, 45.0, 200.0, 4000.0, 1400.0, 250.0, 60.0)
    print(format_report(dyno(engine)))


if __name__ == "__main__":
    main()

