def validate_volume(volume):
    """Return the volume as a float, rejecting anything unusable."""
    if isinstance(volume, bool) or not isinstance(volume, (int, float)):
        raise TypeError("volume must be a number of cubic centimetres")
    if volume < 0:
        raise ValueError("volume cannot be negative")
    return float(volume)


def balsa(volume):
    """Mass in grams of balsa (specific gravity 0.16)."""
    return validate_volume(volume) * 0.16


def cedar(volume):
    """Mass in grams of cedar (specific gravity 0.38)."""
    return validate_volume(volume) * 0.38


def pine(volume):
    """Mass in grams of pine (specific gravity 0.50)."""
    return validate_volume(volume) * 0.50


def mahogany(volume):
    """Mass in grams of mahogany (specific gravity 0.55)."""
    return validate_volume(volume) * 0.55


def oak(volume):
    """Mass in grams of oak (specific gravity 0.75)."""
    return validate_volume(volume) * 0.75


