def validate_specs(specs):
    aperture, focal_length, eyepiece = specs
    if aperture <= 0 or focal_length <= 0 or eyepiece <= 0:
        raise ValueError("aperture, focal length and eyepiece must be positive")
    return float(aperture), float(focal_length), float(eyepiece)


def focal_ratio(aperture, focal_length):
    return focal_length / aperture


def visual_magnification(focal_length, eyepiece):
    return focal_length / eyepiece


def true_field_of_view(magnification, apparent_field=50.0):
    return apparent_field / magnification


def exit_pupil(aperture, magnification):
    return aperture / magnification


def light_gathering_power(aperture, eye_pupil=7.0):
    return (aperture / eye_pupil) ** 2


def dawes_limit(aperture):
    return 116.0 / aperture


def rayleigh_criterion(aperture):
    return 138.0 / aperture


def lowest_useful_magnification(aperture, eye_pupil=7.0):
    return aperture / eye_pupil


def optics(specs):
    aperture, focal_length, eyepiece = validate_specs(specs)
    magnification = visual_magnification(focal_length, eyepiece)
    return [
        focal_ratio(aperture, focal_length),
        magnification,
        true_field_of_view(magnification),
        exit_pupil(aperture, magnification),
        light_gathering_power(aperture),
        dawes_limit(aperture),
        rayleigh_criterion(aperture),
        lowest_useful_magnification(aperture),
    ]


def format_report(specs, metrics):
    labels = [
        "focal ratio (f/)",
        "magnification (x)",
        "true field of view (deg)",
        "exit pupil (mm)",
        "light gathering power (x eye)",
        "Dawes limit (arcsec)",
        "Rayleigh criterion (arcsec)",
        "lowest useful magnification (x)",
    ]
    header = "Telescope {0:.0f}mm f={1:.0f}mm with {2:.0f}mm eyepiece".format(*specs)
    lines = [header]
    for label, value in zip(labels, metrics):
        lines.append("  {0:<32}{1:>10.3f}".format(label, value))
    return "\n".join(lines)


def main():
    for specs in [(203.0, 2032.0, 25.0), (80.0, 600.0, 10.0)]:
        print(format_report(specs, optics(specs)))


if __name__ == "__main__":
    main()

