def validate_duration(minutes):
    value = float(minutes)
    if value <= 0:
        raise ValueError("total time in bed must be a positive number of minutes")
    return value


def stage_n1(minutes):
    return validate_duration(minutes) * 0.05


def stage_n2(minutes):
    return validate_duration(minutes) * 0.50


def stage_n3(minutes):
    return validate_duration(minutes) * 0.20


def rem_sleep(minutes):
    return validate_duration(minutes) * 0.20


def brief_awakenings(minutes):
    return validate_duration(minutes) * 0.03


def sleep_latency(minutes):
    return validate_duration(minutes) * 0.02


def total_sleep_time(minutes):
    time_in_bed = validate_duration(minutes)
    return time_in_bed - sleep_latency(time_in_bed) - brief_awakenings(time_in_bed)


def sleep_efficiency(minutes):
    time_in_bed = validate_duration(minutes)
    return total_sleep_time(time_in_bed) / time_in_bed * 100.0


def polysomnography(minutes):
    return [
        stage_n1(minutes),
        stage_n2(minutes),
        stage_n3(minutes),
        rem_sleep(minutes),
        brief_awakenings(minutes),
        sleep_latency(minutes),
        total_sleep_time(minutes),
        sleep_efficiency(minutes),
    ]


def format_report(minutes):
    labels = [
        "NREM stage 1",
        "NREM stage 2",
        "NREM stage 3",
        "REM sleep",
        "Brief awakenings",
        "Sleep latency",
        "Total sleep time",
        "Sleep efficiency",
    ]
    results = polysomnography(minutes)
    lines = ["Polysomnography estimate for {:.1f} minutes in bed".format(float(minutes))]
    for label, value in zip(labels, results):
        unit = "%" if label == "Sleep efficiency" else "min"
        lines.append("{:<18}{:>8.1f} {}".format(label, value, unit))
    return "\n".join(lines)


def main():
    for night in (420.0, 480.0, 510.5):
        print(format_report(night))
        print()


if __name__ == "__main__":
    main()

