import math

G = 9.81
AIR_DENSITY = 1.225
CABIN_DRAG_COEFF = 1.2
CABIN_AREA = 8.0
PASSENGER_MASS = 75.0
WIND_SHUTDOWN_SPEED = 30.0
ROPE_STRENGTH_PER_LINEAR_KG = 1.6e5
METRIC_NAMES = ["cable sag", "midspan tension", "tower reaction", "hauling power",
                "max cabin speed", "transport rate", "braking distance",
                "crosswind drift", "safety factor"]
METRIC_UNITS = ["m", "N", "N", "W", "m/s", "pax/h", "m", "m", "-"]

def validate_inputs(tramway):
    if len(tramway) != 9:
        raise ValueError("tramway must contain exactly nine values")
    if any(value <= 0 for value in tramway):
        raise ValueError("all tramway parameters must be positive")

def horizontal_tension(cabin_mass, passenger_load):
    return (cabin_mass + passenger_load) * G

def cable_sag(span, linear_mass, tension):
    return linear_mass * G * span ** 2 / (8.0 * tension)

def midspan_tension(span, linear_mass, tension):
    vertical = linear_mass * G * span / 2.0
    return math.hypot(tension, vertical)

def tower_reaction(span, cabin_mass, passenger_load, linear_mass, tension):
    vertical = (linear_mass * span / 2.0 + cabin_mass + passenger_load) * G
    return math.hypot(vertical, tension)

def tractive_force(torque, radius):
    return torque / radius

def rope_length(span, elevation):
    return math.hypot(span, elevation)

def grade_resistance(cabin_mass, passenger_load, span, elevation):
    return (cabin_mass + passenger_load) * G * elevation / rope_length(span, elevation)

def max_cabin_speed(force, resistance, wind_speed):
    net = force - resistance
    if net <= 0.0:
        return 0.0
    drag_factor = 0.5 * AIR_DENSITY * CABIN_DRAG_COEFF * CABIN_AREA
    derate = max(0.0, 1.0 - wind_speed / WIND_SHUTDOWN_SPEED)
    return math.sqrt(net / drag_factor) * derate

def hauling_power(force, speed):
    return force * speed

def transport_rate(passenger_load, span, elevation, speed):
    if speed <= 0.0:
        return 0.0
    seats = math.floor(passenger_load / PASSENGER_MASS)
    round_trip = 2.0 * rope_length(span, elevation) / speed
    return seats * 3600.0 / round_trip

def braking_distance(cabin_mass, passenger_load, speed, braking_force, resistance):
    return (cabin_mass + passenger_load) * speed ** 2 / (2.0 * (braking_force + resistance))

def crosswind_displacement(wind_speed, span, tension):
    wind_force = 0.5 * AIR_DENSITY * CABIN_DRAG_COEFF * CABIN_AREA * wind_speed ** 2
    return wind_force * span / (4.0 * tension)

def safety_factor(linear_mass, tension):
    return linear_mass * ROPE_STRENGTH_PER_LINEAR_KG / tension

def assess(tramway):
    validate_inputs(tramway)
    span, cabin_mass, load, linear_mass, wind, elevation, torque, radius, brake_force = tramway
    tension = horizontal_tension(cabin_mass, load)
    sag = cable_sag(span, linear_mass, tension)
    peak_tension = midspan_tension(span, linear_mass, tension)
    reaction = tower_reaction(span, cabin_mass, load, linear_mass, tension)
    resistance = grade_resistance(cabin_mass, load, span, elevation)
    force = tractive_force(torque, radius)
    speed = max_cabin_speed(force, resistance, wind)
    power = hauling_power(force, speed)
    rate = transport_rate(load, span, elevation, speed)
    stopping = braking_distance(cabin_mass, load, speed, brake_force, resistance)
    drift = crosswind_displacement(wind, span, tension)
    margin = safety_factor(linear_mass, peak_tension)
    return [sag, peak_tension, reaction, power, speed, rate, stopping, drift, margin]

def format_report(metrics):
    lines = []
    for name, unit, value in zip(METRIC_NAMES, METRIC_UNITS, metrics):
        lines.append("{:<18}{:>12.3f} {}".format(name, value, unit))
    return "\n".join(lines)

def main():
    tramway = [1000, 2000, 1000, 5, 20, 200, 50000, 2, 10000]
    metrics = assess(tramway)
    print(format_report(metrics))
    print("capacity: {:.1f} passengers per hour at {:.2f} m sag".format(metrics[5], metrics[0]))


if __name__ == "__main__":
    main()

