import math

GRAVITY = 9.80665
HEEL_ANGLE_DEG = 10.0
PROPERTY_NAMES = (
    "displaced volume (m^3)",
    "buoyant force (N)",
    "ballast water mass (kg)",
    "reserve buoyancy (%)",
    "center of buoyancy above keel (m)",
    "metacentric height (m)",
    "righting moment (N.m)",
    "trim angle (deg)",
    "crush depth pressure (Pa)",
)


def validate(vessel):
    if len(vessel) != 8:
        raise ValueError("vessel must contain exactly eight numbers")
    values = [float(item) for item in vessel]
    if any(value <= 0.0 for value in values):
        raise ValueError("every vessel parameter must be strictly positive")
    return values


def displaced_volume(diameter, length):
    return math.pi * 0.25 * diameter ** 2 * length


def buoyant_force(volume, density):
    return volume * density * GRAVITY


def ballast_water_mass(capacity_litres, density):
    return capacity_litres * 1.0e-3 * density


def reserve_buoyancy(volume, density, internal_mass, ballast_mass):
    displaced_mass = volume * density
    return 100.0 * (displaced_mass - internal_mass - ballast_mass) / displaced_mass


def center_of_buoyancy(diameter):
    return diameter * 0.5


def metacentric_height(kb, cg_height):
    return kb - cg_height


def righting_moment(volume, density, gm):
    return buoyant_force(volume, density) * gm * math.sin(math.radians(HEEL_ANGLE_DEG))


def trim_angle(volume, density, ballast_mass, length, diameter, gm):
    trimming_moment = ballast_mass * GRAVITY * length * 0.25
    longitudinal_gm = gm + length ** 2 / (12.0 * diameter)
    return math.degrees(math.atan(trimming_moment /
                                  (buoyant_force(volume, density) * longitudinal_gm)))


def crush_depth_pressure(yield_stress, thickness, diameter):
    return yield_stress * thickness / (diameter * 0.5)


def evaluate(vessel):
    (diameter, length, thickness, yield_stress,
     internal_mass, ballast_capacity, density, cg_height) = validate(vessel)
    volume = displaced_volume(diameter, length)
    force = buoyant_force(volume, density)
    ballast = ballast_water_mass(ballast_capacity, density)
    reserve = reserve_buoyancy(volume, density, internal_mass, ballast)
    kb = center_of_buoyancy(diameter)
    gm = metacentric_height(kb, cg_height)
    moment = righting_moment(volume, density, gm)
    trim = trim_angle(volume, density, ballast, length, diameter, gm)
    crush = crush_depth_pressure(yield_stress, thickness, diameter)
    return [volume, force, ballast, reserve, kb, gm, moment, trim, crush]


def format_report(metrics):
    lines = []
    for name, value in zip(PROPERTY_NAMES, metrics):
        lines.append("{:<34}{:>16.3f}".format(name, value))
    return "\n".join(lines)


def main():
    vessel = [10, 100, 0.05, 500e6, 3e6, 5e5, 1025, 4]
    metrics = evaluate(vessel)
    print(format_report(metrics))
    print("stable" if metrics[5] > 0.0 else "unstable")


if __name__ == "__main__":
    main()

