def divide(numerator, denominator):
    if denominator == 0:
        return 0.0
    return numerator / denominator


def validate_stats(stats):
    if len(stats) != 10:
        raise ValueError("stats must contain exactly ten values")
    for value in stats:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("stats must contain only integers and floats")
        if value < 0:
            raise ValueError("stats must not contain negative values")
    return [float(value) for value in stats]


def applause_rate(likes, followers):
    return divide(likes, followers)


def amplification_rate(shares, followers):
    return divide(shares, followers)


def conversation_rate(comments, followers):
    return divide(comments, followers)


def virality_rate(shares, impressions):
    return divide(shares, impressions)


def engagement_rate(likes, shares, comments, followers):
    return divide(likes + shares + comments, followers)


def click_through_rate(clicks, impressions):
    return divide(clicks, impressions)


def bounce_rate(bounces, clicks):
    return divide(bounces, clicks)


def cost_per_click(spend, clicks):
    return divide(spend, clicks)


def cost_per_impression(spend, impressions):
    return divide(spend, impressions)


def evaluate(stats):
    followers, likes, shares, comments, impressions, clicks, bounces, spend = validate_stats(stats)[:8]
    return [
        applause_rate(likes, followers),
        amplification_rate(shares, followers),
        conversation_rate(comments, followers),
        virality_rate(shares, impressions),
        engagement_rate(likes, shares, comments, followers),
        click_through_rate(clicks, impressions),
        bounce_rate(bounces, clicks),
        cost_per_click(spend, clicks),
        cost_per_impression(spend, impressions),
    ]


def format_report(stats, metrics):
    names = [
        "Applause rate", "Amplification rate", "Conversation rate",
        "Virality rate", "Engagement rate", "Click through rate",
        "Bounce rate", "Cost per click", "Cost per impression",
    ]
    posts, viewers = int(stats[9]), int(stats[8])
    lines = ["%d posts seen by %d unique viewers" % (posts, viewers)]
    for name, value in zip(names, metrics):
        if name.startswith("Cost"):
            lines.append("%-20s $%.4f" % (name, value))
        else:
            lines.append("%-20s %.2f%%" % (name, value * 100))
    return "\n".join(lines)


def main():
    stats = [1000, 200, 50, 20, 5000, 100, 40, 50.0, 4000, 10]
    metrics = evaluate(stats)
    print(metrics)
    print(format_report(stats, metrics))


if __name__ == "__main__":
    main()

