def validate_ingredients(ingredients):
    values = list(ingredients)
    if len(values) != 8:
        raise ValueError("exactly eight ingredient values are required")
    for value in values:
        if not isinstance(value, (int, float)):
            raise TypeError("ingredient values must be numeric")
    if min(values[:7]) < 0:
        raise ValueError("volumes, densities and thickness must be non-negative")
    if values[6] <= 0:
        raise ValueError("dry film thickness must be positive")
    if not 0 < values[7] <= 1:
        raise ValueError("transfer efficiency must lie in (0, 1]")
    return values


def total_volume(pigment_volume, binder_volume, solvent_volume):
    return pigment_volume + binder_volume + solvent_volume


def pigment_mass(pigment_volume, pigment_density):
    return pigment_volume * pigment_density


def binder_mass(binder_volume, binder_density):
    return binder_volume * binder_density


def solvent_content(mixture_volume, pigment_volume, binder_volume):
    return mixture_volume - pigment_volume - binder_volume


def volume_solids_percentage(pigment_volume, binder_volume, mixture_volume):
    return (pigment_volume + binder_volume) / mixture_volume * 100.0


def wet_film_thickness(dry_film_thickness, solids_percent, transfer_efficiency):
    return dry_film_thickness / (solids_percent / 100.0 * transfer_efficiency)


def theoretical_spread_rate(solids_percent, dry_film_thickness):
    return solids_percent / 100.0 * 1000.0 / dry_film_thickness


def pigment_volume_concentration(pigment_volume, binder_volume):
    return pigment_volume / (pigment_volume + binder_volume) * 100.0


def voc_content(solvent_volume, solvent_density, mixture_volume):
    return solvent_volume * solvent_density * 1000.0 / mixture_volume


def mix(ingredients):
    (pig_vol, pig_den, bin_vol, bin_den,
     sol_vol, sol_den, dft, efficiency) = validate_ingredients(ingredients)
    volume = total_volume(pig_vol, bin_vol, sol_vol)
    solids = volume_solids_percentage(pig_vol, bin_vol, volume)
    return [
        volume,
        pigment_mass(pig_vol, pig_den),
        binder_mass(bin_vol, bin_den),
        solvent_content(volume, pig_vol, bin_vol),
        solids,
        wet_film_thickness(dft, solids, efficiency),
        theoretical_spread_rate(solids, dft),
        pigment_volume_concentration(pig_vol, bin_vol),
        voc_content(sol_vol, sol_den, volume),
    ]


def format_report(metrics):
    labels = (
        "Total volume (L)",
        "Pigment mass (kg)",
        "Binder mass (kg)",
        "Solvent volume (L)",
        "Volume solids (%)",
        "Wet film thickness (um)",
        "Theoretical spread rate (m2/L)",
        "Pigment volume concentration (%)",
        "VOC content (g/L)",
    )
    width = max(len(label) for label in labels)
    return "\n".join(
        "{0:<{1}} : {2:.2f}".format(label, width, value)
        for label, value in zip(labels, metrics)
    )


def main():
    formula = [2, 3, 4, 1.2, 1, 0.8, 50, 0.6]
    print(format_report(mix(formula)))


main()

