LABELS = [
    "dot gain (%)",
    "total ink limit (%)",
    "maximum screen ruling (lpi)",
    "ideal resolution (dpi)",
    "minimum cylinder pressure (psi)",
    "blanket compression (mm)",
    "expected plate wear (%)",
    "ink tack sequence (steps)",
    "drying time (min)",
]


def validate_parameters(parameters):
    if len(parameters) != 7:
        raise ValueError("configure() expects exactly seven parameters")
    for value in parameters:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("all press parameters must be numbers")
    return [float(value) for value in parameters]


def dot_gain(viscosity, speed, humidity):
    return round(8.0 + viscosity * 0.4 + speed / 4000.0 + humidity * 0.05, 2)


def total_ink_limit(brightness, weight):
    limit = 240.0 + brightness * 0.8 - weight * 0.1
    return round(min(limit, 340.0), 2)


def maximum_screen_ruling(brightness, weight):
    ruling = 60.0 + brightness + (weight - 120.0) * 0.05
    return round(min(ruling, 200.0), 2)


def ideal_resolution(ruling):
    return round(ruling * 16.0, 2)


def minimum_cylinder_pressure(weight, viscosity):
    return round(30.0 + weight * 0.1 + viscosity * 0.5, 2)


def blanket_compression(weight, pressure):
    return round(0.05 + weight * 0.0002 + pressure * 0.0005, 4)


def expected_plate_wear(plate_age, speed, humidity):
    return round(plate_age * 2.0 + speed / 2000.0 + (humidity - 45.0) * 0.1, 2)


