import math


MAX_PPO2 = 1.4
FN2_AIR = 0.79
METRIC_NAMES = (
    "FO2", "FN2", "MOD (m)", "EAD (m)", "ppO2 (bar)",
    "SAC (bar/min)", "RMV (L/min)", "NDL (min)", "Gas required (L)",
)


def validate_dive(dive):
    if len(dive) != 7:
        raise ValueError("a dive plan needs exactly seven numbers")
    o2_pct, depth, bottom_time, cylinder, p_start, p_end, surface_rate = dive
    if not 21.0 <= o2_pct <= 100.0:
        raise ValueError("oxygen percentage must lie between 21 and 100")
    if depth <= 0 or bottom_time <= 0:
        raise ValueError("depth and bottom time must be positive")
    if cylinder <= 0 or surface_rate <= 0:
        raise ValueError("cylinder volume and surface rate must be positive")
    if p_end >= p_start:
        raise ValueError("ending pressure must be lower than starting pressure")
    return [float(value) for value in dive]


def ambient_pressure(depth):
    return depth / 10.0 + 1.0


def fraction_oxygen(o2_pct):
    return o2_pct / 100.0


def fraction_nitrogen(o2_pct):
    return 1.0 - fraction_oxygen(o2_pct)


def max_operating_depth(o2_pct):
    return (MAX_PPO2 / fraction_oxygen(o2_pct) - 1.0) * 10.0


def equivalent_air_depth(o2_pct, depth):
    return fraction_nitrogen(o2_pct) * ambient_pressure(depth) / FN2_AIR * 10.0 - 10.0


def ppo2_at_depth(o2_pct, depth):
    return fraction_oxygen(o2_pct) * ambient_pressure(depth)


def sac_rate(p_start, p_end, bottom_time):
    return (p_start - p_end) / bottom_time


def respiratory_minute_volume(p_start, p_end, cylinder, depth, bottom_time):
    used_litres = (p_start - p_end) * cylinder
    return used_litres / (bottom_time * ambient_pressure(depth))


def no_deco_limit(o2_pct, depth):
    ead = max(equivalent_air_depth(o2_pct, depth), 1.0)
    return min(200.0, 400.0 / math.pow(ead / 10.0, 3.0))


def total_gas_required(surface_rate, depth, bottom_time):
    return surface_rate * ambient_pressure(depth) * bottom_time * 1.5


def plan(dive):
    o2_pct, depth, bottom_time, cylinder, p_start, p_end, surface_rate = validate_dive(dive)
    return [
        fraction_oxygen(o2_pct),
        fraction_nitrogen(o2_pct),
        max_operating_depth(o2_pct),
        equivalent_air_depth(o2_pct, depth),
        ppo2_at_depth(o2_pct, depth),
        sac_rate(p_start, p_end, bottom_time),
        respiratory_minute_volume(p_start, p_end, cylinder, depth, bottom_time),
        no_deco_limit(o2_pct, depth),
        total_gas_required(surface_rate, depth, bottom_time),
    ]


def format_plan(results):
    return "\n".join(
        "{:<18}{:>10.2f}".format(name, value)
        for name, value in zip(METRIC_NAMES, results)
    )


def main():
    dive = [32, 30, 40, 11, 200, 50, 20]
    results = plan(dive)
    print(format_plan(results))
    if results[4] > MAX_PPO2:
        print("WARNING: target depth exceeds the MOD for this blend")


if __name__ == "__main__":
    main()

