STEEL_DENSITY_KG_PER_MM3 = 7.85e-6
MELTING_ENTHALPY_J_PER_MM3 = 10.5
REFERENCE_HEAT_INPUT_J_PER_MM = 1000.0


def validate_parameters(parameters):
    if len(parameters) != 8:
        raise ValueError("exactly eight process parameters are required")
    voltage, current, travel_speed, efficiency, diameter, feed_speed, carbon, manganese = parameters
    if min(voltage, current, travel_speed, diameter, feed_speed) <= 0:
        raise ValueError("voltage, current, speeds and wire diameter must be positive")
    if not 0.0 < efficiency <= 1.0:
        raise ValueError("thermal efficiency must lie in (0, 1]")
    if carbon < 0 or manganese < 0:
        raise ValueError("alloy contents cannot be negative")
    return voltage, current, travel_speed, efficiency, diameter, feed_speed, carbon, manganese


def arc_energy(voltage, current, travel_speed):
    return voltage * current / travel_speed


def heat_input(energy, efficiency):
    return energy * efficiency


def carbon_equivalent(carbon, manganese):
    return carbon + manganese / 6.0


def preheat_temperature(equivalent):
    if equivalent <= 0.25:
        return 0.0
    return 350.0 * (equivalent - 0.25) ** 0.5


def cooling_time(input_energy, preheat):
    kilojoules = input_energy / 1000.0
    factor = 6700.0 - 5.0 * preheat
    span = 1.0 / (500.0 - preheat) - 1.0 / (800.0 - preheat)
    return factor * kilojoules * span


def deposition_rate(diameter, feed_speed):
    area = 3.141592653589793 * diameter ** 2 / 4.0
    volume_per_minute = area * feed_speed * 1000.0
    return volume_per_minute * STEEL_DENSITY_KG_PER_MM3 * 60.0


def wire_feed_speed_ratio(feed_speed, travel_speed):
    return feed_speed / (travel_speed * 60.0 / 1000.0)


def melting_efficiency(rate, voltage, current):
    volume_per_second = rate / STEEL_DENSITY_KG_PER_MM3 / 3600.0
    return volume_per_second * MELTING_ENTHALPY_J_PER_MM3 / (voltage * current)


def travel_speed_efficiency(voltage, current, efficiency, travel_speed):
    nominal = voltage * current * efficiency / REFERENCE_HEAT_INPUT_J_PER_MM
    return nominal / travel_speed


def evaluate(parameters):
    voltage, current, speed, efficiency, diameter, feed, carbon, manganese = validate_parameters(parameters)
    energy = arc_energy(voltage, current, speed)
    absorbed = heat_input(energy, efficiency)
    equivalent = carbon_equivalent(carbon, manganese)
    preheat = preheat_temperature(equivalent)
    rate = deposition_rate(diameter, feed)
    return [energy, absorbed, cooling_time(absorbed, preheat), rate,
            wire_feed_speed_ratio(feed, speed), melting_efficiency(rate, voltage, current),
            equivalent, preheat, travel_speed_efficiency(voltage, current, efficiency, speed)]


def format_report(metrics):
    labels = ["Arc energy (J/mm)", "Heat input (J/mm)", "Cooling time t8/5 (s)",
              "Deposition rate (kg/h)", "Wire feed / travel ratio", "Melting efficiency",
              "Carbon equivalent", "Required preheat (C)", "Travel speed efficiency"]
    return "\n".join("%-26s %10.3f" % pair for pair in zip(labels, metrics))


def main():
    parameters = [24, 200, 5, 0.8, 1.2, 10, 0.2, 1.5]
    print(format_report(evaluate(parameters)))


main()

