import math

QUARTZ_INVERSION = 573.0
CLAY_DENSITY = 1.9
CLAY_SPECIFIC_HEAT = 1.05
GLAZE_MATURATION_TEMP = 1280.0
METRIC_LABELS = [
    "total heating time (h)", "soaking duration (h)", "cooling time (h)",
    "max thermal gradient (C/h)", "clay shrinkage (%)", "final fired volume (L)",
    "energy consumption (kWh)", "quartz inversion stress", "glaze maturation index",
]

def validate(firing):
    if len(firing) != 7:
        raise ValueError("firing schedule needs exactly seven values")
    for value in firing:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError("firing values must be numeric")
    initial, peak, heat_rate, cool_rate, soak, volume, insulation = firing
    if peak <= initial:
        raise ValueError("peak temperature must exceed initial temperature")
    if heat_rate <= 0 or cool_rate <= 0:
        raise ValueError("ramp rates must be positive")
    if soak < 0 or volume <= 0 or insulation <= 0:
        raise ValueError("soak, volume and insulation must be non-negative")
    return tuple(float(v) for v in firing)

def heating_time(initial, peak, heat_rate):
    return (peak - initial) / heat_rate

def soaking_duration(soak, peak):
    return soak * (1.0 + max(0.0, peak - GLAZE_MATURATION_TEMP) / 1000.0)

def cooling_time(initial, peak, cool_rate):
    return (peak - initial) / cool_rate

def max_thermal_gradient(heat_rate, cool_rate, insulation):
    return max(heat_rate, cool_rate) * (1.0 + 1.0 / insulation)

def clay_shrinkage(peak, soak):
    if peak <= QUARTZ_INVERSION:
        return 0.0
    vitrification = (peak - QUARTZ_INVERSION) / 100.0 * 1.2
    return min(15.0, vitrification + 0.15 * soak)

def final_volume(volume, shrinkage):
    return volume * (1.0 - shrinkage / 100.0) ** 3

def energy_consumption(initial, peak, volume, soak, insulation):
    mass = volume * CLAY_DENSITY
    sensible = mass * CLAY_SPECIFIC_HEAT * (peak - initial) / 3600.0
    holding = (peak - initial) * soak / (10.0 * insulation)
    return sensible + holding

def quartz_stress(peak, heat_rate, cool_rate, insulation):
    if peak <= QUARTZ_INVERSION:
        return 0.0
    crossings = (heat_rate + cool_rate) / 2.0
    return crossings / (insulation * 10.0)

def glaze_maturation(peak, soak):
    ratio = peak / GLAZE_MATURATION_TEMP
    return min(100.0, 100.0 * ratio ** 3 * (1.0 - math.exp(-max(soak, 0.0) / 2.0)))

def analyze(firing):
    initial, peak, heat_rate, cool_rate, soak, volume, insulation = validate(firing)
    shrinkage = clay_shrinkage(peak, soak)
    return [
        heating_time(initial, peak, heat_rate),
        soaking_duration(soak, peak),
        cooling_time(initial, peak, cool_rate),
        max_thermal_gradient(heat_rate, cool_rate, insulation),
        shrinkage,
        final_volume(volume, shrinkage),
        energy_consumption(initial, peak, volume, soak, insulation),
        quartz_stress(peak, heat_rate, cool_rate, insulation),
        glaze_maturation(peak, soak),
    ]

def format_report(results):
    return "\n".join(
        "%-28s %10.3f" % (label, value)
        for label, value in zip(METRIC_LABELS, results)
    )

def main():
    firing = [20, 1200, 150, 200, 2, 50, 5]
    print(format_report(analyze(firing)))


if __name__ == "__main__":
    main()

