import math

PSYCHROMETRIC_CONSTANT = 0.6686
CFM_TO_M3_PER_MIN = 0.0283168
SNOW_DENSITY = 400.0
AIR_PER_LITRE = 0.04
NIGHT_SHIFT_HOURS = 12.0
METRIC_NAMES = [
    "wet bulb temperature (C)", "required water flow (L/min)",
    "compressed air volume (m3/min)", "snow production rate (m3/h)",
    "energy consumption (kW)", "expected snow depth (m)",
    "acreage coverage time (h)", "evaporative cooling loss (L/min)",
    "total operational cost ($)",
]


def saturation_vapor_pressure(temp_c):
    return 6.112 * math.exp(17.62 * temp_c / (243.12 + temp_c))


def wet_bulb_temperature(temp_c, humidity):
    target = saturation_vapor_pressure(temp_c) * humidity / 100.0
    low, high = temp_c - 40.0, temp_c
    while high - low > 1e-6:
        mid = (low + high) / 2.0
        depression = PSYCHROMETRIC_CONSTANT * (temp_c - mid) * (1 + 0.00115 * mid)
        if saturation_vapor_pressure(mid) - depression > target:
            high = mid
        else:
            low = mid
    return (low + high) / 2.0


def required_water_flow(pump_capacity, wet_bulb, water_temp):
    margin = max(0.0, (-wet_bulb - 1.0) / 6.0)
    warmth_penalty = 1.0 - 0.02 * max(0.0, water_temp)
    return pump_capacity * min(1.0, margin) * warmth_penalty


def compressed_air_volume(compressor_capacity, water_flow):
    return min(compressor_capacity, water_flow * AIR_PER_LITRE)


def snow_production_rate(water_flow, air_volume, wet_bulb):
    if water_flow <= 0.0:
        return 0.0
    nucleation = min(1.0, air_volume / (water_flow * AIR_PER_LITRE))
    quality = min(0.95, 0.6 + 0.04 * (-wet_bulb))
    return water_flow * 60.0 / SNOW_DENSITY * nucleation * quality


def energy_consumption(water_flow, air_volume):
    return water_flow * 0.035 + air_volume * 2.2


def expected_snow_depth(snow_rate, area):
    return snow_rate * NIGHT_SHIFT_HOURS / area


def acreage_coverage_time(snow_rate, area, target_depth):
    if snow_rate <= 0.0:
        return float("inf")
    return area * target_depth / snow_rate


def evaporative_cooling_loss(water_flow, temp_c, humidity, wet_bulb):
    return water_flow * 0.002 * (temp_c - wet_bulb) * (1.0 - humidity / 100.0)


def total_operational_cost(power_kw, hours, electricity_rate):
    if math.isinf(hours):
        return float("inf")
    return power_kw * hours * electricity_rate


def evaluate(resort):
    if len(resort) != 8:
        raise ValueError("resort must contain eight values")
    temp, humidity, pump, compressor, area, depth, rate, water_temp = resort
    if not 0.0 < humidity <= 100.0:
        raise ValueError("relative humidity must be within (0, 100]")
    if area <= 0.0:
        raise ValueError("target slope area must be positive")
    wet_bulb = wet_bulb_temperature(temp, humidity)
    flow = required_water_flow(pump, wet_bulb, water_temp)
    air = compressed_air_volume(compressor * CFM_TO_M3_PER_MIN, flow)
    snow = snow_production_rate(flow, air, wet_bulb)
    power = energy_consumption(flow, air)
    hours = acreage_coverage_time(snow, area, depth)
    return [round(value, 3) for value in (
        wet_bulb, flow, air, snow, power,
        expected_snow_depth(snow, area), hours,
        evaporative_cooling_loss(flow, temp, humidity, wet_bulb),
        total_operational_cost(power, hours, rate),
    )]


def format_report(metrics):
    return "\n".join("%-34s %12.3f" % pair for pair in zip(METRIC_NAMES, metrics))


def main():
    resort = [-5, 40, 500, 2000, 10000, 0.5, 0.1, 2]
    print(format_report(evaluate(resort)))


if __name__ == "__main__":
    main()

