def numerical_aperture(refractive_index, half_angle_deg):
    return refractive_index * math.sin(math.radians(half_angle_deg))


def rayleigh_limit(wavelength_nm, aperture):
    return 0.61 * wavelength_nm / aperture


def abbe_limit(wavelength_nm, aperture):
    return wavelength_nm / (2.0 * aperture)


def total_magnification(objective_mag, eyepiece_mag):
    return objective_mag * eyepiece_mag


def depth_of_focus(wavelength_nm, refractive_index, aperture):
    return refractive_index * (wavelength_nm / 1000.0) / (aperture ** 2)


def field_of_view(field_number, objective_mag):
    return field_number / objective_mag


def exit_pupil(aperture, magnification):
    return 500.0 * aperture / magnification


def working_distance(refractive_index, objective_mag, aperture):
    return 100.0 * refractive_index / (objective_mag * aperture)


def flux_transmission(condenser_aperture, aperture):
    return (min(condenser_aperture, aperture) / aperture) ** 2


def validate(optics):
    values = [float(item) for item in optics]
    if len(values) != 7:
        raise ValueError("evaluate() expects exactly seven numeric inputs")
