import math


def validate_apiary(apiary):
    if len(apiary) != 7:
        raise ValueError("apiary must contain exactly seven numbers")
    values = tuple(float(v) for v in apiary)
    if min(values[0], values[1], values[2]) <= 0 or values[3] < 0:
        raise ValueError("population, distance, flora and hours must be valid")
    return values


def foraging_bees(population, temperature):
    activity = 0.0 if temperature > 40.0 else min(1.0, max(0.0, (temperature - 10.0) / 15.0))
    return int(round(population * 0.35 * activity))


def nectar_collection(foragers, distance, flora, hours):
    trips = hours * 60.0 / (distance * 8.0 + 5.0)
    load_kg = 0.00004 * (flora / 100.0)
    return foragers * trips * load_kg


def honey_yield(nectar_kg, nectar_water=0.80, honey_water=0.18):
    return nectar_kg * (1.0 - nectar_water) / (1.0 - honey_water)


def water_evaporated(nectar_kg):
    return nectar_kg - honey_yield(nectar_kg)


def beeswax_production(honey_kg):
    return honey_kg / 8.0


def supers_required(daily_honey_kg, super_capacity=18.0):
    return int(math.ceil(daily_honey_kg * 30.0 / super_capacity))


def winter_stores(population, temperature):
    cold_factor = 1.0 + max(0.0, 15.0 - temperature) / 30.0
    return population * 0.0005 * cold_factor


def mite_infestation_rate(mite_count, sample_size=300.0):
    return mite_count / sample_size * 100.0


def colony_health_score(mite_percent, hive_weight, stores_needed, foragers, population):
    score = 100.0 - mite_percent * 8.0
    if hive_weight < stores_needed:
        score -= (stores_needed - hive_weight) / stores_needed * 30.0
    if foragers < population * 0.20:
        score -= (0.20 - foragers / population) * 100.0
    return max(0.0, min(100.0, score))


def assess(apiary):
    population, distance, flora, hours, temperature, mites, weight = validate_apiary(apiary)
    foragers = foraging_bees(population, temperature)
    nectar = nectar_collection(foragers, distance, flora, hours)
    honey = honey_yield(nectar)
    stores = winter_stores(population, temperature)
    mites_pct = mite_infestation_rate(mites)
    health = colony_health_score(mites_pct, weight, stores, foragers, population)
    return [foragers, round(nectar, 2), round(water_evaporated(nectar), 2), round(honey, 2),
            round(beeswax_production(honey), 3), supers_required(honey), round(stores, 2),
            round(mites_pct, 2), round(health, 1)]


def format_report(metrics):
    labels = ("Foraging bees", "Daily nectar (kg)", "Water evaporated (kg)", "Daily honey (kg)",
              "Beeswax (kg)", "Supers required", "Winter stores (kg)", "Mite infestation (%)",
              "Health score")
    return "\n".join("{0:<22}{1}".format(k, v) for k, v in zip(labels, metrics))


if __name__ == "__main__":
    print(format_report(assess([50000, 2, 80, 8, 25, 3, 40])))

