def validate_inputs(landfill):
    if len(landfill) != 8:
        raise ValueError("landfill must contain exactly eight metrics")
    if any(value < 0 for value in landfill):
        raise ValueError("landfill metrics must be non-negative")
    if landfill[7] <= 0:
        raise ValueError("average cell depth must be greater than zero")
    if landfill[5] < landfill[6]:
        raise ValueError("used volume cannot exceed permitted volume")
    return [float(value) for value in landfill]


def compacted_density(equipment_weight):
    return 500.0 + equipment_weight / 1000.0 * 10.0


def daily_waste_volume(daily_mass, density):
    return daily_mass / density


def cover_soil_volume(waste_volume, cover_ratio):
    return waste_volume * cover_ratio


def total_daily_volume(waste_volume, soil_volume):
    return waste_volume + soil_volume


def airspace_consumed(used_volume, permitted_volume):
    return used_volume / permitted_volume * 100.0


def remaining_lifespan(permitted_volume, used_volume, daily_volume):
    return (permitted_volume - used_volume) / (daily_volume * 365.0)


def leachate_generation(precipitation, used_volume, cell_depth, daily_mass, moisture):
    footprint = used_volume / cell_depth
    infiltration = precipitation * footprint * 0.85
    squeezed = daily_mass * 365.0 * (moisture / 100.0) * 0.05 / 1000.0
    return infiltration + squeezed


def methane_yield(daily_mass, moisture):
    potential = 0.15 * (0.7 + 0.012 * moisture)
    return daily_mass * 365.0 * potential


def capping_area(permitted_volume, cell_depth):
    return permitted_volume / cell_depth


def simulate(landfill):
    mass, weight, ratio, rain, moisture, permitted, used, depth = validate_inputs(landfill)
    density = compacted_density(weight)
    waste_volume = daily_waste_volume(mass, density)
    soil_volume = cover_soil_volume(waste_volume, ratio)
    daily_total = total_daily_volume(waste_volume, soil_volume)
    return [
        waste_volume,
        density,
        soil_volume,
        daily_total,
        airspace_consumed(used, permitted),
        remaining_lifespan(permitted, used, daily_total),
        leachate_generation(rain, used, depth, mass, moisture),
        methane_yield(mass, moisture),
        capping_area(permitted, depth),
    ]


def format_report(results):
    labels = [
        "Daily waste volume (m3/day)",
        "Compacted waste density (kg/m3)",
        "Daily cover soil volume (m3/day)",
        "Total daily volume (m3/day)",
        "Airspace consumed (%)",
        "Remaining lifespan (years)",
        "Leachate generation (m3/year)",
        "Methane yield (m3/year)",
        "Final capping area (m2)",
    ]
    return "\n".join("%-34s %14.2f" % pair for pair in zip(labels, results))


def main():
    landfill = [500000, 30000, 0.2, 1.2, 25, 10000000, 4000000, 15]
    print(format_report(simulate(landfill)))


if __name__ == "__main__":
    main()

