import math

MM_PER_INCH = 25.4
TARGET_FOOT_LAMBERTS = 16.0


def validate_setup(setup):
    if len(setup) != 7:
        raise ValueError("setup must hold exactly seven values")
    values = [float(value) for value in setup]
    if any(value <= 0.0 for value in values):
        raise ValueError("every projector setup value must be positive")
    return values


def throw_ratio(aspect_ratio, focal_length, chip_diagonal):
    chip_width = chip_diagonal * MM_PER_INCH * aspect_ratio / math.sqrt(1.0 + aspect_ratio ** 2)
    return focal_length / chip_width


def projection_distance(throw_distance, vertical_offset):
    return math.hypot(throw_distance, vertical_offset)


def screen_width(throw_distance, ratio):
    return throw_distance / ratio


def screen_height(width, aspect_ratio):
    return width / aspect_ratio


def image_area(width, height):
    return width * height


def projector_offset(vertical_offset, height):
    return 100.0 * vertical_offset / height


def keystone_angle(throw_distance, vertical_offset):
    return math.degrees(math.atan2(vertical_offset, throw_distance))


def required_lumens(area, screen_gain):
    return area * TARGET_FOOT_LAMBERTS / screen_gain


def foot_lamberts(lamp_power, screen_gain, area):
    return lamp_power * screen_gain / area


def calculate(setup):
    aspect_ratio, throw, focal, chip, offset, gain, lamp = validate_setup(setup)
    ratio = throw_ratio(aspect_ratio, focal, chip)
    distance = projection_distance(throw, offset)
    width = screen_width(throw, ratio)
    height = screen_height(width, aspect_ratio)
    area = image_area(width, height)
    return [
        ratio,
        distance,
        width,
        height,
        area,
        projector_offset(offset, height),
        keystone_angle(throw, offset),
        required_lumens(area, gain),
        foot_lamberts(lamp, gain, area),
    ]


def format_report(metrics):
    labels = [
        ("throw ratio", ":1"),
        ("projection distance", " ft"),
        ("screen width", " ft"),
        ("screen height", " ft"),
        ("image area", " sq ft"),
        ("projector offset", " %"),
        ("keystone angle", " deg"),
        ("required lamp lumens", " lm"),
        ("foot lamberts", " fL"),
    ]
    lines = []
    for (label, unit), value in zip(labels, metrics):
        lines.append("{:<22}{:>10.3f}{}".format(label, value, unit))
    return "\n".join(lines)


def main():
    setup = [1.85, 20, 50, 1.2, 2, 1.4, 5000]
    metrics = calculate(setup)
    print(format_report(metrics))


if __name__ == "__main__":
    main()

