GAS_LHV = 37500.0
BAKE_RATE_MIN_PER_KG = 24.0

def validate(oven):
    if len(oven) != 9:
        raise ValueError("oven must hold nine parameters")
    values = [float(v) for v in oven]
    if min(values[:5]) <= 0 or values[7] <= 0 or values[8] <= 0:
        raise ValueError("lengths, masses, heat capacity and capacities must be positive")
    if values[3] >= values[2]:
        raise ValueError("baked mass must be lower than dough mass")
    if values[6] <= values[5]:
        raise ValueError("baking temperature must exceed entering temperature")
    return values

def total_baking_time(baked_mass):
    return BAKE_RATE_MIN_PER_KG * baked_mass

def conveyor_speed(oven_length, baking_time):
    return oven_length / baking_time

def piece_rate(speed, spacing):
    return speed / spacing

def total_heat_load(pieces_per_min, dough_mass, baked_mass, specific_heat, t_in, t_bake):
    sensible = dough_mass * specific_heat * (t_bake - t_in)
    latent = (dough_mass - baked_mass) * LATENT_HEAT_WATER
    return pieces_per_min * (sensible + latent) / 60.0

def moisture_loss_rate(pieces_per_min, dough_mass, baked_mass):
    return pieces_per_min * (dough_mass - baked_mass) * 60.0

def exhaust_airflow(moisture_per_hour):
