def validate_bow(bow):
    if len(bow) != 6:
        raise ValueError("bow must contain six parameters")
    nominal, draw_length, arrow_mass, brace, bow_length, elasticity = bow
    if nominal <= 0 or arrow_mass <= 0 or bow_length <= 0:
        raise ValueError("weights and lengths must be positive")
    if draw_length <= brace or brace <= 0:
        raise ValueError("draw length must exceed a positive brace height")
    if not 0.0 <= elasticity < 1.0:
        raise ValueError("elasticity factor must be in [0, 1)")
    return tuple(float(value) for value in bow)


def draw_weight_at_length(nominal, draw_length):
    per_inch = nominal * 0.025
    return nominal + (draw_length - 28.0) * per_inch


def stored_energy(draw_weight, draw_length, brace_height):
    power_stroke = (draw_length - brace_height) / 12.0
    return 0.5 * draw_weight * power_stroke


def arrow_velocity(energy, arrow_mass, elasticity):
    efficiency = 0.85 - elasticity * 2.0
    delivered = energy * efficiency
    return (450240.0 * delivered / arrow_mass) ** 0.5


def kinetic_energy(arrow_mass, velocity):
    return arrow_mass * velocity ** 2 / 450240.0


def momentum(arrow_mass, velocity):
    return arrow_mass * velocity / 225218.0


def recommended_spine(draw_weight, draw_length, arrow_mass):
    spine = draw_weight + (draw_length - 28.0) * 5.0
    if arrow_mass < 8.0 * draw_weight:
        spine -= 5.0
    return spine


def string_length(bow_length, elasticity):
    nominal_string = bow_length - 3.0
    return nominal_string * (1.0 - elasticity / 2.0)


def brace_height_efficiency(draw_length, brace_height):
    return 100.0 * (draw_length - brace_height) / draw_length


def bow_mass_weight(bow_length, nominal):
    return bow_length * 0.28 + nominal * 0.09


def analyze(bow):
    nominal, draw_length, arrow_mass, brace, bow_length, elasticity = validate_bow(bow)
    weight = draw_weight_at_length(nominal, draw_length)
    energy = stored_energy(weight, draw_length, brace)
    velocity = arrow_velocity(energy, arrow_mass, elasticity)
    return [round(weight, 2),
            round(energy, 2),
            round(velocity, 2),
            round(kinetic_energy(arrow_mass, velocity), 2),
            round(momentum(arrow_mass, velocity), 4),
            round(recommended_spine(weight, draw_length, arrow_mass), 1),
            round(string_length(bow_length, elasticity), 2),
            round(brace_height_efficiency(draw_length, brace), 2),
            round(bow_mass_weight(bow_length, nominal), 2)]


def format_report(bow):
    labels = ["Draw weight (lb)", "Stored energy (ft-lb)", "Arrow velocity (fps)",
              "Kinetic energy (ft-lb)", "Momentum (slug-ft/s)", "Recommended spine (lb)",
              "String length (in)", "Brace efficiency (%)", "Bow mass weight (oz)"]
    lines = []
    for label, value in zip(labels, analyze(bow)):
        lines.append("{:<24}{:>10}".format(label, value))
    return "\n".join(lines)


def main():
    print(format_report((50, 29, 450, 7.5, 62, 0.02)))


if __name__ == "__main__":
    main()

