SAP_NAOH = 0.1375
SAP_KOH = 0.1925
BATTER_DENSITY = 0.95
CURE_WATER_LOSS = 0.70

def validate_recipe(recipe):
    if len(recipe) != 6:
        raise ValueError("recipe must hold six values")
    base, sodium_fraction, superfat, water_pct, fragrance_rate, colorant_rate = recipe
    if base <= 0:
        raise ValueError("base oil weight must be positive")
    if not 0.0 <= sodium_fraction <= 1.0:
        raise ValueError("sodium fraction must lie between 0 and 1")
    if not 0.0 <= superfat < 1.0:
        raise ValueError("superfat must lie between 0 and 1")
    for rate in (water_pct, fragrance_rate, colorant_rate):
        if rate < 0.0:
            raise ValueError("rates may not be negative")
    return base, sodium_fraction, superfat, water_pct, fragrance_rate, colorant_rate


def fragrance_amount(base_oil_weight, fragrance_rate):
    return base_oil_weight * fragrance_rate


def colorant_amount(base_oil_weight, colorant_rate):
    return base_oil_weight * colorant_rate


def total_oil_mass(base_oil_weight, fragrance, colorant):
    return base_oil_weight + fragrance + colorant


def lye_sodium_hydroxide(base_oil_weight, sodium_fraction):
    return base_oil_weight * sodium_fraction * SAP_NAOH


def lye_potassium_hydroxide(base_oil_weight, sodium_fraction):
    return base_oil_weight * (1.0 - sodium_fraction) * SAP_KOH


def superfat_lye_discount(naoh_gross, koh_gross, superfat):
    return (naoh_gross + koh_gross) * superfat


def water_amount(base_oil_weight, water_pct):
    return base_oil_weight * water_pct


def batch_volume(oils, naoh, koh, water, fragrance, colorant):
    wet_mass = oils + naoh + koh + water + fragrance + colorant
    return wet_mass / BATTER_DENSITY


def cured_soap_weight(oils, naoh, koh, water):
    return oils + naoh + koh + water - water * CURE_WATER_LOSS


def formulate(recipe):
    base, sodium_fraction, superfat, water_pct, fragrance_rate, colorant_rate = validate_recipe(recipe)
    fragrance = fragrance_amount(base, fragrance_rate)
    colorant = colorant_amount(base, colorant_rate)
    oils = total_oil_mass(base, fragrance, colorant)
    naoh_gross = lye_sodium_hydroxide(base, sodium_fraction)
    koh_gross = lye_potassium_hydroxide(base, sodium_fraction)
    discount = superfat_lye_discount(naoh_gross, koh_gross, superfat)
    keep = 1.0 - superfat
    naoh = naoh_gross * keep
    koh = koh_gross * keep
    water = water_amount(base, water_pct)
    volume = batch_volume(base, naoh, koh, water, fragrance, colorant)
    cured = cured_soap_weight(oils, naoh, koh, water)
    values = (oils, naoh, koh, water, discount, fragrance, colorant, volume, cured)
    return tuple(round(value, 2) for value in values)


def format_report(recipe, amounts):
    labels = ("total oils g", "NaOH g", "KOH g", "water g", "superfat lye discount g",
              "fragrance g", "colorant g", "batch volume ml", "cured soap g")
    header = "recipe %s" % (recipe,)
    rows = ["  %-24s %10.2f" % (label, value) for label, value in zip(labels, amounts)]
    return "\n".join([header] + rows)


def main():
    bar_soap = (1000, 1.0, 0.05, 0.33, 0.03, 0.01)
    dual_lye = (2000, 0.7, 0.08, 0.38, 0.02, 0.005)
    print(format_report(bar_soap, formulate(bar_soap)))
    print(format_report(dual_lye, formulate(dual_lye)))


if __name__ == "__main__":
    main()

