def validate_batch(batch):
    if len(batch) != 5:
        raise ValueError("batch must contain exactly five values")
    volume, protein, fat, hardness, humidity = (float(value) for value in batch)
    if volume <= 0:
        raise ValueError("milk volume must be positive")
    if not 0 < protein < 100 or not 0 < fat < 100:
        raise ValueError("protein and fat must be percentages above zero")
    if hardness <= 0:
        raise ValueError("hardness factor must be positive")
    if not 0 <= humidity <= 100:
        raise ValueError("humidity must be a percentage")
    return volume, protein, fat, hardness, humidity


def curd_yield(volume, protein, fat):
    return round(volume * (protein * 1.9 + fat) / 100.0, 2)


def starter_culture(volume):
    return round(volume * 1.5, 1)


def rennet_dosage(volume, protein):
    return round(volume * (0.2 + protein * 0.02), 2)


def initial_pressing_weight(curd, hardness):
    return round(curd * hardness * 0.8, 2)


def final_pressing_weight(initial_weight, hardness):
    return round(initial_weight * (1.5 + hardness * 0.5), 2)


def brine_bath_duration(curd, hardness):
    return round(curd * hardness * 0.9, 1)


def ripening_temperature(hardness, humidity):
    return round(12.5 - hardness * 1.5 + (humidity - 85) * 0.02, 1)


def moisture_loss(hardness, humidity):
    return round((100.0 - humidity) * 0.6 + hardness * 4, 1)


def maturity_days(curd, hardness, loss):
    return int(round(curd * hardness * 3 + loss * 2))


def ripen(batch):
    volume, protein, fat, hardness, humidity = validate_batch(batch)
    curd = curd_yield(volume, protein, fat)
    starter = starter_culture(volume)
    rennet = rennet_dosage(volume, protein)
    first_press = initial_pressing_weight(curd, hardness)
    last_press = final_pressing_weight(first_press, hardness)
    brine = brine_bath_duration(curd, hardness)
    temperature = ripening_temperature(hardness, humidity)
    loss = moisture_loss(hardness, humidity)
    return (curd, starter, rennet, first_press, last_press, brine,
            temperature, loss, maturity_days(curd, hardness, loss))


def format_report(parameters):
    labels = ("curd yield (kg)", "starter culture (g)", "rennet (ml)",
              "initial press (kg)", "final press (kg)", "brine bath (h)",
              "ripening room (C)", "moisture loss (%)", "maturity (days)")
    return "\n".join("%-20s %s" % (label, value)
                     for label, value in zip(labels, parameters))


def main():
    batch = [100, 3.4, 3.6, 1.2, 85]
    print(format_report(ripen(batch)))


if __name__ == "__main__":
    main()

