CHEMICAL_NAMES = (
    "Soaking water (L)",
    "Unhairing lime (kg)",
    "Deliming ammonium sulfate (kg)",
    "Bating enzyme (kg)",
    "Pickling salt (kg)",
    "Pickling acid (L)",
    "Chrome tanning agent (kg)",
    "Basification sodium bicarbonate (kg)",
    "Fatliquor oil (L)",
)


def validate_inputs(hides):
    if len(hides) != 3:
        raise ValueError("hides must contain weight, temperature and softness")
    weight, temperature, softness = (float(value) for value in hides)
    if weight <= 0:
        raise ValueError("wet salted weight must be positive")
    if not 5.0 <= temperature <= 45.0:
        raise ValueError("ambient temperature must be between 5 and 45 C")
    if softness <= 0:
        raise ValueError("softness multiplier must be positive")
    return weight, temperature, softness


def pelt_weight(weight):
    return weight * 1.15


def soak_water(weight, temperature):
    return weight * (8.0 + 0.08 * (temperature - 20.0))


def unhairing_lime(weight):
    return weight * 0.08


def deliming_ammonium_sulfate(pelt):
    return pelt * 0.02


def bating_enzyme(pelt, temperature):
    activity = 1.0 + 0.03 * (35.0 - temperature)
    return pelt * 0.01 * activity


def pickling_salt(water):
    return water * 0.06


def pickling_acid(pelt):
    return pelt * 0.012


def chrome_tanning_agent(pelt):
    return pelt * 0.08


def basification_bicarbonate(chrome):
    return chrome * 0.15


def fatliquor_oil(pelt, softness):
    return pelt * 0.04 * softness


def tan(hides):
    weight, temperature, softness = validate_inputs(hides)
    pelt = pelt_weight(weight)
    water = soak_water(weight, temperature)
    chrome = chrome_tanning_agent(pelt)
    dosages = (
        water,
        unhairing_lime(weight),
        deliming_ammonium_sulfate(pelt),
        bating_enzyme(pelt, temperature),
        pickling_salt(water),
        pickling_acid(pelt),
        chrome,
        basification_bicarbonate(chrome),
        fatliquor_oil(pelt, softness),
    )
    return [round(amount, 2) for amount in dosages]


def format_report(hides, dosages):
    header = "Tanning plan for {0} kg at {1} C, softness {2}".format(*hides)
    lines = [header]
    for name, amount in zip(CHEMICAL_NAMES, dosages):
        lines.append("  {0:<38}{1:>8.2f}".format(name, amount))
    return "\n".join(lines)


def main():
    batch = (50, 25, 1.5)
    print(format_report(batch, tan(batch)))


if __name__ == "__main__":
    main()

