import math


def validate_rough(rough):
    if len(rough) != 4:
        raise ValueError("rough must be (mass, refractive index, specific gravity, width)")
    mass, ri, sg, width = (float(value) for value in rough)
    if mass <= 0 or width <= 0:
        raise ValueError("mass and planned width must be positive")
    if not 1.0 < ri < 3.0:
        raise ValueError("refractive index outside the range of gem materials")
    if sg <= 0:
        raise ValueError("specific gravity must be positive")
    return mass, ri, sg, width


def critical_angle(ri):
    return math.degrees(math.asin(1.0 / ri))


def pavilion_angle(ri):
    return critical_angle(ri) + 2.5


def crown_angle(ri):
    return 0.75 * (90.0 - pavilion_angle(ri))


def table_percent(ri):
    return 100.0 - 1.25 * crown_angle(ri)


def star_length(ri):
    return (100.0 - table_percent(ri)) / 2.0


def girdle_thickness(width):
    return max(0.30, 0.025 * width)


def finished_carat(mass, ri, sg, width):
    girdle = girdle_thickness(width)
    pavilion_depth = 0.5 * width * math.tan(math.radians(pavilion_angle(ri)))
    crown_span = 0.5 * width * (1.0 - table_percent(ri) / 100.0)
    crown_height = crown_span * math.tan(math.radians(crown_angle(ri)))
    depth = crown_height + girdle + pavilion_depth
    weight = 0.0018 * width * width * depth * sg
    return min(weight, 0.35 * mass)


def light_return(ri):
    pavilion_error = abs(pavilion_angle(ri) - 41.0)
    table_error = abs(table_percent(ri) - 56.0)
    return max(0.0, min(100.0, 98.0 - 3.0 * pavilion_error - 0.8 * table_error))


def dispersion_ratio(ri):
    dispersion = 0.0075 + 0.021 * (ri - 1.5)
    return 100.0 * dispersion / (ri - 1.0)


def facet(rough):
    mass, ri, sg, width = validate_rough(rough)
    return (round(critical_angle(ri), 2),
            round(pavilion_angle(ri), 2),
            round(crown_angle(ri), 2),
            round(table_percent(ri), 2),
            round(star_length(ri), 2),
            round(girdle_thickness(width), 2),
            round(finished_carat(mass, ri, sg, width), 3),
            round(light_return(ri), 2),
            round(dispersion_ratio(ri), 3))


def format_report(rough, parameters):
    labels = ("critical angle (deg)", "pavilion main (deg)", "crown main (deg)",
              "table size (%)", "star facet length (%)", "girdle thickness (mm)",
              "finished weight (ct)", "light return (%)", "dispersion ratio (%)")
    header = "Rough: {0} ct, RI {1}, SG {2}, width {3} mm".format(*rough)
    rows = ["{0:<24}{1:>9}".format(name, value)
            for name, value in zip(labels, parameters)]
    return "\n".join([header] + rows)


def main():
    rough = (15, 1.76, 3.99, 8)
    print(format_report(rough, facet(rough)))


if __name__ == "__main__":
    main()

