import math

def validate_boat(boat):
    if len(boat) != 6:
        raise ValueError("a boat record needs six fields")
    start, finish, handicap, distance, wind, flags = boat
    if finish <= start:
        raise ValueError("finish time must be after start time")
    if handicap <= 0 or distance <= 0:
        raise ValueError("handicap rating and course distance must be positive")
    if flags < 0:
        raise ValueError("penalty flags cannot be negative")
    return start, finish, handicap, distance, wind % 360, flags


def elapsed_time(start, finish):
    return finish - start


def corrected_time(elapsed, handicap):
    return elapsed * handicap


def average_speed(distance, elapsed):
    return distance / (elapsed / 3600.0)


def port_tack_distance(distance, wind_direction):
    share = 0.5 + math.sin(math.radians(wind_direction)) / 4.0
    return distance * share


