import math

GRAVITY = 9.81
LIFT_COEFFICIENT = 0.9
DRAG_COEFFICIENT = 0.12
STROUHAL_NUMBER = 0.2


def wing_area(wingspan, root_chord):
    return 0.5 * wingspan * root_chord


def lift_force(area, velocity, density):
    return 0.5 * density * velocity ** 2 * area * LIFT_COEFFICIENT


def form_drag(area, velocity, density):
    return 0.5 * density * velocity ** 2 * area * DRAG_COEFFICIENT


def line_tension_limit(lift, drag, mass):
    return math.hypot(lift, drag) + mass * GRAVITY


def optimal_bridle_angle(lift, drag):
    return math.degrees(math.atan2(drag, lift))


def turning_radius(wingspan, velocity, lift, mass):
    if lift <= 0.0:
        return float('inf')
    return (mass * velocity ** 2) / lift + 0.25 * wingspan


def max_wind_speed(area, density, tension):
    return math.sqrt(2.0 * tension / (density * area * LIFT_COEFFICIENT))


def flutter_frequency(root_chord, velocity):
    return STROUHAL_NUMBER * velocity / root_chord


def required_line_length(tension, elasticity, wingspan):
    stretch = 1.0 + elasticity * math.log1p(tension)
    return 10.0 * wingspan * stretch


def validate(kite):
    if len(kite) != 6:
        raise ValueError('kite must hold 6 parameters')
    wingspan, root_chord, velocity, density, mass, elasticity = kite
    if min(wingspan, root_chord, density, mass) <= 0.0:
        raise ValueError('geometry, density and mass must be positive')
    if velocity < 0.0 or elasticity < 0.0:
        raise ValueError('velocity and elasticity must not be negative')
    return wingspan, root_chord, velocity, density, mass, elasticity


def fly(kite):
    wingspan, root_chord, velocity, density, mass, elasticity = validate(kite)
    area = wing_area(wingspan, root_chord)
    lift = lift_force(area, velocity, density)
    drag = form_drag(area, velocity, density)
    tension = line_tension_limit(lift, drag, mass)
    return [
        area,
        lift,
        drag,
        tension,
        optimal_bridle_angle(lift, drag),
        turning_radius(wingspan, velocity, lift, mass),
        max_wind_speed(area, density, tension),
        flutter_frequency(root_chord, velocity),
        required_line_length(tension, elasticity, wingspan),
    ]


def report(metrics):
    labels = ('wing area [m^2]', 'lift [N]', 'drag [N]', 'tension limit [N]',
              'bridle angle [deg]', 'turning radius [m]', 'max wind [m/s]',
              'flutter [Hz]', 'line length [m]')
    return '\n'.join('%-20s %10.3f' % pair for pair in zip(labels, metrics))


def main():
    print(report(fly((2.5, 0.8, 12, 1.2, 0.3, 0.05))))


if __name__ == '__main__':
    main()

