G = 9.80665
LOCO_MASS_KG = 120000.0
LOADED_CAR_KG = 100000.0
EMPTY_CAR_KG = 25000.0
ROLLING_COEFF = 0.0022
DRAG_FACTOR = 0.5 * 1.225 * 1.8 * 10.5
ADHESION_COEFF = 0.33
BRAKE_COEFF = 0.09
FUEL_L_PER_KWH = 0.215 / 0.845
CURVE_FACTOR = 0.11 / 1.505


def parse_train(train):
    locos, loaded, empties, grade, radius, speed = train
    if locos < 1 or loaded < 0 or empties < 0 or radius <= 0:
        raise ValueError("invalid consist: check vehicle counts and curve radius")
    return int(locos), int(loaded), int(empties), float(grade), float(radius), float(speed)


def total_train_mass(locos, loaded, empties):
    return locos * LOCO_MASS_KG + loaded * LOADED_CAR_KG + empties * EMPTY_CAR_KG


def rolling_resistance(mass_kg):
    return ROLLING_COEFF * mass_kg * G


def aerodynamic_drag(speed_kmh):
    return DRAG_FACTOR * (speed_kmh / 3.6) ** 2


def grade_resistance(mass_kg, grade_percent):
    return mass_kg * G * grade_percent / 100.0


def drawbar_pull(rolling, drag, grade):
    return rolling + drag + grade


def adhesion_limit(locos):
    return locos * LOCO_MASS_KG * G * ADHESION_COEFF


def braking_distance(mass_kg, speed_kmh, rolling, drag, grade):
    decel = (BRAKE_COEFF * mass_kg * G + rolling + drag + grade) / mass_kg
    if decel <= 0.0:
        raise ValueError("train cannot be decelerated on this grade")
    return (speed_kmh / 3.6) ** 2 / (2.0 * decel)


def fuel_rate(pull, speed_kmh):
    return pull * (speed_kmh / 3.6) / 1000.0 * FUEL_L_PER_KWH


def max_curve_speed(radius_m):
    return 3.6 * (CURVE_FACTOR * G * radius_m) ** 0.5


def dispatch(train):
    locos, loaded, empties, grade, radius, speed = parse_train(train)
    mass = total_train_mass(locos, loaded, empties)
    rolling, drag = rolling_resistance(mass), aerodynamic_drag(speed)
    slope = grade_resistance(mass, grade)
    pull = drawbar_pull(rolling, drag, slope)
    return [round(v, 3) for v in (mass, rolling, drag, slope, pull, adhesion_limit(locos),
                                  braking_distance(mass, speed, rolling, drag, slope),
                                  fuel_rate(pull, speed), max_curve_speed(radius))]


def main():
    consist = [3, 80, 20, 1.2, 500, 60]
    metrics = dispatch(consist)
    print(metrics)
    if metrics[4] > metrics[5]:
        print("WARNING: required pull exceeds locomotive adhesion")
    if consist[5] > metrics[8]:
        print("WARNING: speed exceeds safe curving limit")


if __name__ == "__main__":
    main()

