PAGE_AREA_M2 = 0.06237
INK_FILM_ML_PER_M2 = 1.15
IMPRESSIONS_PER_HOUR = 12000.0
MAKEREADY_HOURS = 0.75
WASH_INTERVAL = 20000
WASH_LITRES = 0.25
WASH_DOWNTIME_HOURS = 0.2
WASTE_FRACTION = 0.04
MAKEREADY_SHEETS = 350
INK_COST_PER_L = 28.0
FOUNTAIN_COST_PER_L = 6.0
WASH_COST_PER_L = 12.0
PAPER_COST_PER_SHEET = 0.011
LABELS = ("cyan ink (L)", "magenta ink (L)", "yellow ink (L)", "black ink (L)",
          "fountain solution (L)", "blanket wash (L)", "paper sheets",
          "press hours", "material cost")

def validate_job(job):
    if len(job) != 6:
        raise ValueError("job must hold pages, copies and four coverage values")
    pages, copies = int(job[0]), int(job[1])
    if pages < 1 or copies < 1:
        raise ValueError("pages and copies must be positive")
    coverages = [float(v) for v in job[2:]]
    for value in coverages:
        if value < 0 or value > 100:
            raise ValueError("coverage percentages must lie between 0 and 100")
    return [pages, copies] + coverages

def total_impressions(pages, copies):
    sides_per_sheet = 2
    sheets_per_copy = -(-pages // sides_per_sheet)
    return sheets_per_copy * sides_per_sheet * copies

def ink_volume(impressions, coverage):
    millilitres = impressions * PAGE_AREA_M2 * (coverage / 100.0) * INK_FILM_ML_PER_M2
    return millilitres / 1000.0

def cyan_ink_volume(impressions, cyan_coverage):
    return ink_volume(impressions, cyan_coverage)

def magenta_ink_volume(impressions, magenta_coverage):
    return ink_volume(impressions, magenta_coverage)

def yellow_ink_volume(impressions, yellow_coverage):
    return ink_volume(impressions, yellow_coverage)

def black_ink_volume(impressions, black_coverage):
    return ink_volume(impressions, black_coverage)

def fountain_solution(impressions, ink_litres):
    return 0.18 * ink_litres + 0.9 * impressions / 1000.0

def blanket_washes(impressions):
    return max(1, -(-impressions // WASH_INTERVAL))

def blanket_wash_fluid(impressions):
    return blanket_washes(impressions) * WASH_LITRES

def total_paper_sheets(pages, copies):
    sheets = -(-pages // 2) * copies
    return int(round(sheets * (1.0 + WASTE_FRACTION))) + MAKEREADY_SHEETS

def running_time_hours(impressions, washes):
    return (impressions / IMPRESSIONS_PER_HOUR + MAKEREADY_HOURS
            + washes * WASH_DOWNTIME_HOURS)

def total_material_cost(ink_litres, fountain_litres, wash_litres, sheets):
    return (ink_litres * INK_COST_PER_L + fountain_litres * FOUNTAIN_COST_PER_L
            + wash_litres * WASH_COST_PER_L + sheets * PAPER_COST_PER_SHEET)

def estimate(job):
    pages, copies, cyan, magenta, yellow, black = validate_job(job)
    impressions = total_impressions(pages, copies)
    inks = [cyan_ink_volume(impressions, cyan),
            magenta_ink_volume(impressions, magenta),
            yellow_ink_volume(impressions, yellow),
            black_ink_volume(impressions, black)]
    fountain = fountain_solution(impressions, sum(inks))
    wash = blanket_wash_fluid(impressions)
    sheets = total_paper_sheets(pages, copies)
    hours = running_time_hours(impressions, blanket_washes(impressions))
    cost = total_material_cost(sum(inks), fountain, wash, sheets)
    return [round(v, 3) for v in inks] + [round(fountain, 3), round(wash, 3),
                                          sheets, round(hours, 2), round(cost, 2)]

