    rows = ["  %-22s %12s" % (name, value)
            for name, value in zip(LABELS, results)]
    return "\n".join([header] + rows)

def main():
    job = [32, 10000, 15, 20, 25, 40]
    print(format_report(job, estimate(job)))


if __name__ == "__main__":
    main()

