import math

FEED_COMPOSITION = 0.5
LIGHT_KEY_RECOVERY = 0.98
TRAY_EFFICIENCY = 0.6
LATENT_HEAT = 32000.0
FEED_HEAT_CAPACITY = 150.0


def validate_process(process):
    if len(process) != 5:
        raise ValueError("process must hold five parameters")
    feed_rate, feed_temp, pressure, bottom_temp, target = (float(v) for v in process)
    if feed_rate <= 0 or pressure <= 0:
        raise ValueError("feed rate and overhead pressure must be positive")
    if not 50.0 < target < 100.0:
        raise ValueError("target distillate composition must lie between 50 and 100 %")
    if bottom_temp <= feed_temp:
        raise ValueError("bottom temperature must exceed feed temperature")
    return feed_rate, feed_temp, pressure, bottom_temp, target


def relative_volatility(feed_temp, bottom_temp):
    return 1.0 + (bottom_temp - feed_temp) / 50.0


def distillate_rate(feed_rate, target):
    return feed_rate * FEED_COMPOSITION * LIGHT_KEY_RECOVERY / (target / 100.0)


def bottom_concentration(feed_rate, distillate, target):
    bottoms = feed_rate - distillate
    light_key = feed_rate * FEED_COMPOSITION - distillate * target / 100.0
    return 100.0 * light_key / bottoms


def minimum_reflux(alpha, target):
    top = target / 100.0
    feed = FEED_COMPOSITION
    return (top / feed - alpha * (1.0 - top) / (1.0 - feed)) / (alpha - 1.0)


def reflux_ratio(alpha, target):
    return 1.3 * minimum_reflux(alpha, target)


def vapor_flow_rate(distillate, reflux):
    return distillate * (reflux + 1.0)


def liquid_fallback_rate(distillate, reflux):
    return distillate * reflux


def minimum_plates(alpha, target, bottom_pct):
    top = target / 100.0
    bottom = bottom_pct / 100.0
    return math.log((top / (1 - top)) * ((1 - bottom) / bottom)) / math.log(alpha)


def theoretical_plates(nmin, reflux, rmin):
    x = (reflux - rmin) / (reflux + 1.0)
    y = 1.0 - math.exp((1 + 54.4 * x) / (11 + 117.2 * x) * ((x - 1) / math.sqrt(x)))
    return math.ceil((nmin + y) / (1.0 - y))


def condenser_duty(vapor):
    return vapor * LATENT_HEAT / 3600.0


def reboiler_duty(condenser_kw, feed_rate, feed_temp, bottom_temp):
    sensible = feed_rate * FEED_HEAT_CAPACITY * (bottom_temp - feed_temp)
    return condenser_kw + sensible / 3600.0


def distillate_purity(alpha, plates, bottom_pct):
    bottom = bottom_pct / 100.0
    ratio = alpha ** (plates * TRAY_EFFICIENCY) * (bottom / (1 - bottom))
    return 100.0 * ratio / (1.0 + ratio)


def pressure_drop(plates, pressure):
    return plates * (0.5 + 0.1 * pressure)


def distill(process):
    feed_rate, feed_temp, pressure, bottom_temp, target = validate_process(process)
    alpha = relative_volatility(feed_temp, bottom_temp)
    distillate = distillate_rate(feed_rate, target)
    bottom_pct = bottom_concentration(feed_rate, distillate, target)
    rmin = minimum_reflux(alpha, target)
    reflux = reflux_ratio(alpha, target)
    vapor = vapor_flow_rate(distillate, reflux)
    liquid = liquid_fallback_rate(distillate, reflux)
    nmin = minimum_plates(alpha, target, bottom_pct)
    plates = theoretical_plates(nmin, reflux, rmin)
    condenser = condenser_duty(vapor)
    reboiler = reboiler_duty(condenser, feed_rate, feed_temp, bottom_temp)
    return [round(vapor, 2), round(liquid, 2), round(reflux, 2), plates,
            round(condenser, 2), round(reboiler, 2),
            round(distillate_purity(alpha, plates, bottom_pct), 2),
            round(bottom_pct, 2), round(pressure_drop(plates, pressure), 2)]


def main():
    labels = ["vapor flow (kmol/h)", "liquid fallback (kmol/h)", "reflux ratio",
              "theoretical plates", "condenser duty (kW)", "reboiler duty (kW)",
              "distillate purity (%)", "bottom concentration (%)",
              "pressure drop (kPa)"]
    metrics = distill((100, 85, 1.1, 105, 95))
    for label, value in zip(labels, metrics):
        print("{:<26}{}".format(label, value))


if __name__ == "__main__":
    main()

