def validate_player(player):
    if len(player) != 5:
        raise ValueError("player must contain five numeric fields")
    rating, opponent_rating, age, games, increment = player
    for value in player:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise ValueError("player fields must be numeric")
    if rating < 100 or opponent_rating < 100:
        raise ValueError("ratings must be at least 100")
    if age < 4 or games < 0 or increment < 0:
        raise ValueError("age, games and increment must be sensible")
    return float(rating), float(opponent_rating), int(age), int(games), int(increment)


def expected_win_probability(rating, opponent_rating):
    return round(1.0 / (1.0 + 10.0 ** ((opponent_rating - rating) / 400.0)), 4)


def k_factor(rating, age, games):
    if games < 30:
        return 40
    if age < 18 and rating < 2300:
        return 40
    if rating < 2400:
        return 20
    return 10


def rating_change_win(rating, opponent_rating, age, games):
    expected = expected_win_probability(rating, opponent_rating)
    return round(k_factor(rating, age, games) * (1.0 - expected), 2)


def rating_change_draw(rating, opponent_rating, age, games):
    expected = expected_win_probability(rating, opponent_rating)
    return round(k_factor(rating, age, games) * (0.5 - expected), 2)


def rating_change_loss(rating, opponent_rating, age, games):
    expected = expected_win_probability(rating, opponent_rating)
    return round(k_factor(rating, age, games) * (0.0 - expected), 2)


def performance_rating(rating, opponent_rating):
    expected = expected_win_probability(rating, opponent_rating)
    return round(opponent_rating + 400.0 * (2.0 * expected - 1.0), 1)


def rating_category(rating):
    bands = ((1200, "Novice"), (1400, "Class D"), (1600, "Class C"),
             (1800, "Class B"), (2000, "Class A"), (2200, "Expert"),
             (2400, "National Master"))
    for limit, name in bands:
        if rating < limit:
            return name
    return "International Master"


def new_rating_category(rating, opponent_rating, age, games):
    return rating_category(rating + rating_change_win(rating, opponent_rating, age, games))


def max_rating_gain(rating, opponent_rating):
    return round(40 * (1.0 - expected_win_probability(rating, opponent_rating)), 2)


def volatility_adjustment(games, increment):
    experience_term = 50.0 / (games + 10)
    time_term = 1.0 + max(0, 30 - increment) / 60.0
    return round(experience_term * time_term, 2)


def rate(player):
    rating, opponent_rating, age, games, increment = validate_player(player)
    return (expected_win_probability(rating, opponent_rating),
            rating_change_win(rating, opponent_rating, age, games),
            rating_change_draw(rating, opponent_rating, age, games),
            rating_change_loss(rating, opponent_rating, age, games),
            performance_rating(rating, opponent_rating),
            rating_category(rating),
            new_rating_category(rating, opponent_rating, age, games),
            max_rating_gain(rating, opponent_rating),
            volatility_adjustment(games, increment))


def format_report(metrics):
    labels = ("Expected win probability", "Change on win", "Change on draw",
              "Change on loss", "Performance rating", "Current category",
              "Projected category", "Maximum gain", "Volatility adjustment")
    return "\n".join("%-26s %s" % (label, value) for label, value in zip(labels, metrics))


def main():
    player = (1800, 1950, 25, 40, 30)
    print(format_report(rate(player)))


if __name__ == "__main__":
    main()

