def validate(match):
    if len(match) != 7:
        raise ValueError("match summary must contain seven values")
    if any(value < 0 for value in match):
        raise ValueError("match values must be non-negative")
    if sum(match[:4]) == 0:
        raise ValueError("match must contain at least one point")
    return tuple(match)


def total_points(match):
    won_serve, lost_serve, won_return, lost_return = match[:4]
    return won_serve + lost_serve + won_return + lost_return


def service_win_percentage(match):
    won_serve, lost_serve = match[0], match[1]
    serves = won_serve + lost_serve
    if serves == 0:
        return 0.0
    return round(won_serve / serves * 100, 2)


def return_win_percentage(match):
    won_return, lost_return = match[2], match[3]
    returns = won_return + lost_return
    if returns == 0:
        return 0.0
    return round(won_return / returns * 100, 2)


def max_consecutive_points(match):
    streak = match[4]
    return min(streak, total_points(match))


def unforced_error_rate(match):
    return round(match[5] / total_points(match) * 100, 2)


def rally_length_average(match):
    return round(match[6] / total_points(match), 2)


def third_ball_attack_rate(match):
    won_serve, errors = match[0], match[5]
    attempts = won_serve + errors
    if attempts == 0:
        return 0.0
    return round(won_serve / attempts * 100, 2)


def game_point_conversion_rate(match):
    won_points = match[0] + match[2]
    if won_points == 0:
        return 0.0
    clean = max(won_points - match[5], 0)
    return round(clean / won_points * 100, 2)


def match_dominance_ratio(match):
    lost_points = match[1] + match[3]
    if lost_points == 0:
        return float(match[0] + match[2])
    return round((match[0] + match[2]) / lost_points, 2)


def assess(match):
    match = validate(match)
    return (total_points(match), service_win_percentage(match),
            return_win_percentage(match), max_consecutive_points(match),
            unforced_error_rate(match), rally_length_average(match),
            third_ball_attack_rate(match), game_point_conversion_rate(match),
            match_dominance_ratio(match))


def format_report(stats):
    labels = ("Total points", "Service win %", "Return win %", "Best streak",
              "Unforced error %", "Average rally", "Third ball %",
              "Game point conversion %", "Dominance ratio")
    return "\n".join("{:<26}{}".format(label, value)
                     for label, value in zip(labels, stats))


def main():
    summary = (20, 15, 18, 22, 5, 12, 450)
    print(format_report(assess(summary)))


if __name__ == "__main__":
    main()

