def motor_rpm(readings):
    return readings["gear_ratio"] * readings["motor_frequency"]


def wheel_speed(readings):
    return readings["rpm"] / 60.0 * readings["tire_circumference"]


def esc_temperature(readings):
    samples = readings["thermistor_readings"]
    return sum(samples) / len(samples) + readings["ambient_offset"]


def battery_voltage(readings):
    return sum(readings["cell_readings"]) - readings["voltage_sag"]


def steering_angle(readings):
    return (readings["servo_pulse_width"] - 1500.0) / 500.0 * readings["max_angle"]


def suspension_travel(readings):
    return readings["shock_length"] - readings["compressed_length"]


def tire_slip(readings):
    driven = readings["driven_wheel_speed"]
    return (driven - readings["gps_speed"]) / driven * 100.0


def lateral_g(readings):
    return readings["cornering_speed"] ** 2 / (readings["turn_radius"] * 9.81)


def braking_distance(readings):
    return readings["speed"] ** 2 / (2.0 * readings["deceleration_grip_factor"] * 9.81)


def registry():
    return {
        "motor rpm": (motor_rpm, "rpm"),
        "wheel speed": (wheel_speed, "m/s"),
        "esc temperature": (esc_temperature, "C"),
        "battery voltage": (battery_voltage, "V"),
        "steering angle": (steering_angle, "deg"),
        "suspension travel": (suspension_travel, "mm"),
        "tire slip": (tire_slip, "%"),
        "lateral g": (lateral_g, "g"),
        "braking distance": (braking_distance, "m"),
    }


def analyze(metric, readings):
    key = metric.strip().lower()
    entry = registry().get(key)
    if entry is None:
        raise ValueError("unknown metric: %s" % metric)
    return entry[0](readings)


def format_result(metric, readings):
    key = metric.strip().lower()
    value = analyze(key, readings)
    return "%-18s %10.3f %s" % (key, value, registry()[key][1])


def main():
    runs = [
        ("motor rpm", {"gear_ratio": 4.5, "motor_frequency": 12000.0}),
        ("esc temperature", {"thermistor_readings": [48.0, 51.5, 53.0], "ambient_offset": 6.0}),
        ("battery voltage", {"cell_readings": [4.08, 4.11], "voltage_sag": 0.35}),
        ("tire slip", {"driven_wheel_speed": 46.5, "gps_speed": 41.2}),
        ("braking distance", {"speed": 18.0, "deceleration_grip_factor": 1.1}),
        ("wheel speed", {"rpm": 9000.0, "tire_circumference": 0.31}),
    ]
    for metric, readings in runs:
        print(format_result(metric, readings))


if __name__ == "__main__":
    main()

