HEELFLIP_BONUS = 1.5


def unpack_pair(trick, attributes):
    values = list(attributes)
    if len(values) != 2:
        raise ValueError("%s expects exactly two attributes, got %d" % (trick, len(values)))
    for value in values:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("%s attributes must be numbers, got %r" % (trick, value))
    return values[0], values[1]


def ollie(attributes):
    height, air_time = unpack_pair("ollie", attributes)
    return height * air_time


def kickflip(attributes):
    rotation_speed, pop_height = unpack_pair("kickflip", attributes)
    return rotation_speed + pop_height


def heelflip(attributes):
    return kickflip(attributes) * HEELFLIP_BONUS


def pop_shove_it(attributes):
    rotation_angle, hang_time = unpack_pair("pop shove it", attributes)
    return rotation_angle * hang_time


def manual(attributes):
    balance_duration, speed = unpack_pair("manual", attributes)
    return balance_duration * speed


def nose_manual(attributes):
    return manual(attributes) * 2


def grind(attributes):
    ledge_distance, style_difficulty = unpack_pair("grind", attributes)
    return ledge_distance * style_difficulty


def slide(attributes):
    rail_length, friction_factor = unpack_pair("slide", attributes)
    return rail_length * friction_factor


def drop_in(attributes):
    ramp_height, transition_steepness = unpack_pair("drop in", attributes)
    return ramp_height * transition_steepness


def normalize_trick(trick):
    if not isinstance(trick, str):
        raise TypeError("trick must be a string, got %r" % (trick,))
    return "_".join(trick.lower().replace("-", " ").split())


TRICK_TABLE = {
    "ollie": ollie,
    "kickflip": kickflip,
    "heelflip": heelflip,
    "pop_shove_it": pop_shove_it,
    "manual": manual,
    "nose_manual": nose_manual,
    "grind": grind,
    "slide": slide,
    "drop_in": drop_in,
}


def score(trick, attributes):
    key = normalize_trick(trick)
    if key not in TRICK_TABLE:
        raise ValueError("unknown trick: %s" % trick)
    return TRICK_TABLE[key](attributes)


def format_line(label, points):
    return "%-14s %8.2f points" % (label, points)


def main():
    run = [
        ("ollie", [1.2, 0.8]),
        ("kickflip", [220, 0.6]),
        ("heelflip", [220, 0.6]),
        ("pop shove it", [180, 0.7]),
        ("manual", [5, 2]),
        ("nose-manual", [5, 2]),
        ("grind", [4.5, 3]),
        ("slide", [6, 1.4]),
        ("drop in", [3, 2.5]),
    ]
    total = 0.0
    for trick, attributes in run:
        points = score(trick, attributes)
        print(format_line(trick, points))
        total += points
    print(format_line("TOTAL", total))


if __name__ == "__main__":
    main()

