def distance_points(data):
    span = data["distance"] - data["k_point"]
    return data.get("base", 60.0) + span * data.get("meter_value", 1.8)


def style_points(scores):
    if isinstance(scores, dict):
        scores = scores["judges"]
    if len(scores) != 5:
        raise ValueError("exactly five judge scores are required")
    return sum(sorted(float(score) for score in scores)[1:4])


def wind_compensation(data):
    velocity = data["velocity"]
    factor = data.get("head_factor", 8.0) if velocity >= 0 else data.get("tail_factor", 12.0)
    return -velocity * factor


def gate_compensation(data):
    return -data["gate_delta"] * data.get("gate_factor", 3.6)


def landing_deduction(data):
    fault = max(data["telemark_fault"], 0.0)
    return min(fault * 0.25, 5.0)


def flight_deduction(data):
    spread = abs(data["left_ski"] - data["right_ski"])
    return min(max(spread - 2.0, 0.0) * 0.4, 4.0)


def equipment_penalty(data):
    excess = data["porosity"] - data.get("porosity_limit", 40.0)
    return 5.0 + excess * 0.5 if excess > 0 else 0.0


def total_score(data):
    positives = (distance_points(data) + style_points(data) +
                 wind_compensation(data) + gate_compensation(data))
    negatives = landing_deduction(data) + flight_deduction(data) + equipment_penalty(data)
    return positives - negatives


def ranking_tier(total):
    for cutoff, name in ((130.0, "elite"), (110.0, "advanced"), (90.0, "standard")):
        if total >= cutoff:
            return name
    return "development"


COMPONENTS = {
    "distance points": distance_points, "style points": style_points,
    "wind compensation": wind_compensation, "gate compensation": gate_compensation,
    "landing deduction": landing_deduction, "flight deduction": flight_deduction,
    "equipment penalty": equipment_penalty, "total score": total_score,
    "ranking tier": ranking_tier}


def evaluate(component, data):
    key = component.strip().lower()
    if key not in COMPONENTS:
        raise KeyError("unknown component: %s" % component)
    return COMPONENTS[key](data)


def main():
    jump = {"distance": 132.5, "k_point": 125.0, "velocity": 1.4, "gate_delta": 2,
            "judges": [18.0, 18.5, 19.0, 18.5, 17.5], "telemark_fault": 4.0,
            "left_ski": 6.0, "right_ski": 9.5, "porosity": 38.0}
    for component in ("distance points", "style points", "wind compensation",
                      "gate compensation", "landing deduction", "flight deduction",
                      "equipment penalty", "total score"):
        print("%-20s %7.2f" % (component, evaluate(component, jump)))
    print("tier: %s" % evaluate("ranking tier", evaluate("total score", jump)))


if __name__ == "__main__":
    main()

