    return data["horsepower"] * PROPELLER_EFFICIENCY


def hawser_tension(data):
    weight = data["towline_weight"]
    span = data["span"]
    sag = data["sag"]
    return (weight * span * span) / (8.0 * sag)


def wake_wash(data):
    speed = data["speed"]
    draft = data["draft"]
    return 0.04 * speed * speed * (draft ** 0.5)


def hull_resistance(data):
    block = data["block_coefficient"]
    area = data["wetted_area"]
    speed = data["speed"]
    return 0.5 * WATER_DENSITY * area * block * speed * speed


def propeller_wash(data):
    thrust = data["thrust"]
    diameter = data["propeller_diameter"]
    return 2.5 * diameter * (thrust ** 0.5)


def towline_dip(data):
    weight = data["towline_weight"]
    span = data["span"]
    tension = data["tension"]
    return (weight * span * span) / (8.0 * tension)


def turning_moment(data):
    return data["side_force"] * data["lever_arm"]


def stopping_distance(data):
    speed = data["speed"]
    deceleration = data["reverse_thrust"] * GRAVITY / data["displacement"]
    return (speed * speed) / (2.0 * deceleration)


def fuel_consumption(data):
    return data["engine_load_factor"] * data["hours"] * data["burn_rate"]


