import math


UNITS = {
    "stroke rate": "spm", "drive time": "s", "recovery time": "s", "split time": "s/500m",
    "distance per stroke": "m", "hull speed": "m/s", "drag": "N", "catch angle": "deg", "finish angle": "deg",
}


def stroke_rate(data):
    if data["cycle_time"] <= 0:
        raise ValueError("cycle_time must be positive")
    return 60.0 / data["cycle_time"]


def drive_time(data):
    return data["finish_time"] - data["catch_time"]


def recovery_time(data):
    return data["cycle_time"] - drive_time(data)


def split_time(data):
    if data["speed"] <= 0:
        raise ValueError("speed must be positive")
    return 500.0 / data["speed"]


def distance_per_stroke(data):
    return data["speed"] * 60.0 / stroke_rate(data)


def hull_speed(data):
    return 1.25 * math.sqrt(data["waterline_length"])


def drag(data):
    return data["wetted_area"] * data["speed"] ** 2


def sweep_angle(reach, oar_length):
    if oar_length <= 0 or abs(reach) > oar_length:
        raise ValueError("reach must not exceed the oar length")
    return math.degrees(math.asin(reach / oar_length))


def catch_angle(data):
    return sweep_angle(data["catch_reach"], data["oar_length"])


def finish_angle(data):
    return -sweep_angle(data["finish_reach"], data["oar_length"])


def assess(metric, data):
    handlers = {
        "stroke rate": stroke_rate, "drive time": drive_time, "recovery time": recovery_time,
        "split time": split_time, "distance per stroke": distance_per_stroke, "hull speed": hull_speed,
        "drag": drag, "catch angle": catch_angle, "finish angle": finish_angle,
    }
    if metric not in handlers:
        raise ValueError("unknown metric: %s" % metric)
    return handlers[metric](data)


def format_report(data):
    return "\n".join("%-20s %8.2f %s" % (m, assess(m, data), UNITS[m]) for m in UNITS)


def main():
    crew = {
        "cycle_time": 2.8, "catch_time": 0.4, "finish_time": 1.2, "speed": 4.8, "waterline_length": 18.0,
        "wetted_area": 3.2, "oar_length": 3.7, "catch_reach": 2.2, "finish_reach": 1.4,
    }
    print(format_report(crew))
    print("projected 500m split: %.1f s" % assess("split time", crew))


if __name__ == "__main__": main()

