import math

def grain_size(values):
    mean_mm = sum(values["sieve_diameters_mm"]) / len(values["sieve_diameters_mm"])
    friction_angle = 28.0 + 6.0 * math.log10(1.0 + mean_mm)
    return {"mean_grain_mm": round(mean_mm, 3), "friction_angle_deg": round(friction_angle, 2)}


def water_content(values):
    dry = values["dry_sand_mass_kg"]
    if dry <= 0:
        raise ValueError("dry sand mass must be positive")
    saturation = 100.0 * values["water_mass_kg"] / dry
    return {"saturation_percent": round(saturation, 2), "capillary_bridges": 1.0 <= saturation <= 12.0}


def base_width(values):
    required = 2.0 * values["intended_height_m"]
    return {"required_width_m": round(required, 2), "adequate": values["base_width_m"] >= required}


def tower_height(values):
    slump_ratio = values["slump_cm"] / values["test_cylinder_cm"]
    safe = 2.4 * values["base_width_m"] * (1.0 - slump_ratio)
    return {"max_safe_height_m": round(max(safe, 0.0), 2), "slump_ratio": round(slump_ratio, 3)}


def compaction_force(values):
    energy = values["tamper_weight_n"] * values["strikes"] * values["layer_thickness_m"]
    return {"compaction_energy_j": round(energy, 2), "per_strike_j": round(energy / values["strikes"], 3)}


def collapse_threshold(values):
    drag = 1.2 * 1.225 * values["height_m"]
    return {"critical_wind_mps": round(math.sqrt(2000.0 * values["cohesion_kpa"] / drag), 2)}


def drying_time(values):
    rate = 0.12 * (1.0 + 0.4 * values["wind_mps"]) * (0.3 + 0.7 * values["sun_index"])
    hours = values["water_mass_kg"] / (rate * values["exposed_area_m2"])
    return {"drying_hours": round(hours, 2), "evaporation_kg_per_m2h": round(rate, 4)}


def moat_depth(values):
    angle = math.radians(values["friction_angle_deg"])
    setback = values["depth_m"] / math.tan(angle) + 0.15
    return {"moat_depth_m": values["depth_m"], "safe_setback_m": round(setback, 2)}


def load_capacity(values):
    strength = values["cohesion_kpa"] * 1000.0 * values["roof_area_m2"]
    spare = strength / 9.81 - values["roof_mass_kg"]
    return {"extra_load_kg": round(spare, 2), "crumbles": spare <= 0.0}


def check(parameter, values):
    table = {fn.__name__.replace("_", " "): fn for fn in (grain_size, water_content, base_width,
             tower_height, compaction_force, collapse_threshold, drying_time, moat_depth,
             load_capacity)}
    key = parameter.strip().lower().replace("_", " ")
    if key not in table:
        raise ValueError("unknown parameter: %s (known: %s)" % (parameter, ", ".join(sorted(table))))
    return table[key](values)


def format_report(parameter, result):
    return "%-18s -> %s" % (parameter, ", ".join("%s=%s" % item for item in result.items()))


def main():
    plan = [
        ("water content", {"water_mass_kg": 42.0, "dry_sand_mass_kg": 600.0}),
        ("grain size", {"sieve_diameters_mm": [0.35, 0.42, 0.28, 0.51]}),
        ("base width", {"base_width_m": 3.6, "intended_height_m": 1.7}),
        ("tower height", {"slump_cm": 3.0, "test_cylinder_cm": 15.0, "base_width_m": 3.6}),
        ("compaction force", {"tamper_weight_n": 85.0, "strikes": 24, "layer_thickness_m": 0.12}),
        ("collapse threshold", {"cohesion_kpa": 1.4, "height_m": 1.7}),
        ("drying time", {"water_mass_kg": 42.0, "wind_mps": 4.5, "sun_index": 0.8, "exposed_area_m2": 9.0}),
        ("moat depth", {"depth_m": 0.4, "friction_angle_deg": 32.0}),
        ("load capacity", {"cohesion_kpa": 1.4, "roof_area_m2": 0.25, "roof_mass_kg": 18.0}),
    ]
    for parameter, values in plan:
        print(format_report(parameter, check(parameter, values)))
    print("saturation of the mix: %.2f%%" % check("water content", plan[0][1])["saturation_percent"])

if __name__ == "__main__":
    main()

