    """Cut depth that keeps every tier level, allowing for taper and scribe gap."""
    lower = log_diameter(data['lower'])
    upper = log_diameter(data['upper'])
    return lower / 2.0 - data['scribe_gap'] + (lower - upper) / 4.0

def saddle_length(data):
    """Saddle spans the intersecting log diameter plus a clearance allowance."""
    return log_diameter(data['lower']) + data['clearance']

def tail_overhang(data):
    """Corner tails run one and a half diameters, never less than a foot."""
    return max(12.0, 1.5 * log_diameter(data))

def shrinkage_allowance(data):
    """Vertical openings grow by the settling rate of the chosen species."""
    species = data['species'].strip().lower()
    if species not in SHRINKAGE_RATES:
        raise ValueError('unknown wood species: ' + data['species'])
    return data['opening_height'] * SHRINKAGE_RATES[species]

def chinking_gap(data):
    """Space left over once the backer gasket fills part of the scribe gap."""
    return max(0.0, scribe_width(data) - data['gasket'])

def sill_plate(data):
    """Diagonal the foundation logs must measure to sit at ninety degrees."""
    return math.hypot(data['length'], data['width'])

def peak_height(data):
    """Gable rise from the roof pitch expressed in rise per twelve of run."""
    return data['pitch'] / 12.0 * (data['span'] / 2.0)

def size(dimension, data):
    table = {
        'log diameter': log_diameter,
        'scribe width': scribe_width,
        'notch depth': notch_depth,
        'saddle length': saddle_length,
        'tail overhang': tail_overhang,
        'shrinkage allowance': shrinkage_allowance,
        'chinking gap': chinking_gap,
        'sill plate': sill_plate,
        'peak height': peak_height,
    }
    key = dimension.strip().lower().replace('_', ' ')
    if key not in table:
        raise ValueError('no calculation for dimension: ' + dimension)
    return table[key](data)

def format_inches(value):
    """Round to the nearest sixteenth and render as a carpenter's fraction."""
    sixteenths = int(round(value * 16))
    whole, rem = divmod(sixteenths, 16)
    if rem == 0:
        return '%d"' % whole
    divisor = math.gcd(rem, 16)
    return '%d %d/%d"' % (whole, rem // divisor, 16 // divisor)

def measurement_report(cabin):
    jobs = (
        ('log diameter', cabin['upper']),
        ('scribe width', cabin['scribe']),
        ('notch depth', cabin['logs']),
        ('saddle length', cabin['logs']),
        ('tail overhang', cabin['upper']),
        ('chinking gap', cabin['scribe']),
        ('shrinkage allowance', cabin['openings']),
        ('sill plate', cabin['foundation']),
        ('peak height', cabin['roof']),
    )
    return ['%-20s %s' % (name, format_inches(size(name, payload))) for name, payload in jobs]

def main():
    upper = {'butt': 11.25, 'tip': 10.0}
    lower = {'butt': 12.0, 'tip': 10.75}
    cabin = {
        'upper': upper,
        'lower': lower,
        'logs': {'upper': upper, 'lower': lower, 'scribe_gap': 0.25, 'clearance': 0.5},
        'scribe': {'upper_contour': 3.5, 'lower_contour': 3.0, 'gasket': 0.375},
        'openings': {'species': 'Douglas Fir', 'opening_height': 80.0},
        'foundation': {'length': 288.0, 'width': 192.0},
        'roof': {'span': 192.0, 'pitch': 8.0},
    }
    print('Log cabin carpentry measurements')
    for line in measurement_report(cabin):
        print(line)


if __name__ == '__main__':
    main()

