import math


def require(measurements, *keys):
    missing = [key for key in keys if key not in measurements]
    if missing:
        raise KeyError("missing measurements: " + ", ".join(missing))
    return [float(measurements[key]) for key in keys]


def foundation_depth(measurements):
    (total_height,) = require(measurements, "total_height")
    return total_height / 4.0


def batter_angle(measurements):
    base_width, top_width, total_height = require(
        measurements, "base_width", "top_width", "total_height")
    inset = (base_width - top_width) / 2.0
    return math.degrees(math.atan(inset / total_height))


def hearting_volume(measurements):
    length, total_height, core_width = require(
        measurements, "length", "total_height", "core_width")
    return length * total_height * core_width


def through_stone_frequency(measurements):
    spacing, tier_height = require(measurements, "through_spacing", "tier_height")
    return 1.0 / (spacing * tier_height)


def coping_weight(measurements):
    length, coping_height, top_width, density = require(
        measurements, "length", "coping_height", "top_width", "stone_density")
    return length * coping_height * top_width * density


def friction_lock(measurements):
    stone_length, stone_height, contact_ratio = require(
        measurements, "stone_length", "stone_height", "contact_ratio")
    return stone_length * stone_height * contact_ratio


def drainage_flow(measurements):
    length, total_height, void_fraction, rainfall = require(
        measurements, "length", "total_height", "void_fraction", "rainfall_rate")
    return length * total_height * void_fraction * rainfall * 1000.0


def wall_height(measurements):
    depth = foundation_depth(measurements)
    tiers, tier_height, coping_height = require(
        measurements, "tiers", "tier_height", "coping_height")
    return depth + tiers * tier_height + coping_height


def subsidence_risk(measurements):
    length, base_width, top_width, total_height, density, capacity = require(
        measurements, "length", "base_width", "top_width", "total_height",
        "stone_density", "bearing_capacity")
    volume = length * total_height * (base_width + top_width) / 2.0
    pressure = volume * density * 9.81 / (length * base_width) / 1000.0
    return pressure / capacity


REGISTRY = {
    "foundation depth": (foundation_depth, "m"),
    "batter angle": (batter_angle, "deg"),
    "hearting volume": (hearting_volume, "m3"),
    "through stone frequency": (through_stone_frequency, "stones/m2"),
    "coping weight": (coping_weight, "kg"),
    "friction lock": (friction_lock, "m2"),
    "drainage flow": (drainage_flow, "L/h"),
    "wall height": (wall_height, "m"),
    "subsidence risk": (subsidence_risk, "ratio"),
}


def compute(part, measurements):
    if part not in REGISTRY:
        raise ValueError("unknown part: " + str(part))
    calculate, _units = REGISTRY[part]
    return calculate(measurements)


def format_report(part, measurements):
    value = compute(part, measurements)
    units = REGISTRY[part][1]
    return "{:<24}{:>12.3f} {}".format(part, value, units)


