    site = {
        "total_height": 1.6, "base_width": 0.8, "top_width": 0.4,
        "length": 12.0, "core_width": 0.25, "through_spacing": 1.0,
        "tier_height": 0.35, "tiers": 3, "coping_height": 0.15,
        "stone_density": 2400.0, "stone_length": 0.45, "stone_height": 0.2,
        "contact_ratio": 0.35, "void_fraction": 0.12, "rainfall_rate": 0.05,
        "bearing_capacity": 150.0,
    }
    print("Drystone wall engineering report")
    for part in REGISTRY:
        print(format_report(part, site))
    print("trench depth for a 1.6 m wall: {:.2f} m".format(
        compute("foundation depth", {"total_height": 1.6})))


if __name__ == "__main__":
    main()

