    scale = inputs["bed_area_cm2"] / inputs["sample_area_cm2"]
    grams = inputs["sample_count"] * scale * inputs["worm_mass_g"]
    return round(grams / 1000.0, 2)

def feeding_rate(inputs):
    biomass = inputs.get("biomass_kg")
    if biomass is None:
        biomass = worm_biomass(inputs)
    return round(biomass * inputs.get("appetite_ratio", 0.5), 2)

def moisture_level(inputs):
    dry = inputs["cardboard_kg"] + inputs["peat_kg"]
    total = dry + inputs["water_kg"]
    return round(100.0 * inputs["water_kg"] / total, 1)

def temperature_reading(inputs):
    adjustments = {"winter": -3.5, "spring": 0.5, "summer": 2.5, "autumn": -1.0}
    season = inputs.get("season", "spring")
    if season not in adjustments:
        raise ValueError("unknown season: %s" % season)
    return round(inputs["thermometer_c"] + adjustments[season], 1)

def acidity(inputs):
    deficit = inputs.get("target_ph", 6.8) - inputs["soil_ph"]
    if deficit <= 0:
        return 0.0
    return round(deficit * inputs["buffer_factor"] * inputs["bedding_kg"] / 100.0, 3)

def bedding_depth(inputs):
    insulating = inputs["depth_cm"] - inputs["freeboard_cm"]
    return insulating >= inputs.get("min_insulation_cm", 20)

def harvest_time(inputs):
    remaining = inputs["bedding_kg"] * (1.0 - inputs["processed_fraction"])
    weekly = feeding_rate(inputs) * 7.0
    return round(remaining / weekly, 1)

def casting_volume(inputs):
    yield_ratio = inputs.get("casting_ratio", 0.45)
    moisture_loss = 1.0 - moisture_level(inputs) / 200.0
    return round(bin_volume(inputs) * yield_ratio * moisture_loss, 2)


FACTOR_MAP = {
    "bin_volume": bin_volume, "worm_biomass": worm_biomass,
    "feeding_rate": feeding_rate, "moisture_level": moisture_level,
    "temperature_reading": temperature_reading, "acidity": acidity,
    "bedding_depth": bedding_depth, "harvest_time": harvest_time,
    "casting_volume": casting_volume,
}

def manage(factor, inputs):
    key = factor.strip().lower().replace(" ", "_")
    if key not in FACTOR_MAP:
        raise KeyError("unsupported factor: %s" % factor)
    return FACTOR_MAP[key](inputs)

def build_report(inputs):
    lines = []
    for factor in sorted(FACTOR_MAP):
        lines.append("%-20s %s" % (factor.replace("_", " "), manage(factor, inputs)))
    return "\n".join(lines)

def main():
    facility = {
        "length_cm": 90.0, "width_cm": 60.0, "depth_cm": 45.0, "freeboard_cm": 10.0,
        "bed_area_cm2": 5400.0, "sample_area_cm2": 100.0, "sample_count": 38,
        "worm_mass_g": 0.55, "cardboard_kg": 4.0, "peat_kg": 6.0, "water_kg": 22.0,
        "thermometer_c": 18.0, "season": "autumn", "soil_ph": 5.9,
        "buffer_factor": 1.4, "bedding_kg": 32.0, "processed_fraction": 0.35,
    }
    print(build_report(facility))
    print("food for 10 kg of worms: %s kg/day" % manage("feeding rate", {"biomass_kg": 10}))


if __name__ == "__main__":
    main()

