def to_floats(data, count):
    values = tuple(float(value) for value in data)
    if len(values) != count:
        raise ValueError("expected %d value(s), got %d" % (count, len(values)))
    if any(value < 0 for value in values):
        raise ValueError("carcass measurements cannot be negative")
    return values


def marbling_score(data):
    flecks, = to_floats(data, 1)
    score = 100.0 + 22.0 * flecks
    return round(min(score, 1100.0), 1)


def ribeye_area(data):
    length, width = to_floats(data, 2)
    return round(3.14159265 / 4.0 * length * width, 2)


def backfat_thickness(data):
    readings = to_floats(data, 3)
    mean = sum(readings) / len(readings)
    return round(round(mean / 0.05) * 0.05, 2)


def pelvic_fat(data):
    kidney, pelvic, heart, carcass = to_floats(data, 4)
    if carcass == 0:
        raise ValueError("carcass weight must be greater than zero")
    return round((kidney + pelvic + heart) / carcass * 100.0, 2)


def carcass_weight(data):
    hot_weight, shrink_percent = to_floats(data, 2)
    return round(hot_weight * (1.0 - shrink_percent / 100.0), 1)


def maturity_score(data):
    ossification, lean_color = to_floats(data, 2)
    bone_index = min(ossification, 100.0) / 100.0 * 4.0
    color_index = min(max(lean_color, 1.0), 5.0) - 1.0
    return "ABCDE"[int(round((bone_index + color_index) / 2.0))]


def yield_grade(data):
    backfat, kph_percent, hot_weight, rib_area = to_floats(data, 4)
    grade = (2.50 + 2.50 * backfat + 0.20 * kph_percent
             + 0.0038 * hot_weight - 0.32 * rib_area)
    return round(min(max(grade, 1.0), 5.0), 1)


def quality_grade(data):
    flecks, ossification, lean_color = to_floats(data, 3)
    score = marbling_score([flecks])
    maturity = maturity_score([ossification, lean_color])
    if maturity in "AB":
        for limit, name in ((700, "Prime"), (500, "Choice"), (400, "Select")):
            if score >= limit:
                return name
        return "Standard"
    if score >= 500:
        return "Commercial"
    return "Utility"


def dressing_percentage(data):
    hot_weight, live_weight = to_floats(data, 2)
    if live_weight == 0:
        raise ValueError("live weight must be greater than zero")
    return round(hot_weight / live_weight * 100.0, 2)


def rank(metric, data):
    table = {
        "marbling score": marbling_score,
        "ribeye area": ribeye_area,
        "backfat thickness": backfat_thickness,
        "pelvic fat": pelvic_fat,
        "carcass weight": carcass_weight,
        "maturity score": maturity_score,
        "yield grade": yield_grade,
        "quality grade": quality_grade,
        "dressing percentage": dressing_percentage,
    }
    key = metric.strip().lower().replace("_", " ")
    if key not in table:
        raise KeyError("unknown carcass metric: %r" % metric)
    return table[key](data)


def main():
    evaluations = [
        ("marbling score", [24]),
        ("ribeye area", [8.5, 2.1]),
        ("backfat thickness", [0.42, 0.48, 0.45]),
        ("pelvic fat", [9.0, 4.5, 6.5, 800.0]),
        ("carcass weight", [790.0, 2.5]),
        ("maturity score", [35.0, 2.0]),
        ("yield grade", [0.45, 2.5, 790.0, 14.0]),
        ("quality grade", [24, 35.0, 2.0]),
        ("dressing percentage", [772.0, 1250.0]),
    ]
    for metric, data in evaluations:
        print("%-20s %s" % (metric + ":", rank(metric, data)))


if __name__ == "__main__":
    main()

