def ratio(numerator, denominator):
    if denominator == 0:
        return 0.0
    return numerator / denominator


def parse_counts(counts):
    fields = ("at_bats", "singles", "doubles", "triples", "home_runs",
              "walks", "strikeouts", "hit_by_pitch", "sac_flies")
    if len(counts) != len(fields):
        raise ValueError("expected %d raw counts, got %d" % (len(fields), len(counts)))
    stats = dict(zip(fields, counts))
    for name, value in stats.items():
        if value < 0:
            raise ValueError("%s cannot be negative" % name)
    stats["hits"] = (stats["singles"] + stats["doubles"]
                     + stats["triples"] + stats["home_runs"])
    if stats["hits"] > stats["at_bats"]:
        raise ValueError("hits cannot exceed at bats")
    return stats


def total_bases(stats):
    return (stats["singles"] + 2 * stats["doubles"]
            + 3 * stats["triples"] + 4 * stats["home_runs"])


def batting_average(stats):
    return round(ratio(stats["hits"], stats["at_bats"]), 3)


def on_base_percentage(stats):
    reached = stats["hits"] + stats["walks"] + stats["hit_by_pitch"]
    chances = (stats["at_bats"] + stats["walks"]
               + stats["hit_by_pitch"] + stats["sac_flies"])
    return round(ratio(reached, chances), 3)


def slugging(stats):
    return round(ratio(total_bases(stats), stats["at_bats"]), 3)


def runs_created(stats):
    on_base = stats["hits"] + stats["walks"]
    opportunities = stats["at_bats"] + stats["walks"]
    return round(ratio(on_base * total_bases(stats), opportunities), 2)


def isolated_power(stats):
    return round(slugging(stats) - batting_average(stats), 3)


def babip(stats):
    balls_in_play = (stats["at_bats"] - stats["strikeouts"]
                     - stats["home_runs"] + stats["sac_flies"])
    return round(ratio(stats["hits"] - stats["home_runs"], balls_in_play), 3)


def walk_to_strikeout(stats):
    return round(ratio(stats["walks"], stats["strikeouts"]), 3)


def on_base_plus_slugging(stats):
    return round(on_base_percentage(stats) + slugging(stats), 3)


def evaluate(player):
    counts, requested = player
    stats = parse_counts(counts)
    routines = {
        "batting average": batting_average,
        "on base percentage": on_base_percentage,
        "slugging": slugging,
        "total bases": total_bases,
        "runs created": runs_created,
        "isolated power": isolated_power,
        "babip": babip,
        "walk to strikeout ratio": walk_to_strikeout,
        "ops": on_base_plus_slugging,
    }
    results = []
    for name in requested:
