def safe_ratio(part, whole):
    if whole == 0:
        return 0.0
    return part / whole


def as_percentage(part, whole):
    return round(safe_ratio(part, whole) * 100.0, 1)


def first_serve_percentage(first_serves_in, service_points):
    return as_percentage(first_serves_in, service_points)


def first_serve_points_won(points_won, first_serves_in):
    return as_percentage(points_won, first_serves_in)


def second_serve_points_won(points_won, second_serves_played):
    return as_percentage(points_won, second_serves_played)


def break_points_saved(saved, faced):
    return as_percentage(saved, faced)


def break_points_converted(converted, opportunities):
    return as_percentage(converted, opportunities)


def return_points_won(points_won, return_points_played):
    return as_percentage(points_won, return_points_played)


def total_points_won(points_won, points_played):
    return as_percentage(points_won, points_played)


def aces_per_game(aces, games):
    return round(safe_ratio(aces, games), 2)


def double_fault_ratio(double_faults, service_points):
    return round(safe_ratio(double_faults, service_points), 3)


METRIC_ROUTINES = {
    routine.__name__: routine
    for routine in (first_serve_percentage, first_serve_points_won,
                    second_serve_points_won, break_points_saved,
                    break_points_converted, return_points_won,
                    total_points_won, aces_per_game, double_fault_ratio)
}


def validate_request(counts, metrics):
    if len(counts) != 2 * len(metrics):
        raise ValueError("each metric needs exactly two rally counts")
    if any(value < 0 for value in counts):
        raise ValueError("rally counts must not be negative")
    unknown = [name for name in metrics if name not in METRIC_ROUTINES]
    if unknown:
        raise KeyError("unknown metrics: %s" % ", ".join(unknown))


def summarize(match):
    counts, metrics = match
    validate_request(counts, metrics)
    pairs = zip(counts[0::2], counts[1::2])
    return [METRIC_ROUTINES[name](part, whole)
            for name, (part, whole) in zip(metrics, pairs)]


def main():
    metrics = ["first_serve_percentage", "aces_per_game", "double_fault_ratio"]
    counts = [32, 50, 9, 21, 5, 50]
    for name, value in zip(metrics, summarize((counts, metrics))):
        print("%-26s %s" % (name.replace("_", " ").title(), value))


if __name__ == "__main__":
    main()

