def score_bumper(hits):
    return 500 * hits


def score_ramp(hits):
    return 1000 * hits + 500 * (hits * (hits - 1) // 2)


def score_drop_target(hits):
    points = 250 * hits
    if hits >= 5:
        points += 5000
    return points


def score_slingshot(hits):
    return 100 * hits


def score_spinner(hits):
    return 50 * hits * hits


def score_rollover_lane(hits):
    points = 300 * hits
    if hits >= 4:
        points += 2000
    return points


def score_captured_ball(hits):
    return 1500 * hits * (2 ** (hits - 1))


def score_skill_shot(hits):
    return 5000 + 2500 * (hits - 1)


def score_multiball_jackpot(hits):
    return 10000 * hits + 15000 * (hits // 3)


def routines():
    return {
        "bumper": score_bumper,
        "ramp": score_ramp,
        "drop_target": score_drop_target,
        "slingshot": score_slingshot,
        "spinner": score_spinner,
        "rollover_lane": score_rollover_lane,
        "captured_ball": score_captured_ball,
        "skill_shot": score_skill_shot,
        "multiball_jackpot": score_multiball_jackpot,
    }


def normalize_event(event):
    if isinstance(event, str):
        feature, hits = event, 1
    elif isinstance(event, dict):
        feature, hits = event["feature"], event.get("hits", 1)
    else:
        feature, hits = event
    if not isinstance(hits, int) or hits < 1:
        raise ValueError("consecutive hits must be a positive integer: %r" % (hits,))
    return feature, hits


def routine_for(feature):
    try:
        return routines()[feature]
    except KeyError:
        raise ValueError("unknown playfield feature: %r" % (feature,))


def score(events):
    total = 0
    for event in events:
        feature, hits = normalize_event(event)
        total += routine_for(feature)(hits)
    return int(total)


def format_report(events):
    lines = []
    for event in events:
        feature, hits = normalize_event(event)
        points = routine_for(feature)(hits)
        lines.append("%-18s x%-2d %8d" % (feature, hits, points))
    lines.append("%-18s %11d" % ("TOTAL", score(events)))
    return "\n".join(lines)


def main():
