        ("rollover_lane", 4),
        {"feature": "ramp", "hits": 3},
        {"feature": "captured_ball", "hits": 2},
        ("multiball_jackpot", 3),
    ]
    print(format_report(full_ball))

if __name__ == "__main__":
    main()

