def calibrate_altitude(volts):
    return round(volts * 37.5, 1)


def calibrate_ground_speed(volts):
    return round(volts * 12.0, 1)


def calibrate_ascent_rate(volts):
    return round((volts - 0.5) * 4.0, 2)


def calibrate_descent_rate(volts):
    return round((2.5 - volts) * 3.0, 2)


def calibrate_voltage_sag(volts):
    return round(volts * 0.85, 3)


def calibrate_signal_strength(volts):
    return round(-100.0 + volts * 20.0, 1)


def calibrate_flight_time(volts):
    return round(volts * 9.6, 1)


def calibrate_wind_resistance(volts):
    return round(volts ** 2 * 6.25, 2)


def calibrate_distance_home(volts):
    return round(volts * 250.0, 0)


ROUTINES = {
    "altitude above ground": calibrate_altitude,
    "ground speed": calibrate_ground_speed,
    "ascent rate": calibrate_ascent_rate,
    "descent rate": calibrate_descent_rate,
    "voltage sag": calibrate_voltage_sag,
    "signal strength": calibrate_signal_strength,
    "flight time remaining": calibrate_flight_time,
    "wind resistance": calibrate_wind_resistance,
    "distance to home": calibrate_distance_home,
}


def check_telemetry(voltages, names):
    if len(voltages) != len(names):
        raise ValueError("each voltage needs exactly one reading name")
    unknown = [name for name in names if name not in ROUTINES]
    if unknown:
        raise ValueError("unsupported readings: " + ", ".join(unknown))


def monitor(telemetry):
    voltages, names = telemetry
    check_telemetry(voltages, names)
    return [ROUTINES[name](volts) for volts, name in zip(voltages, names)]


def format_report(names, values):
    lines = []
    for name, value in zip(names, values):
        lines.append("{:<22}{}".format(name + ":", value))
    return "\n".join(lines)


def main():
    names = [
        "altitude above ground",
        "ground speed",
        "ascent rate",
        "voltage sag",
        "signal strength",
        "flight time remaining",
        "wind resistance",
        "distance to home",
    ]
    voltages = [1.2, 2.4, 1.75, 11.1, 3.3, 2.0, 1.6, 0.8]
    print(format_report(names, monitor((voltages, names))))


if __name__ == "__main__":
    main()

