import math
import re

CODE_PATTERN = re.compile(
    r"^(?:P|LT|ST|T)?(\d{3})/(\d{2})\s*[A-Z]{1,2}\s*(\d{2})(?:\s+(\d{2,3})([A-Z]))?$"
)

LOAD_INDEX_TABLE = {
    81: 1019, 82: 1047, 83: 1074, 84: 1102, 85: 1135, 86: 1168, 87: 1201,
    88: 1235, 89: 1279, 90: 1323, 91: 1356, 92: 1389, 93: 1433, 94: 1477,
    95: 1521, 96: 1565, 97: 1609, 98: 1653, 99: 1709, 100: 1764,
}

SPEED_RATING_TABLE = {
    "L": 75, "M": 81, "N": 87, "P": 93, "Q": 99, "R": 106, "S": 112,
    "T": 118, "U": 124, "H": 130, "V": 149, "W": 168, "Y": 186,
}


def parse_code(tire):
    match = CODE_PATTERN.match(tire.strip().upper())
    if match is None:
        raise ValueError("unrecognised sidewall code: %r" % tire)
    section, aspect, rim, load, speed = match.groups()
    return {
        "section_mm": int(section),
        "aspect": int(aspect),
        "rim_in": int(rim),
        "load_index": int(load) if load else None,
        "speed_rating": speed,
    }


def tire_width(parts):
    return parts["section_mm"] / 25.4


def aspect_ratio(parts):
    return float(parts["aspect"])


def wheel_diameter(parts):
    return float(parts["rim_in"])


def sidewall_height(parts):
    return tire_width(parts) * parts["aspect"] / 100.0


def overall_diameter(parts):
    return wheel_diameter(parts) + 2 * sidewall_height(parts)


def circumference(parts):
    return math.pi * overall_diameter(parts)


def revolutions_per_mile(parts):
    return 63360.0 / circumference(parts)


def load_index_pounds(parts):
    index = parts["load_index"]
    if index not in LOAD_INDEX_TABLE:
        raise ValueError("no load capacity known for index %r" % index)
    return float(LOAD_INDEX_TABLE[index])


def speed_rating_max_speed(parts):
    rating = parts["speed_rating"]
    if rating not in SPEED_RATING_TABLE:
        raise ValueError("no speed known for rating %r" % rating)
    return float(SPEED_RATING_TABLE[rating])


CALCULATORS = {
    "tire width": tire_width,
    "aspect ratio": aspect_ratio,
    "wheel diameter": wheel_diameter,
    "sidewall height": sidewall_height,
    "overall diameter": overall_diameter,
    "circumference": circumference,
    "revolutions per mile": revolutions_per_mile,
    "load index pounds": load_index_pounds,
    "speed rating max speed": speed_rating_max_speed,
}


def decode(tire, properties):
    parts = parse_code(tire)
    values = []
    for name in properties:
        key = name.strip().lower()
        if key not in CALCULATORS:
            raise KeyError("unknown tire property: %r" % name)
        values.append(CALCULATORS[key](parts))
    return values


def format_report(tire, properties):
    values = decode(tire, properties)
    lines = ["%s:" % tire]
    for name, value in zip(properties, values):
        lines.append("  %-24s %10.2f" % (name, value))
    return "\n".join(lines)


def main():
    print(decode("P205/65R15", ["wheel diameter"]))
    print(format_report("P225/50R16 91S", [
        "tire width",
        "aspect ratio",
        "sidewall height",
        "overall diameter",
        "circumference",
        "revolutions per mile",
        "load index pounds",
        "speed rating max speed",
    ]))


if __name__ == "__main__":
    main()

