def positions():
    return (
        "present", "challenge", "past", "future", "above",
        "below", "advice", "external", "hopes", "outcome",
    )


def interpret_present(base):
    return base * 1.0


def interpret_challenge(base):
    return base * 2.0


def interpret_past(base):
    return base * 0.5


def interpret_future(base):
    return base * 1.5


def interpret_above(base):
    return base * 1.25


def interpret_below(base):
    return base * 0.75


def interpret_advice(base):
    return base * 1.1


def interpret_external(base):
    return base * 0.9


def interpret_hopes(base):
    return base * 1.4


def interpret_outcome(base):
    return base * 2.5


def interpreters():
    return (
        interpret_present, interpret_challenge, interpret_past,
        interpret_future, interpret_above, interpret_below,
        interpret_advice, interpret_external, interpret_hopes,
        interpret_outcome,
    )


def validate_bases(cards):
    values = list(cards)
    expected = len(positions())
    if len(values) != expected:
        raise ValueError("a reading needs exactly %d card values" % expected)
    for value in values:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("card base values must be numbers, got %r" % (value,))
    return values


def normalize_energy(value):
    rounded = round(value, 2)
    if rounded == int(rounded):
        return int(rounded)
    return rounded


def read(cards):
    values = validate_bases(cards)
    routines = interpreters()
    return [normalize_energy(routines[index](base))
            for index, base in enumerate(values)]


def format_reading(energies):
    names = positions()
    width = max(len(name) for name in names)
    return "\n".join("%-*s : %s" % (width, name, energy)
                     for name, energy in zip(names, energies))


def main():
    spread = [3, 5, 8, 4, 6, 2, 10, 7, 9, 1]
    energies = read(spread)
    print(format_reading(energies))
    print("total energy: %s" % normalize_energy(sum(energies)))

if __name__ == "__main__":
    main()

