def normalize(angle):
    """Reduce any angle to the 0-180 range used for aspect comparison."""
    angle = float(angle) % 360.0
    if angle > 180.0:
        angle = 360.0 - angle
    return angle


def within_orb(angle, target, orb):
    return abs(normalize(angle) - target) <= orb


def conjunction(angle):
    return within_orb(angle, 0.0, 10.0)


def sextile(angle):
    return within_orb(angle, 60.0, 6.0)


def square(angle):
    return within_orb(angle, 90.0, 8.0)


def trine(angle):
    return within_orb(angle, 120.0, 8.0)


def opposition(angle):
    return within_orb(angle, 180.0, 10.0)


def quincunx(angle):
    return within_orb(angle, 150.0, 4.0)


def semi_sextile(angle):
    return within_orb(angle, 30.0, 2.0)


def semi_square(angle):
    return within_orb(angle, 45.0, 2.0)


def sesquiquadrate(angle):
    return within_orb(angle, 135.0, 2.0)


def aspects(angle):
    tests = (
        ("Conjunction", conjunction),
        ("Sextile", sextile),
        ("Square", square),
        ("Trine", trine),
        ("Opposition", opposition),
        ("Quincunx", quincunx),
        ("Semi-sextile", semi_sextile),
        ("Semi-square", semi_square),
        ("Sesquiquadrate", sesquiquadrate),
    )
    for name, test in tests:
        if test(angle):
            return name
    return None


def describe(angle):
    name = aspects(angle)
    if name is None:
        return "{0:7.2f} deg: no aspect".format(float(angle))
    return "{0:7.2f} deg: {1}".format(float(angle), name)


def main():
    for angle in (0.0, 15.0, 29.5, 52.0, 60.0, 88.0, 100.0, 118.0, 135.5, 151.0, 175.0, 340.0):
        print(describe(angle))


if __name__ == "__main__":
    main()

