import math


def validate_conditions(conditions):
    years = float(conditions.get("years", 0.0))
    mineral = float(conditions.get("mineral_concentration", 1.0))
    drip = float(conditions.get("drip_rate", 1.0))
    if years < 0.0:
        raise ValueError("years must not be negative")
    if mineral <= 0.0:
        raise ValueError("mineral_concentration must be positive")
    if drip < 0.0:
        raise ValueError("drip_rate must not be negative")
    return years, mineral, drip


def grow_stalactite(years, mineral, drip):
    return 0.10 * years * mineral * min(drip, 4.0)


def grow_stalagmite(years, mineral, drip):
    splash = drip / (1.0 + 0.25 * drip)
    return 0.12 * years * mineral * splash


def grow_column(years, mineral, drip):
    return grow_stalactite(years, mineral, drip) + grow_stalagmite(years, mineral, drip)


def grow_flowstone(years, mineral, drip):
    return 0.05 * years * mineral * math.sqrt(1.0 + drip)


def grow_drapery(years, mineral, drip):
    return 0.08 * years * mineral * min(drip, 2.5)


def grow_soda_straw(years, mineral, drip):
    return 0.20 * years * mineral * min(drip, 1.5)


def grow_helictite(years, mineral, drip):
    capillary = 1.0 / (1.0 + 4.0 * drip)
    return 0.06 * years * mineral * capillary


def grow_cave_pearl(years, mineral, drip):
    agitation = min(drip, 3.0)
    return 3.0 * (years * mineral * agitation / 1000.0) ** (1.0 / 3.0)


def grow_moonmilk(years, mineral, drip):
    return 1.5 * math.sqrt(years * mineral) * (1.0 - math.exp(-drip))


ROUTINES = {
    "stalactite": grow_stalactite,
    "stalagmite": grow_stalagmite,
    "column": grow_column,
    "flowstone": grow_flowstone,
    "drapery": grow_drapery,
    "soda straw": grow_soda_straw,
    "helictite": grow_helictite,
    "cave pearl": grow_cave_pearl,
    "moonmilk": grow_moonmilk,
}


def simulate(conditions):
    years, mineral, drip = validate_conditions(conditions)
    sizes = []
    for name in conditions.get("formations", []):
        key = name.strip().lower()
        if key not in ROUTINES:
            raise KeyError("unknown formation: %s" % name)
        sizes.append(round(ROUTINES[key](years, mineral, drip), 2))
    return sizes


def format_report(conditions, sizes):
    header = "After %g years (mineral %g, drip %g):" % validate_conditions(conditions)
    lines = [header]
    for name, size in zip(conditions["formations"], sizes):
        lines.append("  %-12s %8.2f mm" % (name, size))
    return "\n".join(lines)


def main():
    conditions = {
        "years": 100.0,
        "mineral_concentration": 1.0,
        "drip_rate": 1.0,
        "formations": ["soda straw", "stalactite", "column", "cave pearl", "moonmilk"],
    }
    print(format_report(conditions, simulate(conditions)))
    dry_cave = dict(conditions, drip_rate=0.2, formations=["helictite", "flowstone", "drapery"])
    print(format_report(dry_cave, simulate(dry_cave)))


if __name__ == "__main__":
    main()

