"""Meteor shower intensity forecasting based on observing conditions."""

import math


def validate(conditions):
    latitude = float(conditions["latitude"])
    cloud_cover = float(conditions["cloud_cover"])
    day_of_year = int(conditions["day_of_year"])
    if not -90.0 <= latitude <= 90.0:
        raise ValueError("latitude must lie between -90 and 90 degrees")
    if not 0.0 <= cloud_cover <= 1.0:
        raise ValueError("cloud_cover must lie between 0 and 1")
    if not 1 <= day_of_year <= 366:
        raise ValueError("day_of_year must lie between 1 and 366")
    return latitude, cloud_cover, day_of_year


def peak_distance(day_of_year, peak_day):
    gap = abs(day_of_year - peak_day) % 365
    return min(gap, 365 - gap)


def radiant_factor(latitude, declination):
    altitude = 90.0 - abs(latitude - declination)
    if altitude <= 0.0:
        return 0.0
    return math.sin(math.radians(altitude))


def sky_clarity(cloud_cover):
    return 1.0 - cloud_cover


def activity_factor(distance, width):
    return math.exp(-(distance / width) ** 2)


def hourly_rate(conditions, zhr, declination, peak_day, width):
    latitude, cloud_cover, day_of_year = validate(conditions)
    rate = zhr * radiant_factor(latitude, declination) * sky_clarity(cloud_cover)
    return round(rate * activity_factor(peak_distance(day_of_year, peak_day), width))


def perseids(conditions):
    return hourly_rate(conditions, 120, 58.0, 224, 4.0)


def geminids(conditions):
    return hourly_rate(conditions, 150, 33.0, 348, 3.0)


def leonids(conditions):
    return hourly_rate(conditions, 15, 22.0, 321, 2.5)


def lyrids(conditions):
    return hourly_rate(conditions, 18, 34.0, 112, 2.0)


def orionids(conditions):
    return hourly_rate(conditions, 20, 16.0, 294, 5.0)


def quadrantids(conditions):
    return hourly_rate(conditions, 120, 49.0, 3, 0.7)


def taurids(conditions):
    return hourly_rate(conditions, 10, 14.0, 309, 12.0)


def ursids(conditions):
    return hourly_rate(conditions, 10, 76.0, 356, 1.5)


def draconids(conditions):
    return hourly_rate(conditions, 10, 54.0, 281, 1.0)


def forecast(conditions):
    routines = {
        "perseids": perseids, "geminids": geminids, "leonids": leonids,
        "lyrids": lyrids, "orionids": orionids, "quadrantids": quadrantids,
        "taurids": taurids, "ursids": ursids, "draconids": draconids,
    }
    rates = []
    for name in conditions["showers"]:
        key = name.strip().lower()
        if key not in routines:
