def allele_codes():
    return frozenset({'A', 'a', 'O', 'o', 'S', 's', 'I', 'i', 'C', 'cs'})


def validate_markers(markers):
    unknown = sorted(set(markers) - allele_codes())
    if unknown:
        raise ValueError('unknown genetic markers: ' + ', '.join(unknown))
    return list(markers)


def dosage(markers, allele):
    copies = markers.count(allele)
    if copies >= 2:
        return 1.0
    if copies == 1:
        return 0.5
    return 0.0


def solid(markers):
    return 100.0 if markers.count('a') >= 2 else 0.0


def tabby(markers):
    return 100.0 if 'A' in markers else 0.0


def bicolor(markers):
    return 100.0 * dosage(markers, 'S')


def tortoiseshell(markers):
    if 'O' in markers and 'o' in markers:
        return 100.0
    return 0.0


def calico(markers):
    return tortoiseshell(markers) * bicolor(markers) / 100.0


def colorpoint(markers):
    return 100.0 if markers.count('cs') >= 2 else 0.0


def smoke(markers):
    return dosage(markers, 'I') * solid(markers)


def shaded(markers):
    if markers.count('I') == 1 and 'A' in markers:
        return 100.0
    return 0.0


def chinchilla(markers):
    if markers.count('I') >= 2 and 'A' in markers:
        return 100.0
    return 0.0


def trait_routines():
    return {'solid': solid, 'tabby': tabby, 'bicolor': bicolor,
            'tortoiseshell': tortoiseshell, 'calico': calico,
            'colorpoint': colorpoint, 'smoke': smoke, 'shaded': shaded,
            'chinchilla': chinchilla}


def genetics(alleles):
    markers, traits = alleles
    markers = validate_markers(markers)
    routines = trait_routines()
    probabilities = []
    for trait in traits:
        if trait not in routines:
            raise ValueError('unsupported trait: ' + str(trait))
        probabilities.append(round(routines[trait](markers), 1))
    return probabilities


def format_report(markers, traits):
    probabilities = genetics([markers, traits])
    header = 'genotype ' + '/'.join(markers)
    rows = ['  {0:<14}{1:>6.1f}%'.format(t, p)
            for t, p in zip(traits, probabilities)]
    return '\n'.join([header] + rows)


def main():
    print(format_report(['a', 'a'], ['solid']))
    print(format_report(['A', 'a', 'S', 's'], ['tabby', 'solid', 'bicolor']))
    print(format_report(['a', 'a', 'O', 'o', 'S', 'S'],
                        ['tortoiseshell', 'calico', 'bicolor']))
    print(format_report(['cs', 'cs', 'a', 'a', 'I', 'i'],
                        ['colorpoint', 'smoke']))
    print(format_report(['A', 'A', 'I', 'I'], ['shaded', 'chinchilla']))


if __name__ == '__main__':
    main()

