def normalize_damage(damage):
    wind = float(damage.get("wind_speed", 0.0))
    if wind < 0:
        raise ValueError("estimated wind speed cannot be negative")
    system = str(damage.get("system", "EF")).upper()
    if system not in ("EF", "F"):
        raise ValueError("unknown damage scale system: %s" % system)
    indicators = frozenset(str(i).strip().lower() for i in damage.get("indicators", ()))
    return {"wind": wind, "indicators": indicators, "system": system}


def has_damage(damage, *indicators):
    return any(indicator in damage["indicators"] for indicator in indicators)


def ef_zero(damage):
    return damage["wind"] >= 65 or has_damage(
        damage, "shingles peeled", "branches broken", "gutters damaged")


def ef_one(damage):
    return damage["wind"] >= 86 or has_damage(
        damage, "roof severely stripped", "mobile home overturned", "windows broken")


def ef_two(damage):
    return damage["wind"] >= 111 or has_damage(
        damage, "roof torn off frame house", "mobile home destroyed", "large trees snapped")


def ef_three(damage):
    return damage["wind"] >= 136 or has_damage(
        damage, "entire stories destroyed", "trains overturned", "heavy cars lifted")


def ef_four(damage):
    return damage["wind"] >= 166 or has_damage(
        damage, "well-built house leveled", "structures blown some distance")


def ef_five(damage):
    return damage["wind"] >= 200 or has_damage(
        damage, "foundation swept clean", "strong frame house lifted", "steel structure deformed")


def f_zero(damage):
    return damage["wind"] >= 40 or has_damage(
        damage, "chimney damaged", "sign boards damaged", "shallow-rooted trees pushed over")


def f_one(damage):
    return damage["wind"] >= 73 or has_damage(
        damage, "surfaces peeled off roof", "mobile home pushed off foundation", "moving autos pushed off road")


def f_two(damage):
    return damage["wind"] >= 113 or has_damage(
        damage, "roofs torn off frame houses", "boxcars overturned", "light-object missiles generated")


def scale_routines(system):
    if system == "F":
        return [("F0", f_zero), ("F1", f_one), ("F2", f_two)]
    return [("EF0", ef_zero), ("EF1", ef_one), ("EF2", ef_two),
            ("EF3", ef_three), ("EF4", ef_four), ("EF5", ef_five)]


def rate(damage):
    parameters = normalize_damage(damage)
    matched = "Unrated"
    for name, routine in scale_routines(parameters["system"]):
        if routine(parameters):
            matched = name
    return matched


def format_report(damage):
    parameters = normalize_damage(damage)
    listed = ", ".join(sorted(parameters["indicators"])) or "no reported indicators"
    return "%3.0f mph / %s -> %s" % (parameters["wind"], listed, rate(damage))


def main():
    surveys = [
        {"wind_speed": 200, "indicators": ["foundation swept clean"]},
        {"wind_speed": 95, "indicators": ["mobile home overturned"]},
        {"wind_speed": 30, "indicators": ["branches broken"]},
        {"wind_speed": 20, "indicators": []},
        {"wind_speed": 120, "indicators": ["boxcars overturned"], "system": "F"},
        {"wind_speed": 55, "indicators": ["chimney damaged"], "system": "F"},
    ]
    for survey in surveys:
        print(format_report(survey))


if __name__ == "__main__":
    main()

