STRENGTH_FACTORS = {"mild": 1.0, "medium": 1.25, "strong": 1.5}
MIN_TEMPERATURE = 50.0
MAX_TEMPERATURE = 100.0

def normalize_name(name):
    return " ".join(name.strip().lower().replace("-", " ").replace("_", " ").split())

def strength_factor(strength):
    key = normalize_name(strength)
    if key not in STRENGTH_FACTORS:
        raise ValueError("unknown strength: %s" % strength)
    return STRENGTH_FACTORS[key]

def temperature_adjustment(temperature, ideal_temperature):
    factor = 1.0 + (ideal_temperature - temperature) * 0.02
    return min(2.0, max(0.5, factor))

def brew_seconds(base_seconds, ideal_temperature, temperature, strength):
    scaled = base_seconds * strength_factor(strength)
    return int(round(scaled * temperature_adjustment(temperature, ideal_temperature)))

def steep_white(temperature, strength):
    return brew_seconds(150, 75, temperature, strength)

def steep_green(temperature, strength):
    return brew_seconds(120, 80, temperature, strength)

def steep_yellow(temperature, strength):
    return brew_seconds(130, 80, temperature, strength)

def steep_oolong(temperature, strength):
    return brew_seconds(100, 90, temperature, strength)

def steep_black(temperature, strength):
    return brew_seconds(180, 95, temperature, strength)

def steep_pu_erh(temperature, strength):
    return brew_seconds(200, 100, temperature, strength)

def steep_herbal(temperature, strength):
    return brew_seconds(300, 100, temperature, strength)

def steep_rooibos(temperature, strength):
    return brew_seconds(330, 100, temperature, strength)

def steep_mate(temperature, strength):
    return brew_seconds(240, 80, temperature, strength)

def routine_for(name):
    routines = {
        "white": steep_white, "green": steep_green, "yellow": steep_yellow,
        "oolong": steep_oolong, "black": steep_black, "pu erh": steep_pu_erh,
        "herbal": steep_herbal, "rooibos": steep_rooibos, "mate": steep_mate,
    }
    return routines.get(normalize_name(name))

def validate_parameters(parameters):
    temperature = parameters.get("temperature")
    if not isinstance(temperature, (int, float)):
        raise TypeError("temperature must be a number in degrees celsius")
    if not MIN_TEMPERATURE <= temperature <= MAX_TEMPERATURE:
        raise ValueError("temperature %r outside brewing range" % temperature)
    teas = parameters.get("teas", [])
    if not teas:
        raise ValueError("at least one tea variety is required")
    unknown = [tea for tea in teas if routine_for(tea) is None]
    if unknown:
        raise ValueError("unsupported varieties: %s" % ", ".join(unknown))
    return temperature, teas, parameters.get("strength", "medium")

def steep(parameters):
    temperature, teas, strength = validate_parameters(parameters)
    return [routine_for(tea)(temperature, strength) for tea in teas]

def format_report(parameters, times):
    temperature, teas, strength = validate_parameters(parameters)
    header = "%g C, %s strength" % (temperature, normalize_name(strength))
    rows = ["  %-8s %4d s" % (normalize_name(tea), seconds)
            for tea, seconds in zip(teas, times)]
    return "\n".join([header] + rows)

def main():
    request = {"temperature": 80, "strength": "mild",
               "teas": ["green", "white", "pu erh", "rooibos"]}
    print(format_report(request, steep(request)))
    strong = dict(request, strength="strong", temperature=95)
    print(format_report(strong, steep(strong)))

if __name__ == "__main__":
    main()

