def validate_age(age):
    value = float(age)
    if value < 0.0:
        raise ValueError("age in millions of years cannot be negative")
    return value


def is_cambrian(age):
    return 485.4 < age <= 538.8


def is_ordovician(age):
    return 443.8 < age <= 485.4


def is_silurian(age):
    return 419.2 < age <= 443.8


def is_devonian(age):
    return 358.9 < age <= 419.2


def is_carboniferous(age):
    return 298.9 < age <= 358.9


def is_permian(age):
    return 251.9 < age <= 298.9


def is_triassic(age):
    return 201.4 < age <= 251.9


def is_jurassic(age):
    return 145.0 < age <= 201.4


def is_cretaceous(age):
    return 66.0 < age <= 145.0


BOUNDARY_TESTS = (
    ("Cambrian", is_cambrian),
    ("Ordovician", is_ordovician),
    ("Silurian", is_silurian),
    ("Devonian", is_devonian),
    ("Carboniferous", is_carboniferous),
    ("Permian", is_permian),
    ("Triassic", is_triassic),
    ("Jurassic", is_jurassic),
    ("Cretaceous", is_cretaceous),
)


def era(age):
    value = validate_age(age)
    for name, boundary_test in BOUNDARY_TESTS:
        if boundary_test(value):
            return name
    return None


def describe(age):
    period = era(age)
    if period is None:
        return "{0:.1f} Ma: outside the Cambrian-Cretaceous range".format(float(age))
    return "{0:.1f} Ma: {1}".format(float(age), period)


def main():
    samples = [150.0, 500.0, 66.5, 430.0, 300.0, 12.0, 250.0]
    for age in samples:
        print(describe(age))
    try:
        era(-5.0)
    except ValueError as error:
        print("rejected sample: {0}".format(error))


if __name__ == "__main__":
    main()

