TOOL_HARDNESS = {
    "fingernail": 2.5,
    "copper penny": 3.5,
    "glass": 5.5,
    "steel knife": 5.5,
    "hardened steel": 6.0,
    "steel file": 6.5,
    "quartz point": 7.0,
    "topaz point": 8.0,
    "corundum point": 9.0,
    "diamond point": 10.0,
}

MINERAL_NAMES = (
    "Talc", "Gypsum", "Calcite", "Fluorite", "Apatite",
    "Orthoclase", "Quartz", "Topaz", "Corundum", "Diamond",
)


def tool_hardness(material):
    try:
        return TOOL_HARDNESS[material.strip().lower()]
    except KeyError:
        raise ValueError("unknown tool material: %r" % (material,))


def required_force(mohs):
    return 1.0 + 0.5 * mohs


def parse_test(test):
    force = float(test["force"])
    if force < 0.0:
        raise ValueError("force must not be negative: %r" % (force,))
    return tool_hardness(test["tool"]), force


def leaves_mark(test, mohs):
    point, force = parse_test(test)
    return point > mohs and force >= required_force(mohs)


def scratches_talc(test):
    return leaves_mark(test, 1)


def scratches_gypsum(test):
    return leaves_mark(test, 2)


def scratches_calcite(test):
    return leaves_mark(test, 3)


def scratches_fluorite(test):
    return leaves_mark(test, 4)


def scratches_apatite(test):
    return leaves_mark(test, 5)


def scratches_orthoclase(test):
    return leaves_mark(test, 6)


def scratches_quartz(test):
    return leaves_mark(test, 7)


def scratches_topaz(test):
    return leaves_mark(test, 8)


def scratches_corundum(test):
    return leaves_mark(test, 9)


def scratches_diamond(test):
    return leaves_mark(test, 10)


ROUTINES = (
    (scratches_talc, 1), (scratches_gypsum, 2), (scratches_calcite, 3),
    (scratches_fluorite, 4), (scratches_apatite, 5), (scratches_orthoclase, 6),
    (scratches_quartz, 7), (scratches_topaz, 8), (scratches_corundum, 9),
    (scratches_diamond, 10),
)


def hardness(test):
    resisted = [mohs for routine, mohs in ROUTINES if not routine(test)]
    return min(resisted)


def mineral_name(mohs):
    return MINERAL_NAMES[mohs - 1]


def format_report(tests):
    lines = []
    for test in tests:
        mohs = hardness(test)
        lines.append("%-15s %5.1f N -> Mohs %2d (%s resists)"
                     % (test["tool"], float(test["force"]), mohs, mineral_name(mohs)))
    return "\n".join(lines)


def main():
    tests = [
        {"tool": "fingernail", "force": 0.8},
        {"tool": "fingernail", "force": 3.0},
        {"tool": "copper penny", "force": 4.0},
        {"tool": "hardened steel", "force": 6.0},
        {"tool": "steel file", "force": 6.0},
        {"tool": "diamond point", "force": 12.0},
    ]
    print(format_report(tests))


if __name__ == "__main__":
    main()

