def sporting(sixteen_week_weight):
    return round(sixteen_week_weight * 2.30, 1)


def hound(sixteen_week_weight):
    return round(sixteen_week_weight * 2.20, 1)


def working(sixteen_week_weight):
    return round(sixteen_week_weight * 2.60, 1)


def terrier(sixteen_week_weight):
    return round(sixteen_week_weight * 1.50, 1)


def toy(sixteen_week_weight):
    return round(sixteen_week_weight * 1.35, 1)


def non_sporting(sixteen_week_weight):
    return round(sixteen_week_weight * 2.00, 1)


def herding(sixteen_week_weight):
    return round(sixteen_week_weight * 2.10, 1)


def miscellaneous(sixteen_week_weight):
    return round(sixteen_week_weight * 2.05, 1)


def foundation_stock_service(sixteen_week_weight):
    return round(sixteen_week_weight * 2.40, 1)


def routines():
    return {
        "sporting": sporting,
        "hound": hound,
        "working": working,
        "terrier": terrier,
        "toy": toy,
        "non sporting": non_sporting,
        "herding": herding,
        "miscellaneous": miscellaneous,
        "foundation stock service": foundation_stock_service,
    }


def normalize_group(name):
    key = " ".join(str(name).replace("-", " ").replace("_", " ").lower().split())
    if key not in routines():
        raise ValueError("unknown breed group: {0}".format(name))
    return key


def validate_weight(weight):
    if not isinstance(weight, (int, float)) or isinstance(weight, bool):
        raise TypeError("puppy weight must be numeric")
    if weight <= 0:
        raise ValueError("puppy weight must be positive")
    return float(weight)


def estimate(puppy):
    weight = validate_weight(puppy["weight"])
    table = routines()
    return [table[normalize_group(group)](weight) for group in puppy["groups"]]


def format_report(puppy, projections):
