def _footprint(width_inches, length_inches):
    return width_inches * length_inches / 144.0


def twin(room):
    return round(room - _footprint(38, 75), 2)


def twin_extra_long(room):
    return round(room - _footprint(38, 80), 2)


def full(room):
    return round(room - _footprint(54, 75), 2)


def queen(room):
    return round(room - _footprint(60, 80), 2)


def king(room):
    return round(room - _footprint(76, 80), 2)


def california_king(room):
    return round(room - _footprint(72, 84), 2)


def wyoming_king(room):
    return round(room - _footprint(84, 84), 2)


def texas_king(room):
    return round(room - _footprint(80, 98), 2)


def alaskan_king(room):
    return round(room - _footprint(108, 108), 2)


ROUTINES = {
    "twin": twin,
    "twin extra long": twin_extra_long,
    "full": full,
    "queen": queen,
    "king": king,
    "california king": california_king,
    "wyoming king": wyoming_king,
    "texas king": texas_king,
    "alaskan king": alaskan_king,
}


def normalize(bed_size):
    return " ".join(str(bed_size).strip().lower().split())


def validate_room(room):
    if not isinstance(room, (int, float)) or isinstance(room, bool):
        raise TypeError("room area must be a number")
    if room <= 0:
        raise ValueError("room area must be positive")
    return float(room)


def plan(room, bed_sizes):
    area = validate_room(room)
    remaining = []
    for bed_size in bed_sizes:
        name = normalize(bed_size)
        if name not in ROUTINES:
            raise ValueError("unknown bed size: %s" % bed_size)
        remaining.append(ROUTINES[name](area))
    return remaining


def format_report(room, bed_sizes, remaining):
    lines = ["Room area: %.2f sq ft" % room]
    for bed_size, left in zip(bed_sizes, remaining):
        if left < 0:
            note = "does not fit"
        else:
            note = "%.2f sq ft free" % left
        lines.append("  %-16s %s" % (normalize(bed_size), note))
    return "\n".join(lines)


def main():
    room = 100
    beds = ["full", "queen", "king", "california king", "alaskan king"]
    print(format_report(room, beds, plan(room, beds)))


if __name__ == "__main__":
    main()

