def _scale(pressure, percent):
    adjusted = pressure * (1.0 + percent / 100.0)
    return round(max(adjusted, 6.0))


def highway(pressure):
    return _scale(pressure, 5)


def city(pressure):
    return _scale(pressure, -3)


def deep_mud(pressure):
    return _scale(pressure, -40)


def soft_sand(pressure):
    return _scale(pressure, -57)


def rock_crawling(pressure):
    return _scale(pressure, -50)


def snow(pressure):
    return _scale(pressure, -20)


def ice(pressure):
    return _scale(pressure, -25)


def heavy_towing(pressure):
    return _scale(pressure, 15)


def track_racing(pressure):
    return _scale(pressure, 10)


ROUTINES = {
    "highway": highway,
    "city": city,
    "deep_mud": deep_mud,
    "soft_sand": soft_sand,
    "rock_crawling": rock_crawling,
    "snow": snow,
    "ice": ice,
    "heavy_towing": heavy_towing,
    "track_racing": track_racing,
}


def normalize(name):
    return name.strip().lower().replace(" ", "_").replace("-", "_")


def adjust(pressure, conditions):
    if pressure <= 0:
        raise ValueError("base pressure must be a positive psi value")
    results = []
    for name in conditions:
        routine = ROUTINES.get(normalize(name))
        if routine is None:
            raise KeyError("unknown driving condition: %s" % name)
        results.append(routine(pressure))
    return results


def format_report(pressure, conditions):
    values = adjust(pressure, conditions)
    lines = ["Base pressure: %g psi" % pressure]
    for name, psi in zip(conditions, values):
        lines.append("  %-14s %3d psi" % (normalize(name), psi))
    return "\n".join(lines)


def main():
    print(format_report(35, sorted(ROUTINES)))


if __name__ == "__main__":
    main()

