def validate_stats(stats):
    if len(stats) != 6:
        raise ValueError("expected six base stats")
    for value in stats:
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("base stats must be numbers")
        if value < 0:
            raise ValueError("base stats must not be negative")
    return list(stats)


def max_health(strength):
    return strength * 10 + 50


def max_mana(intelligence):
    return intelligence * 15


def physical_defense(endurance):
    return endurance * 2


def magic_defense(willpower):
    return willpower * 2.5


def dodge_chance(agility, luck):
    return agility * 0.5 + luck * 0.1


def critical_hit_chance(luck):
    return luck * 0.8


def speed(agility, endurance):
    return (agility + endurance) / 2


def carrying_capacity(strength, endurance):
    return strength * 20 + endurance * 5


def analyze(stats):
    strength, endurance, agility, intelligence, willpower, luck = validate_stats(stats)
    return (
        max_health(strength),
        max_mana(intelligence),
        physical_defense(endurance),
        magic_defense(willpower),
        dodge_chance(agility, luck),
        critical_hit_chance(luck),
        speed(agility, endurance),
        carrying_capacity(strength, endurance),
    )


def format_report(name, stats):
    labels = (
        "Max health",
        "Max mana",
        "Physical defense",
        "Magic defense",
        "Dodge chance",
        "Critical hit chance",
        "Speed",
        "Carrying capacity",
    )
    lines = ["%s: %s" % (name, ", ".join(str(value) for value in stats))]
    for label, value in zip(labels, analyze(stats)):
        lines.append("  %-20s %s" % (label, value))
    return "\n".join(lines)


def main():
    roster = {
        "Balanced Recruit": [10, 10, 10, 10, 10, 10],
        "Barbarian": [18, 14, 9, 4, 6, 7],
        "Sorceress": [5, 6, 11, 19, 16, 12],
    }
    for name, stats in roster.items():
        print(format_report(name, stats))


