VOWELS = "aeiou"
SENTENCE_ENDINGS = ".!?"
METRIC_LABELS = (
    "word count",
    "sentence count",
    "syllable estimate",
    "character count",
    "average word length",
    "average sentence length",
    "vowel density",
    "reading time (minutes)",
)


def word_count(text):
    return len(text.split())


def sentence_count(text):
    return sum(1 for char in text if char in SENTENCE_ENDINGS)


def syllable_estimate(text):
    return sum(1 for char in text.lower() if char in VOWELS)


def character_count(text):
    return sum(1 for char in text if not char.isspace())


def safe_divide(numerator, denominator):
    if denominator == 0:
        return 0.0
    return numerator / denominator


def average_word_length(text):
    return safe_divide(character_count(text), word_count(text))


def average_sentence_length(text):
    return safe_divide(word_count(text), sentence_count(text))


def vowel_density(text):
    return safe_divide(syllable_estimate(text), character_count(text))


def reading_time(text):
    return word_count(text) / 200


def readability(text):
    return [
        word_count(text),
        sentence_count(text),
        syllable_estimate(text),
        character_count(text),
        average_word_length(text),
        average_sentence_length(text),
        vowel_density(text),
        reading_time(text),
    ]


def format_report(text):
    metrics = readability(text)
    width = max(len(label) for label in METRIC_LABELS)
    lines = []
    for label, value in zip(METRIC_LABELS, metrics):
        lines.append("{0:<{1}} : {2}".format(label, width, round(value, 4)))
    return "\n".join(lines)


def main():
    paragraph = (
        "Readability is a rough idea, not a science. "
        "Can a handful of counts describe a paragraph? "
        "They can hint at it!"
    )
    print(format_report(paragraph))


if __name__ == "__main__":
    main()

