def photosynthesis_rate(light_intensity, co2_level):
    return light_intensity * co2_level * 0.5


def transpiration_rate(temperature, humidity):
    return temperature * 0.8 - humidity * 0.2


def root_growth_rate(soil_moisture):
    return soil_moisture * 0.3


def leaf_expansion_rate(photosynthesis, transpiration):
    return photosynthesis - transpiration


def nutrient_uptake_rate(soil_fertility, root_growth):
    return soil_fertility * root_growth


def water_stress_level(transpiration, soil_moisture):
    if soil_moisture <= 0:
        raise ValueError("soil_moisture must be positive to compute water stress")
    return transpiration / soil_moisture


def sunlight_stress(light_intensity):
    if light_intensity < 100:
        return 0
