def passenger_weight(passengers):
    return passengers * 85


def cargo_weight(bags):
    return bags * 20


def zero_fuel_weight(empty_weight, passengers, bags):
    return empty_weight + passenger_weight(passengers) + cargo_weight(bags)


def required_fuel(duration_hours, burn_rate, reserve_fuel):
    return duration_hours * burn_rate + reserve_fuel


def takeoff_weight(zfw, fuel):
    return zfw + fuel


def takeoff_distance(tow):
    return tow * 0.02


def cruise_speed(thrust, drag, weight_factor):
    return (thrust - drag) / weight_factor


def descent_time(cruise_altitude, descent_rate):
    return cruise_altitude / descent_rate


def aviation(parameters):
    (passengers, bags, empty_weight, duration_hours, burn_rate,
     reserve_fuel, thrust, drag, weight_factor,
     cruise_altitude, descent_rate) = parameters
    pax = passenger_weight(passengers)
    cargo = cargo_weight(bags)
    zfw = zero_fuel_weight(empty_weight, passengers, bags)
    fuel = required_fuel(duration_hours, burn_rate, reserve_fuel)
    tow = takeoff_weight(zfw, fuel)
    distance = takeoff_distance(tow)
    speed = cruise_speed(thrust, drag, weight_factor)
    descent = descent_time(cruise_altitude, descent_rate)
    return (pax, cargo, zfw, fuel, tow, distance, speed, descent)


def validate(parameters):
    if len(parameters) != 11:
        raise ValueError("expected 11 flight variables, got %d" % len(parameters))
    for value in parameters:
        if not isinstance(value, (int, float)):
            raise TypeError("flight variables must be numeric: %r" % (value,))
    if parameters[8] == 0:
        raise ValueError("weight factor must not be zero")
    if parameters[10] == 0:
        raise ValueError("descent rate must not be zero")
    return list(parameters)


def format_report(results):
    labels = ("Passenger weight (kg)", "Cargo weight (kg)",
              "Zero fuel weight (kg)", "Required fuel (kg)",
              "Takeoff weight (kg)", "Takeoff distance (m)",
              "Cruise speed (m/s)", "Descent time (min)")
    lines = []
    for label, value in zip(labels, results):
        lines.append("{:<24}{:>12.2f}".format(label, value))
    return "\n".join(lines)


def main():
    flight = validate([180, 220, 42000, 4.5, 2400, 3000,
                       220000, 48000, 1600, 11000, 350])
    print(format_report(aviation(flight)))


if __name__ == "__main__":
    main()

