def validate_flour(flour):
    if not isinstance(flour, (int, float)) or isinstance(flour, bool):
        raise TypeError("flour weight must be a number")
    if flour <= 0:
        raise ValueError("flour weight must be positive")
    return float(flour)


def water_weight(flour):
    return flour * 0.70


def salt_weight(flour):
    return flour * 0.02


def fresh_yeast_weight(flour):
    return flour * 0.03


def active_dry_yeast_weight(flour):
    return flour * 0.01


def sugar_weight(flour):
    return flour * 0.05


def butter_weight(flour):
    return flour * 0.10


def milk_powder_weight(flour):
    return flour * 0.04


def sourdough_starter_weight(flour):
    return flour * 0.20


def bake(flour):
    grams = validate_flour(flour)
    return (
        water_weight(grams),
        salt_weight(grams),
        fresh_yeast_weight(grams),
        active_dry_yeast_weight(grams),
        sugar_weight(grams),
        butter_weight(grams),
        milk_powder_weight(grams),
        sourdough_starter_weight(grams),
    )


def ingredient_names():
    return (
        "water",
        "salt",
        "fresh yeast",
        "active dry yeast",
        "sugar",
        "butter",
        "milk powder",
        "sourdough starter",
    )


def format_recipe(flour):
    weights = bake(flour)
    lines = ["flour: {:.1f} g".format(validate_flour(flour))]
    for name, weight in zip(ingredient_names(), weights):
        lines.append("{}: {:.1f} g".format(name, weight))
    return "\n".join(lines)


def total_dough_weight(flour):
    return validate_flour(flour) + sum(bake(flour))


def main():
    for flour in (1000, 500, 250.5):
        print(format_recipe(flour))
        print("total dough: {:.1f} g".format(total_dough_weight(flour)))
        print()
    print(bake(1000))


if __name__ == "__main__":
    main()

