def validate(data):
    if len(data) < 16:
        raise ValueError("packet header must contain at least 16 hex characters")
    invalid = [c for c in data[:16] if c not in "0123456789abcdefABCDEF"]
    if invalid:
        raise ValueError("invalid hex characters: " + "".join(invalid))
    return data[:16]


def version(data):
    return int(data[0], 16)


def header_length(data):
    return int(data[1], 16) * 4


def type_of_service(data):
    return int(data[2:4], 16)


def total_length(data):
    return int(data[4:8], 16)


def identification(data):
    return int(data[8:12], 16)


def time_to_live(data):
    return int(data[12:14], 16)


def protocol(data):
    return int(data[14:16], 16)


def payload_size(data):
    return total_length(data) - header_length(data)


def packet(data):
    header = validate(data)
    return [
        version(header),
        header_length(header),
        type_of_service(header),
        total_length(header),
        identification(header),
        time_to_live(header),
        protocol(header),
        payload_size(header),
    ]


def report(data):
    labels = ("version", "header length", "type of service", "total length",
              "identification", "time to live", "protocol", "payload size")
    lines = ["header: " + data]
    for label, value in zip(labels, packet(data)):
        lines.append("  {:<16}{}".format(label + ":", value))
    return "\n".join(lines)


def main():
    for sample in ("4500003ca1b40000400600", "45c0011122220000ff01abcd", "4500003c"):
        try:
            print(report(sample))
        except ValueError as error:
            print("skipping {!r}: {}".format(sample, error))


if __name__ == "__main__":
    main()

