def parse_portfolio(portfolio):
    if len(portfolio) != 15:
        raise ValueError("portfolio must contain exactly 15 numbers")
    values = [float(number) for number in portfolio]
    if values[2] == 0 or values[10] == 0 or values[14] == 0:
        raise ValueError("initial investment, market cap and leverage must be non-zero")
    return {
        "coin_amount": values[0],
        "current_price": values[1],
        "initial_investment": values[2],
        "weekly_prices": values[3:10],
        "total_market_cap": values[10],
        "order_size": values[11],
        "entry_price": values[12],
        "collateral": values[13],
        "leverage": values[14],
    }


def total_value(coin_amount, current_price):
    return coin_amount * current_price


def profit_or_loss(value, initial_investment):
    return value - initial_investment


def return_on_investment(profit, initial_investment):
    return profit / initial_investment


def moving_average(weekly_prices):
    return sum(weekly_prices[-7:]) / 7


def volatility(weekly_prices):
    return max(weekly_prices) - min(weekly_prices)


def market_dominance(value, total_market_cap):
    return value / total_market_cap


def slippage_estimate(order_size):
    return order_size * 0.0001


def liquidation_price(entry_price, collateral, leverage):
    return entry_price - collateral / leverage


def crypto(portfolio):
    data = parse_portfolio(portfolio)
    value = total_value(data["coin_amount"], data["current_price"])
    profit = profit_or_loss(value, data["initial_investment"])
    return [
        value,
        profit,
        return_on_investment(profit, data["initial_investment"]),
        moving_average(data["weekly_prices"]),
        volatility(data["weekly_prices"]),
        market_dominance(value, data["total_market_cap"]),
        slippage_estimate(data["order_size"]),
        liquidation_price(data["entry_price"], data["collateral"], data["leverage"]),
    ]


def format_report(metrics):
    labels = [
        "Total value", "Profit/loss", "Return on investment", "Moving average",
        "Volatility", "Market dominance", "Slippage estimate", "Liquidation price",
    ]
    return "\n".join(
        "{:<22}{:>18.6f}".format(label, metric)
        for label, metric in zip(labels, metrics)
    )


def main():
    portfolio = [
        2.5, 42000.0, 80000.0,
        40100.0, 40950.0, 41500.0, 40800.0, 42300.0, 41750.0, 42000.0,
        850000000000.0, 25000.0, 41000.0, 9000.0, 5.0,
    ]
    print(format_report(crypto(portfolio)))


if __name__ == "__main__":
    main()

