def solar_production(data):
    return data["panel_area"] * data["sunlight_intensity"] * data["panel_efficiency"]


def wind_production(data):
    return data["turbine_count"] * data["wind_speed"] ** 2 * 0.5


def local_production(data):
    return solar_production(data) + wind_production(data)


def grid_import(data):
    deficit = data["target_demand"] - local_production(data)
    return deficit if deficit > 0 else 0.0


def battery_charge(data):
    surplus = local_production(data) - data["target_demand"]
    return surplus if surplus > 0 else 0.0


def grid_export(data):
    spare = battery_charge(data) - data["battery_capacity"]
    return spare if spare > 0 else 0.0


def total_consumption(data):
    return data["target_demand"] + battery_charge(data)


def transmission_loss(data):
    return total_consumption(data) * 0.03


def net_carbon_offset(data):
    return local_production(data) - grid_import(data) * 0.4


def validate(data):
    required = (
        "panel_area",
        "sunlight_intensity",
        "panel_efficiency",
        "turbine_count",
        "wind_speed",
        "target_demand",
        "battery_capacity",
    )
    for key in required:
        if key not in data:
            raise KeyError("missing environmental input: " + key)
        if data[key] < 0:
            raise ValueError("negative environmental input: " + key)
    return data


def grid(data):
    validate(data)
    return (
        solar_production(data),
        wind_production(data),
        grid_import(data),
        battery_charge(data),
        grid_export(data),
        total_consumption(data),
        transmission_loss(data),
        net_carbon_offset(data),
    )


def format_report(metrics):
    labels = (
        "solar production",
        "wind production",
        "grid import",
        "battery charge",
        "grid export",
        "total consumption",
        "transmission loss",
        "net carbon offset",
    )
    return "\n".join(
        "{:<18}: {:>10.2f} kWh".format(label, value)
        for label, value in zip(labels, metrics)
    )


def main():
    sites = [
        {
            "panel_area": 120.0,
            "sunlight_intensity": 0.85,
            "panel_efficiency": 0.19,
            "turbine_count": 3,
            "wind_speed": 7.5,
            "target_demand": 90.0,
            "battery_capacity": 30.0,
        },
        {
            "panel_area": 40.0,
            "sunlight_intensity": 0.4,
            "panel_efficiency": 0.16,
            "turbine_count": 1,
            "wind_speed": 3.0,
            "target_demand": 150.0,
            "battery_capacity": 20.0,
