def temperature_stress(water_temperature, baseline_threshold):
    return water_temperature - baseline_threshold


def acidity_stress(baseline_ph, current_ph):
    return (baseline_ph - current_ph) * 10


def pollution_level(nitrate, phosphate):
    return nitrate + phosphate


def sedimentation_rate(turbidity):
    return turbidity - 5


def sunlight_exposure(daylight_hours, intensity_threshold):
    return daylight_hours - intensity_threshold


def symbiodinium_loss(temp_stress, acid_stress):
    return temp_stress * acid_stress


def calcification_rate(acid_stress):
    return 1 / acid_stress


def bleaching_risk(factors, calcification):
    return sum(factors) / calcification


def validate(metrics):
    if len(metrics) != 9:
        raise ValueError("expected 9 environmental readings, got %d" % len(metrics))
    for reading in metrics:
        if not isinstance(reading, (int, float)):
            raise TypeError("readings must be numeric, got %r" % (reading,))
    if metrics[2] == metrics[3]:
        raise ValueError("ph drop of zero leaves calcification rate undefined")


def coral(metrics):
    validate(metrics)
    water_temp, baseline_temp, baseline_ph, current_ph = metrics[0:4]
    nitrate, phosphate, turbidity, daylight, intensity = metrics[4:9]
    temp = temperature_stress(water_temp, baseline_temp)
    acid = acidity_stress(baseline_ph, current_ph)
    pollution = pollution_level(nitrate, phosphate)
    sediment = sedimentation_rate(turbidity)
    sunlight = sunlight_exposure(daylight, intensity)
    loss = symbiodinium_loss(temp, acid)
    calcification = calcification_rate(acid)
    risk = bleaching_risk([temp, acid, pollution, sediment, sunlight, loss], calcification)
    return (temp, acid, pollution, sediment, sunlight, loss, calcification, risk)


def report(name, indicators):
    labels = ("temperature stress", "acidity stress", "pollution level",
              "sedimentation rate", "sunlight exposure", "symbiodinium loss",
              "calcification rate", "bleaching risk")
    lines = ["Reef: %s" % name]
    for label, value in zip(labels, indicators):
        lines.append("  %-20s %10.3f" % (label, value))
    return "\n".join(lines)


def main():
    sites = {
        "Heron Island": [30.2, 28.0, 8.2, 8.05, 0.4, 0.15, 7.5, 11.0, 6.0],
        "Lizard Island": [29.1, 28.5, 8.2, 8.18, 0.2, 0.05, 4.2, 10.5, 6.5],
    }
    for name, metrics in sites.items():
        print(report(name, coral(metrics)))


if __name__ == "__main__":
    main()

