def validate_profile(profile):
    if len(profile) != 7:
        raise ValueError("profile must contain 7 physical inputs")
    for value in profile:
        if not isinstance(value, (int, float)):
            raise TypeError("profile values must be numeric")
    if profile[0] <= 0:
        raise ValueError("age must be positive")
    return tuple(float(value) for value in profile)


def max_heart_rate(age):
    return 220 - age


def aerobic_zone(mhr):
    return mhr * 0.7


def anaerobic_zone(mhr):
    return mhr * 0.85


def daily_calorie_burn(resting_metabolic_rate, activity_multiplier):
    return resting_metabolic_rate * activity_multiplier


def protein_requirement(weight_kg):
    return weight_kg * 1.6


def water_requirement(weight_kg, sweat_loss):
    return weight_kg * 0.03 + sweat_loss


def recovery_time(workout_duration, fatigue_level):
    return workout_duration * 0.2 + fatigue_level


def sleep_requirement(recovery_hours):
    return 8 + recovery_hours / 5


def training(profile):
    age, rmr, multiplier, weight, sweat, duration, fatigue = validate_profile(profile)
    mhr = max_heart_rate(age)
    recovery = recovery_time(duration, fatigue)
    return (
        mhr,
        aerobic_zone(mhr),
        anaerobic_zone(mhr),
        daily_calorie_burn(rmr, multiplier),
        protein_requirement(weight),
        water_requirement(weight, sweat),
        recovery,
        sleep_requirement(recovery),
    )


def format_report(targets):
    labels = (
        ("Max heart rate", "bpm"),
        ("Aerobic zone", "bpm"),
        ("Anaerobic zone", "bpm"),
        ("Daily calorie burn", "kcal"),
        ("Protein requirement", "g"),
        ("Water requirement", "L"),
        ("Recovery time", "h"),
        ("Sleep requirement", "h"),
    )
    lines = []
    for (label, unit), value in zip(labels, targets):
        lines.append("{:<20}{:>9.2f} {}".format(label, value, unit))
    return "\n".join(lines)


def main():
    athlete = [32, 1650, 1.55, 74.5, 1.2, 90, 3]
    print(format_report(training(athlete)))


if __name__ == "__main__":
    main()

