SENSOR_FIELDS = (
    "wheel_speed", "ground_speed", "current_rpm", "max_rpm",
    "braking_force", "duration", "friction_coefficient",
    "cornering_force", "distance", "velocity", "drag_coefficient",
    "throttle_position", "turning_radius", "track_bumpiness",
    "spring_stiffness",
)

METRIC_NAMES = (
    "wheel slip ratio", "engine load", "brake temperature increase",
    "tire wear", "aerodynamic downforce", "fuel consumption rate",
    "lateral acceleration", "suspension travel",
)


def read_sensors(sensors):
    if len(sensors) != len(SENSOR_FIELDS):
        raise ValueError("expected %d sensor readings" % len(SENSOR_FIELDS))
    readings = dict(zip(SENSOR_FIELDS, (float(value) for value in sensors)))
    for field in ("ground_speed", "max_rpm", "turning_radius"):
        if readings[field] == 0.0:
            raise ValueError("%s must be non-zero" % field)
    return readings


def wheel_slip_ratio(wheel_speed, ground_speed):
    return (wheel_speed - ground_speed) / ground_speed


def engine_load(current_rpm, max_rpm):
    return current_rpm / max_rpm


def brake_temperature_increase(braking_force, duration, friction_coefficient):
    return braking_force * duration * friction_coefficient


def tire_wear(cornering_force, slip_ratio, distance):
    return cornering_force + slip_ratio * distance


def aerodynamic_downforce(velocity, drag_coefficient):
    return velocity ** 2 * drag_coefficient * 0.5


def fuel_consumption_rate(load, throttle_position):
    return load * throttle_position


def lateral_acceleration(velocity, turning_radius):
    return velocity ** 2 / turning_radius


def suspension_travel(track_bumpiness, spring_stiffness):
    return track_bumpiness * spring_stiffness


def telemetry(sensors):
    r = read_sensors(sensors)
    slip = wheel_slip_ratio(r["wheel_speed"], r["ground_speed"])
    load = engine_load(r["current_rpm"], r["max_rpm"])
    return [
        slip,
        load,
        brake_temperature_increase(r["braking_force"], r["duration"], r["friction_coefficient"]),
        tire_wear(r["cornering_force"], slip, r["distance"]),
        aerodynamic_downforce(r["velocity"], r["drag_coefficient"]),
        fuel_consumption_rate(load, r["throttle_position"]),
        lateral_acceleration(r["velocity"], r["turning_radius"]),
        suspension_travel(r["track_bumpiness"], r["spring_stiffness"]),
    ]


def format_report(metrics):
    width = max(len(name) for name in METRIC_NAMES)
    lines = []
    for name, value in zip(METRIC_NAMES, metrics):
        lines.append("%-*s : %10.4f" % (width, name, value))
    return "\n".join(lines)


def main():
    lap_sensors = [
        62.5, 60.0, 11200.0, 15000.0, 850.0, 1.8, 0.42,
        2.6, 4.3, 58.0, 1.15, 0.78, 95.0, 0.035, 2400.0,
    ]
    print(format_report(telemetry(lap_sensors)))


if __name__ == "__main__":
    main()

