def safe_ratio(numerator, denominator):
    if denominator == 0:
        return 0.0
    return numerator / denominator


def purchase_frequency(total_orders, account_age_months):
    return safe_ratio(total_orders, account_age_months)


def average_order_value(total_spent, total_orders):
    return safe_ratio(total_spent, total_orders)


def customer_lifetime_value(frequency, order_value, expected_lifespan):
    return frequency * order_value * expected_lifespan


def cart_abandonment_rate(abandoned_carts, total_carts):
    return safe_ratio(abandoned_carts, total_carts)


def return_rate(returned_items, total_items):
    return safe_ratio(returned_items, total_items)


def discount_usage(discounted_items, total_items):
    return safe_ratio(discounted_items, total_items)


def review_ratio(reviews_written, total_orders):
    return safe_ratio(reviews_written, total_orders)


def engagement_score(login_frequency, reviews_per_order, returns_per_item):
    return login_frequency + reviews_per_order - returns_per_item


def validate(data):
    if len(data) != 11:
        raise ValueError("expected 11 raw totals, got %d" % len(data))
    for index, value in enumerate(data):
        if not isinstance(value, (int, float)) or value < 0:
            raise ValueError("value at position %d must be non-negative" % index)
    return [float(value) for value in data]


def customer(data):
    (orders, age_months, spent, lifespan, abandoned, carts,
     returned, items, discounted, reviews, logins) = validate(data)
    frequency = purchase_frequency(orders, age_months)
    order_value = average_order_value(spent, orders)
    lifetime_value = customer_lifetime_value(frequency, order_value, lifespan)
    abandonment = cart_abandonment_rate(abandoned, carts)
    returns = return_rate(returned, items)
    discounts = discount_usage(discounted, items)
    reviews_per_order = review_ratio(reviews, orders)
    score = engagement_score(logins, reviews_per_order, returns)
    return (frequency, order_value, lifetime_value, abandonment,
            returns, discounts, reviews_per_order, score)


def format_report(name, metrics):
    labels = ("purchase frequency", "average order value", "lifetime value",
              "cart abandonment rate", "return rate", "discount usage",
              "review ratio", "engagement score")
