def vibration_severity(amplitude, frequency):
    return amplitude * frequency


def temperature_anomaly(current_temp, normal_temp):
    return current_temp - normal_temp


def lubrication_degradation(operating_hours, friction_coefficient):
    return operating_hours * friction_coefficient


def motor_current_draw(baseline_current, load_factor):
    return baseline_current + load_factor


def belt_tension_loss(initial_tension, current_tension):
    return initial_tension - current_tension


def bearing_wear(severity, anomaly, age):
    return severity + anomaly * age


def output_efficiency(actual_production, expected_production):
    if expected_production == 0:
        raise ValueError("expected production must not be zero")
    return actual_production / expected_production


def maintenance_priority(wear, degradation, efficiency):
    if efficiency == 0:
        raise ValueError("output efficiency must not be zero")
    return (wear + degradation) / efficiency


def parse_sensors(sensors):
    readings = list(sensors)
    if len(readings) != 13:
        raise ValueError("expected 13 sensor readings, got %d" % len(readings))
    for index, value in enumerate(readings):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("sensor %d is not numeric: %r" % (index, value))
    return readings


def machinery(sensors):
    (amplitude, frequency, current_temp, normal_temp, operating_hours,
     friction_coefficient, baseline_current, load_factor, initial_tension,
     current_tension, age, actual_production,
     expected_production) = parse_sensors(sensors)
    severity = vibration_severity(amplitude, frequency)
    anomaly = temperature_anomaly(current_temp, normal_temp)
    degradation = lubrication_degradation(operating_hours, friction_coefficient)
    draw = motor_current_draw(baseline_current, load_factor)
    tension_loss = belt_tension_loss(initial_tension, current_tension)
    wear = bearing_wear(severity, anomaly, age)
    efficiency = output_efficiency(actual_production, expected_production)
    priority = maintenance_priority(wear, degradation, efficiency)
    return [severity, anomaly, degradation, draw, tension_loss, wear,
            efficiency, priority]


