import math


def surface_gravity(mass, radius):
    return mass / radius ** 2


def escape_velocity(gravity, radius):
    return math.sqrt(2 * gravity * radius)


def atmospheric_pressure(base_pressure, temperature, volume):
    return base_pressure * temperature / volume


def habitable_zone_distance(star_luminosity, distance):
    return star_luminosity / distance ** 2


def radiation_exposure(flare_rate, magnetic_field):
    return flare_rate / magnetic_field


def temperature_stability(max_temp, min_temp):
    return max_temp - min_temp


def water_availability(ice_mass, liquid_mass):
    return ice_mass + liquid_mass


def colonization_score(water, stability, radiation):
    return water + stability / radiation


def validate(data):
    required = ("mass", "radius", "base_pressure", "temperature", "volume",
                "star_luminosity", "distance", "flare_rate", "magnetic_field",
                "max_temp", "min_temp", "ice_mass", "liquid_mass")
    missing = [key for key in required if key not in data]
    if missing:
        raise KeyError("missing inputs: " + ", ".join(missing))
    for key in ("radius", "volume", "distance", "magnetic_field"):
        if data[key] == 0:
            raise ValueError("input '%s' must be non-zero" % key)
    return data


def exoplanet(data):
    values = validate(data)
    gravity = surface_gravity(values["mass"], values["radius"])
    velocity = escape_velocity(gravity, values["radius"])
    pressure = atmospheric_pressure(values["base_pressure"],
                                    values["temperature"], values["volume"])
    zone = habitable_zone_distance(values["star_luminosity"], values["distance"])
    radiation = radiation_exposure(values["flare_rate"], values["magnetic_field"])
    stability = temperature_stability(values["max_temp"], values["min_temp"])
    water = water_availability(values["ice_mass"], values["liquid_mass"])
    score = colonization_score(water, stability, radiation)
    return (gravity, velocity, pressure, zone, radiation, stability, water, score)


def report(name, metrics):
    labels = ("surface gravity", "escape velocity", "atmospheric pressure",
              "habitable zone distance", "radiation exposure",
              "temperature stability", "water availability",
              "colonization score")
