def validate_census(census):
    required = (
        "mature_females", "average_litter_size", "natural_mortality",
        "predation", "disease", "immigrants", "emigrants",
        "current_population", "habitat_size", "breeding_pairs",
    )
    missing = [field for field in required if field not in census]
    if missing:
        raise KeyError("missing census fields: " + ", ".join(missing))
    if census["habitat_size"] <= 0:
        raise ValueError("habitat size must be positive")
    if census["current_population"] <= 0:
        raise ValueError("current population must be positive")
    return {field: float(census[field]) for field in required}


def birth_rate(census):
    return census["mature_females"] * census["average_litter_size"]


def death_rate(census):
    return census["natural_mortality"] + census["predation"] + census["disease"]


def net_migration(census):
    return census["immigrants"] - census["emigrants"]


def population_growth(census):
    return birth_rate(census) - death_rate(census) + net_migration(census)


def carrying_capacity_usage(census):
    return census["current_population"] / census["habitat_size"]


def resource_competition(census):
    return population_growth(census) * carrying_capacity_usage(census)


def genetic_diversity_index(census):
    return census["breeding_pairs"] / census["current_population"]


def extinction_risk(census):
    births = birth_rate(census)
    if births == 0:
        return float("inf")
    return death_rate(census) / births * resource_competition(census)


def wildlife(census):
    data = validate_census(census)
    return [
        birth_rate(data),
        death_rate(data),
        net_migration(data),
        population_growth(data),
        carrying_capacity_usage(data),
        resource_competition(data),
        genetic_diversity_index(data),
        extinction_risk(data),
    ]


def format_report(metrics):
    labels = (
        "birth rate", "death rate", "net migration", "population growth",
        "carrying capacity usage", "resource competition",
        "genetic diversity index", "extinction risk",
    )
    return "\n".join(
        "{:<26}{:>12.4f}".format(label, value)
        for label, value in zip(labels, metrics)
    )


def main():
    census = {
        "mature_females": 120,
        "average_litter_size": 2.4,
        "natural_mortality": 90,
        "predation": 35,
        "disease": 18,
        "immigrants": 22,
        "emigrants": 9,
        "current_population": 640,
        "habitat_size": 1500,
        "breeding_pairs": 85,
    }
    print(format_report(wildlife(census)))


if __name__ == "__main__":
    main()

