def major(base):
    return base + 3


def minor(base):
    return base + 4


def seventh(base):
    return base + 5


def augmented(base):
    return (base + 4) * 2


def diminished(base):
    return (base + 3) / 2


def suspended_second(base):
    return base + 5 - 1


def suspended_fourth(base):
    return base + 6


def major_seventh(base):
    return base + 4 + base


def minor_seventh(base):
    return base + 5 - 2


def power_chord(base):
    return (base + 2) * 3


def validate_base(base):
    if not isinstance(base, int) or isinstance(base, bool):
        raise TypeError("base fret must be an integer")
    if base < 0 or base > 24:
        raise ValueError("base fret must be between 0 and 24")
    return base


def spans(base):
    fret = validate_base(base)
    return [
        major(fret),
        minor(fret),
        seventh(fret),
        augmented(fret),
        diminished(fret),
        suspended_second(fret),
        suspended_fourth(fret),
        major_seventh(fret),
        minor_seventh(fret),
        power_chord(fret),
    ]


CHORD_NAMES = [
    "major", "minor", "seventh", "augmented", "diminished",
    "suspended second", "suspended fourth", "major seventh",
    "minor seventh", "power chord",
]


def format_report(base):
    lines = ["Maximum fret spans from base fret %d:" % base]
    for name, span in zip(CHORD_NAMES, spans(base)):
        lines.append("  %-18s %6s" % (name, span))
    return "\n".join(lines)


def widest_chord(base):
    pairs = zip(CHORD_NAMES, spans(base))
    return max(pairs, key=lambda pair: pair[1])


def main():
    for base in (0, 4, 7):
        print(format_report(base))
        name, span = widest_chord(base)
        print("  widest: %s (%s)\n" % (name, span))


if __name__ == "__main__":
    main()

