def validate_crease(crease):
    if not isinstance(crease, (int, float)) or isinstance(crease, bool):
        raise TypeError("crease angle must be a number")
    if crease < 0:
        raise ValueError("crease angle cannot be negative")
    return float(crease)


def normalize(value):
    if float(value).is_integer():
        return int(value)
    return value


def valley_fold(crease):
    return crease / 2


def mountain_fold(crease):
    return crease / 2 + 10


def petal_fold(crease):
    return crease / 3


def squash_fold(crease):
    return crease / 4 + 5


def reverse_fold(crease):
    return (crease - 15) / 2


def rabbit_ear_fold(crease):
    return crease / 3 + 12


