    return round(check_tension(tension) * 3.1, 3)


def knit_two_together(tension):
    return round(check_tension(tension) * 4.0, 3)


def purl_two_together(tension):
    return round(check_tension(tension) * 4.2, 3)


def make_one(tension):
    return round(check_tension(tension) * 2.8, 3)


def pass_slipped_stitch_over(tension):
    return round(check_tension(tension) * 3.5, 3)


def cable_front(tension):
    return round(check_tension(tension) * 5.5, 3)


def cable_back(tension):
    return round(check_tension(tension) * 5.4, 3)


