def validate_line(line):
    if not isinstance(line, (int, float)) or isinstance(line, bool):
        raise TypeError("line strength must be a number")
    if line <= 0:
        raise ValueError("line strength must be positive")
    return float(line)


def retain(line, percent):
    return round(validate_line(line) * percent / 100.0, 2)


def bowline(line):
    return retain(line, 60)


def clove_hitch(line):
    return retain(line, 65)


def square_knot(line):
    return retain(line, 45)


def figure_eight(line):
    return retain(line, 80)


def sheet_bend(line):
    return retain(line, 55)


def timber_hitch(line):
    return retain(line, 70)


def taut_line_hitch(line):
    return retain(line, 50)


def round_turn(line):
    return retain(line, 75)


def fisherman_knot(line):
    return retain(line, 68)


def carrick_bend(line):
    return retain(line, 85)


def knot_table():
    return [
        ("bowline", bowline),
        ("clove hitch", clove_hitch),
        ("square knot", square_knot),
        ("figure eight", figure_eight),
        ("sheet bend", sheet_bend),
        ("timber hitch", timber_hitch),
        ("taut line hitch", taut_line_hitch),
        ("round turn", round_turn),
        ("fisherman knot", fisherman_knot),
        ("carrick bend", carrick_bend),
    ]


def strengths(line):
    return [knot(line) for _name, knot in knot_table()]


def format_strength(value):
    if float(value).is_integer():
        return str(int(value))
    return "{0:.2f}".format(value)


def report(line):
    rows = ["Line strength: {0} lb".format(format_strength(validate_line(line)))]
    for name, value in zip([n for n, _f in knot_table()], strengths(line)):
        rows.append("{0:<16} {1:>8} lb".format(name, format_strength(value)))
    weakest = min(strengths(line))
    rows.append("Weakest retention: {0} lb".format(format_strength(weakest)))
    return "\n".join(rows)


def main():
    print(strengths(100))
    print(report(2400))


if __name__ == "__main__":
    main()

