def validate_unit(unit):
    if not isinstance(unit, (int, float)) or isinstance(unit, bool):
        raise TypeError("unit must be a number of milliseconds")
    if unit <= 0:
        raise ValueError("unit must be a positive number of milliseconds")
    return unit


def dot(unit):
    return unit * 1


def dash(unit):
    return unit * 3


def intra_character_gap(unit):
    return unit * 1


def short_gap(unit):
    return unit * 3


def medium_gap(unit):
    return unit * 7


def long_gap(unit):
    return unit * 10


def extra_long_gap(unit):
    return unit * 14


def prosign_gap(unit):
    return unit * 5


def word_gap(unit):
    return unit * 7


def sentence_gap(unit):
    return unit * 15


def element_functions():
    return [
        dot,
        dash,
        intra_character_gap,
        short_gap,
        medium_gap,
        long_gap,
        extra_long_gap,
        prosign_gap,
        word_gap,
        sentence_gap,
    ]


def timing(unit):
    validate_unit(unit)
