def validate_input(n):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("factorial is defined for integers only, got %r" % (n,))
    if n < 0:
        raise ValueError("factorial is undefined for negative input %d" % n)
    return n


def calculate_factorial(n):
    validate_input(n)
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def digit_sum(value):
    total = 0
    for character in str(value):
        total += int(character)
    return total


def factorial_sequence(limit):
    sequence = []
    running = 1
    for index in range(limit + 1):
        if index > 1:
            running *= index
        sequence.append(running)
    return sequence


def format_row(n, value):
    rendered = str(value)
    if len(rendered) > 20:
        rendered = rendered[:17] + "..."
    return "{:>3}! = {:<20} (digits: {:>3}, digit sum: {:>4})".format(
        n, rendered, len(str(value)), digit_sum(value)
    )


def build_table(limit):
    lines = []
    for n, value in enumerate(factorial_sequence(limit)):
        lines.append(format_row(n, value))
    return "\n".join(lines)


def parse_limit(argv):
    if len(argv) < 2:
        return 12
    try:
        limit = int(argv[1])
    except ValueError:
        raise SystemExit("usage: factorial.py [non-negative integer]")
    return validate_input(limit)


def main(argv):
    limit = parse_limit(argv)
    print(build_table(limit))
    print()
    print("calculate_factorial(0) =", calculate_factorial(0))
    print("calculate_factorial(5) =", calculate_factorial(5))
    print("calculate_factorial(%d) = %d" % (limit, calculate_factorial(limit)))


if __name__ == "__main__":
