import re
from collections import Counter

MENTION_PATTERN = re.compile(r"(?<![\w@])@([A-Za-z0-9_]+)")

def require_text(text):
    if not isinstance(text, str):
        raise TypeError("text must be a str, got %s" % type(text).__name__)
    return text


def extract_mentions(text):
    require_text(text)
    return MENTION_PATTERN.findall(text)


def unique_mentions(text):
    seen = []
    lowered = set()
    for name in extract_mentions(text):
        key = name.lower()
        if key not in lowered:
            lowered.add(key)
            seen.append(name)
    return seen


def mention_counts(text):
    return Counter(name.lower() for name in extract_mentions(text))


def strip_mentions(text):
    cleaned = MENTION_PATTERN.sub("", require_text(text))
    return re.sub(r"\s{2,}", " ", cleaned).strip()


def most_mentioned(text, limit=3):
    counts = mention_counts(text)
    ordered = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ordered[:limit]


def format_report(text):
    mentions = extract_mentions(text)
    lines = ["text: %r" % text, "mentions (%d): %s" % (len(mentions), mentions)]
    if mentions:
        lines.append("unique: %s" % unique_mentions(text))
        top = ", ".join("%s x%d" % (name, hits) for name, hits in most_mentioned(text))
        lines.append("top: %s" % top)
        lines.append("without mentions: %r" % strip_mentions(text))
    return "\n".join(lines)


def main():
    samples = [
        "Hello @user1, how are you @user2?",
        "No mentions here.",
        "@ada cc @grace and @ada again, thanks @Ada!",
        "email a@b.com is not a mention but @b_c_9 is",
    ]
