def ensure_text(value):
    """Return the value unchanged, rejecting non-string input."""
    if not isinstance(value, str):
        raise TypeError(
            "encoded input must be a string, not %s" % type(value).__name__
        )
    return value


def strip_whitespace(text):
    """Remove whitespace so encoded data may be wrapped across lines."""
    return "".join(character for character in text if not character.isspace())


def split_tokens(text):
    """Split an encoded string into (count_digits, character) pairs."""
    tokens = []
    digits = ""
    for character in text:
        if character.isdigit():
            digits += character
        else:
            tokens.append((digits, character))
            digits = ""
    if digits:
        raise ValueError("dangling count %r at end of input" % digits)
    return tokens


def parse_count(digits, character):
    """Turn the digits of one token into a positive repetition count."""
    if not digits:
        raise ValueError("missing count before %r" % character)
    count = int(digits)
    if count == 0:
        raise ValueError("zero-length run for %r" % character)
    return count


def expand_run(count, character):
    """Return the run of characters described by one token."""
    return character * count


def decode_tokens(tokens):
    """Join the expansion of every (count_digits, character) pair."""
    pieces = []
    for digits, character in tokens:
        count = parse_count(digits, character)
        pieces.append(expand_run(count, character))
    return "".join(pieces)


def run_length_decode(encoded_string):
    """Decode a run-length encoded string of the form '3A2B1C'."""
    text = strip_whitespace(ensure_text(encoded_string))
    return decode_tokens(split_tokens(text))

