import random
from collections import Counter


def validate_num_dice(num_dice):
    if isinstance(num_dice, bool) or not isinstance(num_dice, int):
        raise TypeError("num_dice must be an integer")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    return num_dice


def roll_die():
    return random.randint(1, 6)


def roll_dice(num_dice):
    return [roll_die() for _ in range(validate_num_dice(num_dice))]


def simulate_dice_sum(num_dice):
    return sum(roll_dice(num_dice))


def run_trials(num_dice, trials):
    if trials < 1:
        raise ValueError("trials must be at least 1")
    return [simulate_dice_sum(num_dice) for _ in range(trials)]


def summarize(totals):
    counts = Counter(totals)
    return {
        "trials": len(totals),
        "min": min(totals),
        "max": max(totals),
        "mean": sum(totals) / len(totals),
        "counts": dict(sorted(counts.items())),
    }


def expected_mean(num_dice):
    return validate_num_dice(num_dice) * 3.5


def format_histogram(counts, width=40):
    peak = max(counts.values())
    lines = []
    for total, count in sorted(counts.items()):
        bar = "#" * max(1, round(count * width / peak))
        lines.append("{:>3} | {:<{w}} {}".format(total, bar, count, w=width))
    return "\n".join(lines)


def format_report(num_dice, summary):
    header = "Rolling {} die/dice, {} trials".format(num_dice, summary["trials"])
    stats = "range {}-{}, mean {:.3f} (expected {:.3f})".format(
        summary["min"], summary["max"], summary["mean"], expected_mean(num_dice)
    )
    return "\n".join([header, stats, format_histogram(summary["counts"])])


