def validate_pixel(pixel):
    if not isinstance(pixel, (list, tuple)) or len(pixel) != 3:
        raise ValueError("each pixel must have exactly three channels: %r" % (pixel,))
    for channel in pixel:
        if not isinstance(channel, int) or isinstance(channel, bool):
            raise TypeError("channel values must be integers: %r" % (channel,))
        if channel < 0 or channel > 255:
            raise ValueError("channel out of range 0..255: %d" % channel)
    return tuple(pixel)


def validate_image(image_matrix):
    if not isinstance(image_matrix, (list, tuple)):
        raise TypeError("image must be a list of rows")
    widths = set()
    rows = []
    for row in image_matrix:
        if not isinstance(row, (list, tuple)):
            raise TypeError("each row must be a list of pixels")
        widths.add(len(row))
        rows.append([validate_pixel(pixel) for pixel in row])
    if len(widths) > 1:
        raise ValueError("all rows must have the same width, got %s" % sorted(widths))
    return rows


def average_channels(pixel):
    red, green, blue = pixel
    return (red + green + blue) // 3


def to_grayscale(image_matrix):
    rows = validate_image(image_matrix)
    return [[average_channels(pixel) for pixel in row] for row in rows]


def image_extremes(grayscale_image):
    values = [value for row in grayscale_image for value in row]
    if not values:
        return 0, 0
    return min(values), max(values)


