    grayscale_image = to_grayscale(image_matrix)
    low, high = image_extremes(grayscale_image)
    height = len(grayscale_image)
    width = len(grayscale_image[0]) if height else 0
    lines = ["%dx%d image, luminance range %d..%d" % (width, height, low, high)]
    for row in grayscale_image:
        lines.append(" ".join("%3d" % value for value in row))
    art = render_ascii(grayscale_image)
    if art:
        lines.append(art)
    return "\n".join(lines)


