    validate_inputs(text, keyword)
    pattern = build_pattern(keyword)
    return len(pattern.findall(normalize(text)))

def count_many(text, keywords):
    return {keyword: count_keyword_occurrences(text, keyword) for keyword in keywords}

def total_words(text):
    normalized = normalize(text)
    return len(normalized.split()) if normalized else 0

def density(text, keyword):
    words = total_words(text)
    if words == 0:
        return 0.0
    return 100.0 * count_keyword_occurrences(text, keyword) / words

def format_row(keyword, count, percent):
    return "{:<12} {:>5} {:>7.2f}%".format(keyword, count, percent)

def build_report(text, keywords):
    lines = ["{:<12} {:>5} {:>8}".format("keyword", "count", "density")]
    for keyword, count in sorted(count_many(text, keywords).items(),
                                 key=lambda item: (-item[1], item[0])):
        lines.append(format_row(keyword, count, density(text, keyword)))
    return "\n".join(lines)

def read_text(argv):
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            return handle.read()
    return "Hello world, hello Python! Python is fun, and Python is fast."

def main(argv):
    text = read_text(argv)
    keywords = argv[2:] or ["hello", "python", "java", "is fun"]
    print(build_report(text, keywords))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

