def parse_csv_line(line):
    fields = []
    current = []
    in_quotes = False
    index = 0
    while index < len(line):
        char = line[index]
        if in_quotes:
            if char == '"':
                if index + 1 < len(line) and line[index + 1] == '"':
                    current.append('"')
                    index += 1
                else:
                    in_quotes = False
            else:
                current.append(char)
        elif char == '"':
            in_quotes = True
        elif char == ',':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
        index += 1
    fields.append(''.join(current))
    return fields


def parse_csv_text(text):
    return [parse_csv_line(line) for line in text.splitlines() if line]


def normalize_row(row, width):
    trimmed = [field.strip() for field in row]
    while len(trimmed) < width:
        trimmed.append('')
    return trimmed[:width]


def build_table(text):
    rows = parse_csv_text(text)
    if not rows:
        return [], []
    header = normalize_row(rows[0], len(rows[0]))
    body = [normalize_row(row, len(header)) for row in rows[1:]]
    return header, body


def column_widths(header, body):
    widths = [len(name) for name in header]
    for row in body:
        for position, field in enumerate(row):
            widths[position] = max(widths[position], len(field))
    return widths


def format_row(row, widths):
    return ' | '.join(field.ljust(width) for field, width in zip(row, widths))


def render_table(text):
    header, body = build_table(text)
    if not header:
        return '(no data)'
    widths = column_widths(header, body)
    lines = [format_row(header, widths)]
    lines.append('-+-'.join('-' * width for width in widths))
    for row in body:
        lines.append(format_row(row, widths))
    return '\n'.join(lines)


def main():
    sample = '\n'.join([
        'fruit,color,notes',
        'apple,red,"sweet, crisp"',
        'banana,yellow,',
        'cherry,,small',
        'plum,purple',
    ])
    print(parse_csv_line('apple,banana,cherry'))
    print(parse_csv_line('one,,three'))
    print(render_table(sample))


if __name__ == '__main__':
    main()

