import sys


PASSPORT_LENGTH = 9
DIGITS = "0123456789"


def normalize_candidate(raw):
    """Strip surrounding whitespace so user-typed values can be checked."""
    if not isinstance(raw, str):
        raise TypeError("passport number must be given as a string")
    return raw.strip()


def is_valid_passport_number(number):
    """Return True when the argument is a string of exactly 9 digits."""
    if not isinstance(number, str):
        return False
    if len(number) != PASSPORT_LENGTH:
        return False
    return all(character in DIGITS for character in number)


def describe_problem(number):
    """Explain why a normalized candidate was rejected."""
    if len(number) < PASSPORT_LENGTH:
        return "too short: {} of {} characters".format(len(number), PASSPORT_LENGTH)
    if len(number) > PASSPORT_LENGTH:
        return "too long: {} of {} characters".format(len(number), PASSPORT_LENGTH)
    bad = sorted({c for c in number if c not in DIGITS})
    return "contains non-digit characters: " + " ".join(bad)


def validate_batch(candidates):
    """Check many candidates, returning (original, normalized, valid) triples."""
    results = []
    for candidate in candidates:
        normalized = normalize_candidate(candidate)
        results.append((candidate, normalized, is_valid_passport_number(normalized)))
    return results


def format_line(original, normalized, valid):
    """Render a single validation result as one report line."""
    if valid:
        return "{!r}: valid".format(original)
    return "{!r}: invalid ({})".format(original, describe_problem(normalized))


def format_report(results):
    """Join the per-candidate lines with a summary count."""
    lines = [format_line(*result) for result in results]
    accepted = sum(1 for result in results if result[2])
    lines.append("{} of {} accepted".format(accepted, len(results)))
    return "\n".join(lines)


def read_candidates(argv):
    """Take candidates from the command line, or from stdin when none given."""
    if argv:
        return argv
    return [line for line in sys.stdin.read().splitlines() if line.strip()]


def main():
    candidates = read_candidates(sys.argv[1:])
    if not candidates:
        print("no passport numbers supplied")
        return 1
    print(format_report(validate_batch(candidates)))
    return 0


if __name__ == "__main__":
    sys.exit(main())

