def validate_parameters(a, r, n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer number of terms")
    if n < 0:
        raise ValueError("n must be non-negative")
    for name, value in (("a", a), ("r", r)):
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            raise TypeError("{} must be a real number".format(name))
    return a, r, n


def geometric_series_sum(a, r, n):
    a, r, n = validate_parameters(a, r, n)
    if n == 0:
        return 0
    if r == 1:
        return a * n
    return a * (1 - r ** n) / (1 - r) if isinstance(r, float) else a * (1 - r ** n) // (1 - r)


def series_terms(a, r, n):
    a, r, n = validate_parameters(a, r, n)
    terms = []
    current = a
    for _ in range(n):
        terms.append(current)
        current = current * r
    return terms


def brute_force_sum(a, r, n):
    return sum(series_terms(a, r, n))


def format_term(value):
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value)


def format_series(a, r, n):
    terms = series_terms(a, r, n)
    if not terms:
        return "0"
    return " + ".join(format_term(term) for term in terms)


def describe(a, r, n):
    total = geometric_series_sum(a, r, n)
    expansion = format_series(a, r, n)
    return "a={0}, r={1}, n={2}: {3} = {4}".format(
        format_term(a), format_term(r), n, expansion, format_term(total)
    )


def check_consistency(a, r, n):
    closed = geometric_series_sum(a, r, n)
    direct = brute_force_sum(a, r, n)
    return abs(closed - direct) < 1e-9


def main():
    cases = [(1, 2, 3), (5, 1, 4), (3, 0.5, 4), (2, -3, 5), (7, 4, 0)]
    for a, r, n in cases:
        print(describe(a, r, n))
        if not check_consistency(a, r, n):
            print("  warning: closed form disagrees with term-by-term sum")
    try:
        geometric_series_sum(1, 2, -1)
    except ValueError as exc:
        print("rejected invalid input: {}".format(exc))


if __name__ == "__main__":
    main()

