def validate_binary(text):
    """Return the binary string stripped of surrounding spaces, or raise ValueError."""
    candidate = text.strip()
    if not candidate:
        raise ValueError("binary string must not be empty")
    for position, digit in enumerate(candidate):
        if digit not in "01":
            raise ValueError("invalid digit %r at index %d" % (digit, position))
    return candidate


def binary_to_gray(binary):
    """Convert a binary string to the equivalent Gray code string."""
    bits = validate_binary(binary)
    gray = [bits[0]]
    for previous, current in zip(bits, bits[1:]):
        gray.append("1" if previous != current else "0")
    return "".join(gray)


def gray_to_binary(gray):
    """Convert a Gray code string back to the binary string it encodes."""
    bits = validate_binary(gray)
    binary = [bits[0]]
    for bit in bits[1:]:
        binary.append("1" if binary[-1] != bit else "0")
    return "".join(binary)


def gray_sequence(width):
    """Return the Gray codes of all binary numbers of the given bit width."""
    if width < 1:
        raise ValueError("width must be at least 1")
    codes = []
    for value in range(2 ** width):
        codes.append(binary_to_gray(format(value, "0%db" % width)))
    return codes


def adjacent_differences(codes):
    """Count the differing bit positions between each pair of neighbouring codes."""
    distances = []
    for first, second in zip(codes, codes[1:]):
        distances.append(sum(1 for a, b in zip(first, second) if a != b))
    return distances


def format_row(binary):
    """Render one 'binary -> gray -> binary' line for the report."""
    gray = binary_to_gray(binary)
    return "%s -> %s -> %s" % (binary.strip(), gray, gray_to_binary(gray))


def main():
    """Print the conversion report for a few samples and a full 3-bit sequence."""
    for sample in ("000", "1011", " 1101 ", "0"):
        print(format_row(sample))
    width = 3
    codes = gray_sequence(width)
    print("gray sequence of width %d: %s" % (width, " ".join(codes)))
    distances = adjacent_differences(codes)
    if set(distances) == {1}:
        print("every neighbouring pair differs in exactly one bit")
    else:
        print("unexpected distances: %s" % distances)


main()

